  function projectProgress(p){
    const steps = PROJECT_STEP_TEMPLATES[p.type] || [];
    return steps.length ? Math.round((p.completedSteps.length/steps.length)*100) : 0;
  }
  function renderProjectsNavCount(){
    const el = $('#projects-nav-count'); if(el) el.textContent = PROJECTS.length;
  }

  /* ── Work — state ── */
  let workSearch = '', workToolFilter = 'all', workSort = 'priority';

  /* ═══ WORK — "what do you want to accomplish now" (blueprint §6 design
     principle), built from every project's own step sequence: any step that's
     unlocked-but-not-done across all projects is a piece of "Work". This is
     deliberately just a different lens over the same PROJECT_STEP_TEMPLATES
     data Projects already tracks, not a second, separate task system. ═══ */
  function collectWorkItems(){
    const items = [];
    PROJECTS.forEach(p=>{
      const steps = PROJECT_STEP_TEMPLATES[p.type] || [];
      steps.forEach((s,i)=>{
        const isDone = p.completedSteps.includes(s.key);
        const isNext = !isDone && steps.slice(0,i).every(prev=>p.completedSteps.includes(prev.key));
        if(isNext){
          const tool = s.tool ? SUITE_TOOLS.find(t=>t.id===s.tool) : null;
          items.push({project:p, step:s, tool, stepIndex:i, totalSteps:steps.length});
        }
      });
    });
    return items;
  }
  function renderWorkView(){
    const strip = $('#work-stat-strip');
    const allItems = collectWorkItems();
    const withAgent = allItems.filter(w=>w.tool).length;
    const doneProjects = PROJECTS.filter(p=>projectProgress(p)===100).length;
    const inProgressProjects = PROJECTS.filter(p=>{ const pct=projectProgress(p); return pct>0&&pct<100; }).length;

    if(strip) strip.innerHTML = `
      <div class="rs-item"><span class="rs-v">${allItems.length}</span><span class="rs-k">Open items</span></div>
      <div class="rs-item"><span class="rs-v">${withAgent}</span><span class="rs-k">Agent-ready</span></div>
      <div class="rs-item" style="cursor:pointer" onclick="gotoTop('projects')"><span class="rs-v">${inProgressProjects}</span><span class="rs-k">In progress ↗</span></div>
      <div class="rs-item" style="cursor:pointer" onclick="projFilterStatus='complete';gotoTop('projects')"><span class="rs-v">${doneProjects}</span><span class="rs-k">Complete ↗</span></div>`;
    const navChip = $('#work-nav-count'); if(navChip) navChip.textContent = allItems.length || '';

    /* tool filter chips — rebuild each time so new items are reflected */
    const toolChips = $('#work-tool-chips');
    if(toolChips){
      const toolsInWork = [...new Set(allItems.map(w=>w.tool?.id).filter(Boolean))];
      toolChips.innerHTML = `<button class="xc-filter-chip${workToolFilter==='all'?' on':''}" data-wtool="all">All agents</button>`
        + toolsInWork.map(id=>{ const t=SUITE_TOOLS.find(x=>x.id===id); return t?`<button class="xc-filter-chip${workToolFilter===id?' on':''}" data-wtool="${id}">${t.name}</button>`:'' }).join('');
      toolChips.querySelectorAll('.xc-filter-chip').forEach(b=>{
        b.onclick=()=>{ workToolFilter=b.dataset.wtool; renderWorkView(); };
      });
    }

    const workSearchEl = $('#work-search');
    if(workSearchEl && !workSearchEl.dataset.wired){
      workSearchEl.dataset.wired='1';
      workSearchEl.addEventListener('input',e=>{ workSearch=e.target.value.toLowerCase(); renderWorkView(); });
    }
    const workSortEl = $('#work-sort');
    if(workSortEl && !workSortEl.dataset.wired){
      workSortEl.dataset.wired='1'; workSortEl.value=workSort;
      workSortEl.onchange=()=>{ workSort=workSortEl.value; renderWorkView(); };
    }

    /* filter + sort */
    let items = allItems.filter(w=>{
      const byTool = workToolFilter==='all' || w.tool?.id===workToolFilter;
      const bySearch = !workSearch || w.project.name.toLowerCase().includes(workSearch)
        || w.step.title.toLowerCase().includes(workSearch)
        || (w.tool?.name||'').toLowerCase().includes(workSearch);
      return byTool && bySearch;
    });
    if(workSort==='project') items.sort((a,b)=>a.project.name.localeCompare(b.project.name));
    else if(workSort==='tool') items.sort((a,b)=>(a.tool?.name||'').localeCompare(b.tool?.name||''));
    else if(workSort==='step') items.sort((a,b)=>a.stepIndex-b.stepIndex);
    else items.sort((a,b)=>projectProgress(a.project)-projectProgress(b.project));

    const workCountLine = $('#work-count-line');
    if(workCountLine) workCountLine.textContent = items.length
      ? `${items.length} open step${items.length>1?'s':''} across ${new Set(items.map(w=>w.project.id)).size} project${new Set(items.map(w=>w.project.id)).size>1?'s':''}`
      : 'No items match this filter';

    /* Recommended action — clean featured card, not alarming amber box */
    const recommendBox = $('#work-recommend-section');
    if(recommendBox){
      const top = items.find(w=>w.tool && w.stepIndex>0) || items.find(w=>w.tool) || items[0];
      recommendBox.innerHTML = top ? `
        <div style="background:var(--raise);border:1px solid var(--line);border-radius:14px;padding:18px 20px;margin-bottom:4px;display:flex;align-items:flex-start;gap:14px;position:relative">
          <button onclick="this.closest('[style]').remove()" title="Dismiss" style="position:absolute;top:10px;right:10px;background:none;border:none;color:var(--ink-4);cursor:pointer;font-size:16px;line-height:1;padding:2px 6px;border-radius:5px;transition:color .15s" onmouseenter="this.style.color='var(--ink)'" onmouseleave="this.style.color='var(--ink-4)'">×</button>
          <div style="width:38px;height:38px;border-radius:10px;background:var(--panel);border:1px solid var(--raise-2);display:grid;place-items:center;flex:none">
            ${top.tool ? toolIco(top.tool.icon,18) : '<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M9 11l3 3L22 4"/></svg>'}
          </div>
          <div style="flex:1;min-width:0">
            <div style="font-size:10px;font-family:var(--mono);font-weight:700;letter-spacing:.08em;color:var(--ink-4);margin-bottom:5px">RECOMMENDED NEXT</div>
            <div style="font-size:14px;font-weight:700;color:var(--hi);margin-bottom:3px">${top.step.title}</div>
            <div style="font-size:12.5px;color:var(--ink-3);margin-bottom:8px">${top.project.name} · Step ${top.stepIndex+1} of ${top.totalSteps}</div>
            <div style="font-size:12px;color:var(--ink-4);line-height:1.5">${top.step.desc}</div>
          </div>
          <div style="display:flex;flex-direction:column;gap:6px;flex:none;align-self:flex-start;margin-right:24px">
            ${top.tool
              ? `<button class="um-create-btn" style="white-space:nowrap" onclick="showAIContextPreview(PROJECTS.find(p=>p.id==='${top.project.id}'),'${top.step.key}',()=>runProjectStep(PROJECTS.find(p=>p.id==='${top.project.id}'),'${top.step.key}'))">Run ${top.tool.name} ▶</button>`
              : `<button class="um-create-btn" onclick="openProjectDetail('${top.project.id}')">Open project ↗</button>`
            }
          </div>
        </div>` : '';
    }

    const list = $('#work-list'); if(!list) return;
    if(!items.length){
      list.innerHTML = `
        <div style="text-align:center;padding:60px 24px;color:var(--ink-4)">
          <svg viewBox="0 0 24 24" width="36" height="36" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" style="opacity:.3;margin-bottom:14px"><path d="M9 11l3 3L22 4"/><path d="M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11"/></svg>
          <div style="font-size:14px;font-weight:600;color:var(--ink-3);margin-bottom:6px">${workSearch||workToolFilter!=='all' ? 'No items match this filter' : 'No open work right now'}</div>
          <div style="font-size:12px;margin-bottom:18px">${workSearch||workToolFilter!=='all' ? 'Try clearing the search or filter.' : 'Every project step is either complete or waiting on a manual action.'}</div>
          ${workSearch||workToolFilter!=='all'
            ? `<button class="um-btn" onclick="workToolFilter='all';workSearch='';var s=document.getElementById('work-search');if(s)s.value='';renderWorkView()">Clear filters</button>`
            : `<button class="um-btn" onclick="gotoTop('projects')">Go to Projects ↗</button>`}
        </div>`;
      return;
    }

    list.innerHTML = items.map(w=>{
      const pct = projectProgress(w.project);
      const pctColor = pct===100 ? 'var(--emerald)' : pct>60 ? 'rgba(255,255,255,.6)' : 'rgba(255,255,255,.35)';
      const stepLabel = `Step ${w.stepIndex+1} / ${w.totalSteps}`;
      return `
        <div style="background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:0;overflow:hidden;transition:border-color .15s" onmouseenter="this.style.borderColor='var(--raise-2)'" onmouseleave="this.style.borderColor='var(--line)'">
          <!-- Card body -->
          <div style="display:flex;align-items:flex-start;gap:14px;padding:16px 18px">
            <!-- Agent icon -->
            <div style="width:36px;height:36px;border-radius:9px;background:var(--raise);border:1px solid var(--raise-2);display:grid;place-items:center;flex:none;margin-top:2px" data-tip="${w.tool?w.tool.name+' agent':'Manual step'}">
              ${w.tool ? toolIco(w.tool.icon,16) : '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M9 11l3 3L22 4"/></svg>'}
            </div>
            <!-- Content -->
            <div style="flex:1;min-width:0">
              <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:12px;flex-wrap:wrap">
                <div style="flex:1;min-width:0">
                  <div style="font-size:13.5px;font-weight:700;color:var(--hi);margin-bottom:3px">${w.step.title}</div>
                  <div style="font-size:11.5px;color:var(--ink-3);margin-bottom:8px;line-height:1.5">${w.step.desc}</div>
                  <!-- Meta row -->
                  <div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap">
                    <button style="font-size:11.5px;font-weight:600;color:var(--ink-2);background:none;border:none;padding:0;cursor:pointer;text-decoration:underline;text-underline-offset:2px;text-decoration-color:rgba(255,255,255,.2)" onclick="openProjectDetail('${w.project.id}')">${w.project.name}</button>
                    <span style="font-size:11px;color:var(--ink-4);font-family:var(--mono)">${stepLabel}</span>
                    ${w.project.environment ? `<span style="font-size:10.5px;padding:2px 8px;border-radius:5px;background:var(--raise);border:1px solid var(--raise-2);color:var(--ink-3)">${w.project.environment}</span>` : ''}
                    ${w.project.owner ? `<span style="font-size:11px;color:var(--ink-4)">· ${w.project.owner}</span>` : ''}
                  </div>
                </div>
                <!-- Single primary CTA -->
                <div style="flex:none">
                  ${w.tool
                    ? `<button class="um-create-btn" style="font-size:12px;padding:8px 16px;white-space:nowrap" onclick="showAIContextPreview(PROJECTS.find(p=>p.id==='${w.project.id}'),'${w.step.key}',()=>runProjectStep(PROJECTS.find(p=>p.id==='${w.project.id}'),'${w.step.key}'))">Run ${w.tool.name}</button>`
                    : `<button class="um-btn" style="font-size:12px;padding:8px 16px;white-space:nowrap" onclick="openProjectDetail('${w.project.id}')">Open step ↗</button>`
                  }
                </div>
              </div>
            </div>
          </div>
          <!-- Progress bar footer -->
          <div style="height:3px;background:var(--raise);position:relative">
            <div style="position:absolute;inset:0;width:${pct}%;background:${pctColor};transition:width .3s ease"></div>
          </div>
        </div>`;
    }).join('');
  }

  /* ═══ RESULTS & RUNS — every execution as a first-class Xccelera AI object,
     flattened across every tool's own run history (MOCK_RUNS) instead of
     living only inside that tool's page (blueprint §24). Read-only lens over
     the same run data Harness Learning → Tools already has. ═══ */
  function allRunsFlat(){
    try {
      const flat = [];
      TOOLS.forEach(t=>{
        (MOCK_RUNS[t.key]||[]).forEach(r=>flat.push({...r, toolKey:t.key, toolName:t.name}));
      });
      return flat;
    } catch(e){ return []; }
  }

  let resultsStatusFilter = 'all', resultsToolFilter = 'all', resultsSearchTerm = '';
  let resultsViewMode = 'list'; // 'grid' | 'list'
  let workViewMode = 'list';   // 'grid' | 'list'

  /* Wire view toggles — called at boot after DOM is ready */
  function wireViewToggles(){
    const suiteT = $$('#suite-view-toggle .vtb');
    suiteT.forEach(b=>b.onclick=()=>{ suiteViewMode=b.dataset.view; renderSuiteGrid(); });
    const resultsT = $$('#results-view-toggle .vtb');
    resultsT.forEach(b=>b.onclick=()=>{ resultsViewMode=b.dataset.view;
      resultsT.forEach(x=>x.classList.toggle('on',x===b)); renderResultsRunList(); });
    const workT = $$('#work-view-toggle .vtb');
    workT.forEach(b=>b.onclick=()=>{ workViewMode=b.dataset.view;
      workT.forEach(x=>x.classList.toggle('on',x===b));
      if(typeof renderWorkView==='function') renderWorkView(); });
  }

  function renderResultsView(){
    const all = allRunsFlat();
    const strip = $('#results-stat-strip');
    if(strip){
      const success = all.filter(r=>r.performance==='success').length;
      const partial  = all.filter(r=>r.performance==='partial').length;
      const review   = all.filter(r=>r.performance==='review').length;
      strip.innerHTML = `
        <div class="rs-item"><span class="rs-v">${all.length}</span><span class="rs-k">Total runs</span></div>
        <div class="rs-item"><span class="rs-v">${success}</span><span class="rs-k">Success</span></div>
        <div class="rs-item"><span class="rs-v">${partial}</span><span class="rs-k">Partial</span></div>
        <div class="rs-item"><span class="rs-v attention">${review}</span><span class="rs-k">Needs review</span></div>`;
    }
    const navChip = $('#results-nav-count'); if(navChip) navChip.textContent = all.length;

    /* Status filter dropdown */
    const statusBtn = $('#results-status-btn'), statusPanel = $('#results-status-panel');
    if(statusPanel && !statusPanel.dataset.wired){
      statusPanel.dataset.wired = '1';
      const statuses = [{v:'all',l:'All'},{v:'success',l:'Success'},{v:'partial',l:'Partial'},{v:'review',l:'Needs review'}];
      statusPanel.innerHTML = statuses.map(s=>`<label class="ms-option"><input type="radio" name="results-status" value="${s.v}" ${resultsStatusFilter===s.v?'checked':''}> ${s.l}</label>`).join('');
      statusPanel.querySelectorAll('input').forEach(inp=>inp.onchange=()=>{
        resultsStatusFilter=inp.value;
        statusBtn.textContent=`Status: ${inp.parentElement.textContent.trim()} ▾`;
        statusPanel.hidden=true; renderResultsRunList();
      });
      statusBtn.onclick = (e)=>{ e.stopPropagation(); statusPanel.hidden = !statusPanel.hidden; };
    }

    /* Tool filter dropdown */
    const toolBtn = $('#results-tool-btn'), toolPanel = $('#results-tool-panel');
    if(toolPanel && !toolPanel.dataset.wired){
      toolPanel.dataset.wired = '1';
      toolPanel.innerHTML = `<label class="ms-option"><input type="radio" name="results-tool" value="all" checked> All tools</label>` +
        TOOLS.map(t=>`<label class="ms-option"><input type="radio" name="results-tool" value="${t.key}"> ${t.name}</label>`).join('');
      toolPanel.querySelectorAll('input').forEach(inp=>inp.onchange=()=>{
        resultsToolFilter=inp.value;
        toolBtn.textContent=`Tool: ${inp.parentElement.textContent.trim()} ▾`;
        toolPanel.hidden=true; renderResultsRunList();
      });
      toolBtn.onclick = (e)=>{ e.stopPropagation(); toolPanel.hidden = !toolPanel.hidden; };
    }

    /* Search */
    const searchInput = $('#results-search');
    if(searchInput && !searchInput.dataset.wired){
      searchInput.dataset.wired = '1';
      searchInput.addEventListener('input', e=>{ resultsSearchTerm = e.target.value.toLowerCase(); renderResultsRunList(); });
    }

    renderResultsRunList();
  }
  function renderResultsRunList(){
    const list = $('#results-run-list'); if(!list) return;
    const perfClass = (p) => { try { return PERF_CLASS[p]||''; } catch(e){ return ''; } };
    let runs = allRunsFlat();
    if(resultsStatusFilter!=='all') runs = runs.filter(r=>r.performance===resultsStatusFilter);
    if(resultsToolFilter!=='all') runs = runs.filter(r=>r.toolKey===resultsToolFilter);
    if(resultsSearchTerm) runs = runs.filter(r=>(r.project||'').toLowerCase().includes(resultsSearchTerm) || r.id.toLowerCase().includes(resultsSearchTerm));
    if(!runs.length){ list.innerHTML = `<div class="empty">No runs match this filter/search.</div>`; return; }
    if(resultsViewMode==='grid'){
      list.style.cssText='display:grid;grid-template-columns:repeat(3,1fr);gap:14px';
      list.innerHTML = runs.slice(0,60).map(r=>`
        <div class="card" data-run-id="${r.id}" style="gap:10px">
          <div style="display:flex;align-items:center;justify-content:space-between;gap:8px">
            <span style="font-size:11px;font-weight:700;color:var(--indigo-bright);font-family:var(--mono)">${r.toolName}</span>
            <span class="pill ${perfClass(r.performance)}" style="font-size:9.5px"><i></i>${r.performanceLabel}</span>
          </div>
          <div style="font-size:12px;color:var(--ink-3)">${r.id} · ${r.startedAt}</div>
          <p style="font-size:12px;color:var(--ink-2);line-height:1.5;overflow:hidden;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical">${r.overview}</p>
          <div style="display:flex;gap:12px;border-top:1px solid var(--line-soft);padding-top:8px;margin-top:auto">
            <div style="font-size:11px;color:var(--ink-4)">${r.timeTaken}</div>
            <div style="font-size:11px;color:var(--ink-4)">${r.tokens.toLocaleString()} tokens</div>
            <div style="font-size:11px;color:var(--ink-4)">${r.cost}</div>
          </div>
        </div>`).join('');
    } else {
      list.style.cssText='';
      list.innerHTML = runs.slice(0,60).map(r=>`
        <div class="runcard" data-run-id="${r.id}">
          <div class="run-top">
            <div class="rl">
              <span class="rid">${r.toolName} · ${r.id}</span>
              <span class="rdate">${r.startedAt}</span>
              <span class="rtrigger">${r.trigger}</span>
            </div>
            <span class="pill ${perfClass(r.performance)}"><i></i>${r.performanceLabel}</span>
          </div>
          <div class="run-meta">
            <div class="rm"><div class="k">Time taken</div><div class="v">${r.timeTaken}</div></div>
            <div class="rm"><div class="k">Tokens used</div><div class="v">${r.tokens.toLocaleString()}</div></div>
            <div class="rm"><div class="k">Estimated cost</div><div class="v">${r.cost}</div></div>
            ${r.project?`<div class="rm"><div class="k">Project</div><div class="v proj">${r.project}</div></div>`:''}
          </div>
          <div class="run-content">
            <p class="overview">${r.overview}</p>
            ${r.memoryApplied?`<div class="insight"><span class="ii"><svg viewBox="0 0 24 24" fill="none" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M9 18h6M10 22h4M12 2a7 7 0 0 0-4 12.7c.5.4.9 1 .9 1.6V17h6.2v-.7c0-.6.4-1.2.9-1.6A7 7 0 0 0 12 2Z"/></svg></span><div class="it"><b>Harness Memory applied (${r.memoryApplied.count})</b> — ${r.memoryApplied.note}</div></div>`:''}
          </div>
        </div>`).join('');
    }
  }

