function uixEl(html){ const d=document.createElement('div'); d.innerHTML=html.trim(); return d.firstChild; }
function uixEscapeHtml(s){ return String(s).replace(/[&<>]/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c])); }

