function uixIsDraftValid(){
  const d = uixDraft;
  if(!d.name || !d.type || !d.technology) return false;
  if(d.type==='figma') return !!(d.figmaFileUrl && d.accessToken);
  if(d.type==='business-logic') return !!d.businessLogic;
  if(d.type==='both') return !!(d.figmaFileUrl && d.accessToken && d.businessLogic);
  return false;
}

