  window.abxCloseCustomModal = abxCloseCustomModal;
  window.abxDeployNewOTA = abxDeployNewOTA;
  window.abxIncrementStepsResults = abxIncrementStepsResults;
  window.abxLoadHistoryPreset = abxLoadHistoryPreset;
  window.abxOpenHistoryMenu = abxOpenHistoryMenu;
  window.abxMoveScreen = abxMoveScreen;
  window.abxNavigateSimulator = abxNavigateSimulator;
  window.abxNavigateSimulatorResults = abxNavigateSimulatorResults;
  window.abxRemoveDependency = abxRemoveDependency;
  window.abxRemoveFlow = abxRemoveFlow;
  window.abxRemoveScreen = abxRemoveScreen;
  window.abxResetFormFields = abxResetFormFields;
  window.abxSelectPlatform = abxSelectPlatform;
  window.abxSelectProjectType = abxSelectProjectType;
  window.abxSendHelpQuery = abxSendHelpQuery;
  window.abxSetSimulatedTemplate = abxSetSimulatedTemplate;
