  const settingsSectionIndex = {};

  /* ── Settings page render shims ──────────────────────────────────────────
     Each of the four Settings nav items now has its own top-level page.
     These shims wire each gotoTop() call to the existing underlying
     renderer (renderSettingsTabs/Body, renderProfile, renderPolicyPage,
     renderHelpPage) so the real content still displays. ──────────────── */
  function renderConfigPage(){
    renderSettingsTabs('apix');
    renderSettingsBody('apix');
  }
  function renderHelpPage(){
    if(typeof renderFaqGrid==='function') renderFaqGrid();
  }
  function renderPolicyPage(){
    if(typeof renderPolicyByTool==='function') renderPolicyByTool();
  }
  function renderProfilePage(){
    renderProfile();
  }
  function renderSettingsTabs(activeId){
    $('#st-tool-tabs').innerHTML = SUITE_TOOLS.map(t=>`
      <button class="st-tool-tab${t.id===activeId?' on':''}" data-stid="${t.id}">
        ${toolIco(t.icon,15)}<span>${t.name}</span>
      </button>`).join('');
    $$('#st-tool-tabs .st-tool-tab').forEach(b=>b.onclick=()=>renderSettingsBody(b.dataset.stid));
  }

  function renderSettingsBody(id){
    $$('#st-tool-tabs .st-tool-tab').forEach(b=>b.classList.toggle('on', b.dataset.stid===id));
    const t = SUITE_TOOLS.find(x=>x.id===id);
    const cfg = TOOL_SETTINGS[id] || {settingsSections:[],helpItems:[],note:'No settings data mapped yet for this tool.'};

    let leftCol = `
      <div>
        <div class="st-card st-title-card">
          <div class="st-title-row"><span class="st-title-ic">${toolIco(t.icon,18)}</span><div><h4>${t.name} — Settings</h4><div class="st-source-tag" style="display:block">${cfg.source||''}</div></div></div>
          ${cfg.settingsSections.length ? `<div class="st-sec-tabs" role="tablist">${cfg.settingsSections.map((s,i)=>`<div class="st-nav-item" role="tab" tabindex="0" data-secanchor="st-sec-${id}-${i}">${s.title}</div>`).join('')}</div>` : '<div class="st-note-box" style="margin-top:12px">No dedicated settings section in this agent.</div>'}
        </div>
        ${cfg.settingsSections.map((s,i)=>`
          <div class="st-card st-settings-section" id="st-sec-${id}-${i}">
            <div class="st-settings-section-title">${s.title}</div>
            ${s.items.map(o=>{
              if(o.type==='text'){
                return `<div class="st-field-row"><div class="tt">${o.t}</div><div class="st-field-val">${o.d}</div></div>`;
              }
              return `<div class="st-toggle-row"><div><div class="tt">${o.t}</div><div class="td">${o.d}</div></div><div class="st-mini-switch${o.on?' on':''}" onclick="this.classList.toggle('on')"></div></div>`;
            }).join('')}
          </div>`).join('')}`;
    if(cfg.note){
      leftCol += `<div class="st-card"><div class="st-note-box">${cfg.note}</div></div>`;
    }
    leftCol += '</div>';

    $('#st-body').innerHTML = leftCol;
    $$('#st-body .st-nav-item[data-secanchor]').forEach((el,i)=>{
      el.onclick=()=>{
        $$('#st-body .st-nav-item[data-secanchor]').forEach(n=>n.classList.remove('active'));
        el.classList.add('active');
        const target = document.getElementById(el.dataset.secanchor);
        if(target) target.scrollIntoView({behavior:'smooth', block:'start'});
      };
      if(i===0) el.classList.add('active');
    });
  }

  renderSettingsTabs('apix');
  renderSettingsBody('apix');

  /* ═══ SETTINGS / HELP / POLICY — top-level tab switch ═══ */
  function gotoSTH(view, focusToolId){
    /* Each section is now its own top-level nav page rather than a tab —
       redirect to the matching page and handle any deep-link context. */
    const pageMap = {settings:'config', help:'help', policy:'policy', profile:'profile'};
    gotoTop(pageMap[view] || view);
    if(view==='help' && focusToolId){
      const tool = SUITE_TOOLS.find(x=>x.id===focusToolId);
      if(tool){ setTimeout(()=>{ const inp=$('#rag-input'); if(inp){inp.value=tool.name; runRagSearch(tool.name);} },50); }
    }
    if(view==='policy' && focusToolId){
      setTimeout(()=>{
        const el = document.getElementById('policy-group-'+focusToolId);
        if(el){ el.scrollIntoView({behavior:'smooth', block:'start'}); el.classList.add('flash'); setTimeout(()=>el.classList.remove('flash'),1200); }
      }, 80);
    }
  }
  $$('#sth-tabs .sth-tab').forEach(b=>b.onclick=()=>gotoSTH(b.dataset.sth));

  /* ═══ HELP & SUPPORT — suite-wide RAG search hub ═══ */
  function getAllHelpItems(){
    const out=[];
    Object.keys(TOOL_SETTINGS).forEach(id=>{
      const tool = SUITE_TOOLS.find(x=>x.id===id);
      const toolColor = tool ? TOOL_ICON_COLOR[tool.icon] : 'var(--indigo-bright)';
      (TOOL_SETTINGS[id].helpItems||[]).forEach(h=>out.push(Object.assign({},h,{toolId:id, toolName:tool?tool.name:id, toolColor})));
    });
    return out;
  }

  function renderFaqGrid(){
    const items = getAllHelpItems();
    $('#rag-faq-grid').innerHTML = items.map(h=>`
      <div class="rag-faq-item" data-q="${h.t.replace(/"/g,'&quot;')}" style="--tool-c:${h.toolColor}">
        <div class="fq-top"><span class="fq-ic" style="background:${h.toolColor}26;border-color:${h.toolColor}59">${h.ic}</span><span class="fq-src" style="color:${h.toolColor};background:${h.toolColor}1f">${h.toolName}</span></div>
        <div class="fq-t">${h.t}</div>
        <div class="fq-d">${h.d}</div>
      </div>`).join('');
    $$('#rag-faq-grid .rag-faq-item').forEach(el=>el.onclick=()=>{ $('#rag-input').value = el.dataset.q; runRagSearch(el.dataset.q); });
  }

  function runRagSearch(query){
    const q = (query||'').trim();
    if(!q){ $('#rag-answer').innerHTML=''; return; }
    const items = getAllHelpItems();
    const qLower = q.toLowerCase();
    const qWords = qLower.split(/\W+/).filter(w=>w.length>2);
    let best=null, bestScore=0;
    items.forEach(h=>{
      const hay = (h.t+' '+h.d+' '+h.toolName).toLowerCase();
      let score=0;
      qWords.forEach(w=>{ if(hay.includes(w)) score++; });
      if(hay.includes(qLower)) score+=3;
      if(score>bestScore){ bestScore=score; best=h; }
    });
    if(best && bestScore>0){
      $('#rag-answer').innerHTML = `<div class="rag-answer-card">
        <div class="ra-q">You asked</div>
        <div class="ra-a"><b>${best.t}.</b> ${best.d}</div>
        <div class="ra-src">📄 Retrieved from: ${best.toolName} → Help &amp; Support</div>
      </div>`;
    } else {
      $('#rag-answer').innerHTML = `<div class="rag-answer-card"><div class="ra-q">You asked</div><div class="rag-no-match">No exact match found across the suite's knowledge base yet. Try a broader term, or browse the frequently asked questions below.</div></div>`;
    }
  }
  $('#rag-go').onclick = ()=>runRagSearch($('#rag-input').value);
  $('#rag-input').addEventListener('keydown', e=>{ if(e.key==='Enter') runRagSearch(e.target.value); });
  renderFaqGrid();

  /* ═══ POLICY & DOCUMENTS — suite-wide, grouped by tool ═══ */
  function getAllPolicyGroups(){
    const out=[];
    Object.keys(TOOL_SETTINGS).forEach(id=>{
      const cfg = TOOL_SETTINGS[id];
      if(cfg.policy && cfg.policy.length){
        const tool = SUITE_TOOLS.find(x=>x.id===id);
        out.push({toolId:id, toolName:tool?tool.name:id, toolIcon:tool?tool.icon:null, items:cfg.policy});
      }
    });
    return out;
  }

  function renderPolicyByTool(){
    $('#policy-by-tool').innerHTML = getAllPolicyGroups().map(g=>`
      <div class="st-card" id="policy-group-${g.toolId}">
        <h4>${toolIco(g.toolIcon,16)} ${g.toolName}</h4>
        ${g.items.map(p=>`<div class="st-policy-item"><span class="pi">${p.ic}</span><div><div class="pt">${p.t}</div><div class="ps">${p.d}</div></div></div>`).join('')}
      </div>`).join('');
  }
  renderPolicyByTool();

  /* ═══ MY PROFILE ═══ */
  function initialsFrom(name){ return name.trim().split(/\s+/).map(w=>w[0]).slice(0,2).join('').toUpperCase(); }

