  function exI(n,s){ return `<svg class="exi" viewBox="0 0 24 24" ${s?`style="width:${s}px;height:${s}px"`:''} fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round">${EX_I[n]||''}</svg>`; }
  const exEsc = s=>String(s==null?'':s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
  const exDate = d=>new Date(d+'T00:00:00').toLocaleDateString('en-GB',{month:'short',day:'numeric',year:'numeric'});
  function exToast(m){ if(typeof showToast==='function') showToast(m); }
  function exCanEdit(v){ return !SESSION.user || canEditView(v); }
  function exKpi(ic,tone,big,label,sub,extra){ return `<div class="ex-kpi"><span class="ex-kpi-ic ${tone}">${exI(ic,22)}</span><div class="ex-kpi-t"><div class="ex-kpi-big">${big}${extra||''}</div><div class="ex-kpi-l">${label}</div><div class="ex-kpi-s">${sub}</div></div></div>`; }
  function exHead(title,sub,btns){ return `<div class="ex-head"><div><h2>${title}</h2><p>${sub}</p></div><div class="ex-head-btns">${btns||''}</div></div>`; }
  function exBtn(label,ic,cls,id,attrs){ return `<button type="button" class="ex-btn ${cls||''}" ${id?`id="${id}"`:''} ${attrs||''}>${ic?exI(ic,15):''}${label}</button>`; }
  function exModal(title,sub,body,foot,onMount){
    const b=document.createElement('div'); b.className='um-modal-backdrop';
    b.innerHTML=`<div class="um-modal ex-modal"><h3>${title}</h3>${sub?`<div class="sub">${sub}</div>`:''}<div class="ex-modal-b">${body}</div><div class="um-modal-foot">${foot||'<button class="um-btn primary" data-close>Close</button>'}</div></div>`;
    document.body.appendChild(b);
    const close=()=>b.remove();
    b.addEventListener('click',e=>{ if(e.target===b||e.target.closest('[data-close]')) close(); });
    if(onMount) onMount(b,close);
    return b;
  }
  function exDownload(name,text,type){ try{ const a=document.createElement('a'); a.href=URL.createObjectURL(new Blob([text],{type:type||'text/plain'})); a.download=name; document.body.appendChild(a); a.click(); setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove();},400); exToast('Downloaded '+name); }catch(e){ exToast('Download is not available here'); } }
  function exSwitch(on,attrs,locked){ return `<span class="ex-sw${on?' on':''}${locked?' locked':''}" ${attrs||''} role="switch" aria-checked="${on}"></span>`; }
  function exDonut(segs,center,sub,size){
    let acc=0; const total=segs.reduce((a,s)=>a+s.v,0)||1;
    const stops=segs.map(s=>{const a=acc/total*360; acc+=s.v; return `${s.c} ${a}deg ${acc/total*360}deg`;}).join(',');
    return `<div class="ex-donut" style="--sz:${size||150}px;background:conic-gradient(${stops})"><div><b>${center}</b><span>${sub}</span></div></div>`;
  }
  /* close any open ⋯ menu on outside click */
  document.addEventListener('click',e=>{ if(!e.target.closest('.ex-menu-wrap')) $$('.ex-menu.open').forEach(m=>m.classList.remove('open')); });

  /* ─────────────── USERS & ROLES ─────────────── */
  const UX = {detail:null, tab:'all', q:'', dept:'all', role:'all', status:'all', page:1, per:12, sel:null, ptab:'details', checked:new Set()};
  const STATUS_LABEL = {approved:'Active', pending:'Pending', suspended:'Suspended'};
  function uxAvatar(u,big){ const hue=[...u.name].reduce((a,c)=>a+c.charCodeAt(0),0)%360; return `<span class="ex-av${big?' big':''}" style="--h:${hue}">${initials(u.name)}</span>`; }
  function uxLic(u){ const l=LIC_TYPES[u.license]||LIC_TYPES.workstation; return `<span class="ex-lt ${l.cls}">${l.label}</span>`; }
  function uxStatus(s){ return `<span class="ex-st st-${s}">${s==='approved'?exI('check',11):s==='pending'?exI('clock',11):exI('x',11)}${STATUS_LABEL[s]||s}</span>`; }
  function uxPerms(u){
    const rs = userRoles(u), any = (fn)=>rs.some(r=>fn(ROLE_DEF[r]));
    return [
      ['Access Xccelera Platform Studio', any(d=>!!d.access.studio)],
      ['Access Enterprise Admin Portal', any(d=>!!d.access.enterprise)],
      ['Use AI Agents', rs.some(r=>r!=='org-admin' && ROLE_DEF[r].access.studio)],
      ['Create and manage projects', rs.some(r=>['cto','pm'].includes(r))],
      ['Work in assigned projects', rs.some(r=>['cto','pm','developer'].includes(r))],
      ['Access organization knowledge base', rs.some(r=>!!ROLE_DEF[r].access.studio)],
      ['Manage team members', rs.some(r=>['org-admin','cto'].includes(r))],
      ['Manage subscriptions & licensing', rs.includes('org-admin')]
    ];
  }
  function uxActivity(u){
    const base = u.license==='admin' ? ['Updated role assignments','Reviewed license allocation','Signed in to Enterprise Admin Portal'] :
      u.license==='viewer' ? ['Viewed organization insights','Opened project report','Signed in to Xccelera Platform Studio'] :
      ['Logged in to Xccelera Studio','Ran VulnerabilityX','Updated project documentation'];
    const when = [u.last==='Never'?'—':u.last,'3 hours ago','5 hours ago'];
    return u.status==='pending' ? [['Invitation sent — waiting for approval','Today']] : base.map((t,i)=>[t,when[i]]);
  }
  function uxFiltered(){
    const q=UX.q.trim().toLowerCase();
    return USERS.filter(u=>(UX.tab==='all'||u.license===UX.tab)
      &&(UX.dept==='all'||u.dept===UX.dept)&&(UX.role==='all'||hasRole(u,UX.role))&&(UX.status==='all'||u.status===UX.status)
      &&(!q||u.name.toLowerCase().includes(q)||u.email.toLowerCase().includes(q)||(u.dept||'').toLowerCase().includes(q)||(u.title||'').toLowerCase().includes(q)));
  }
  function entRenderUsers(){
    const root=$('#ent-users'); if(!root) return;
    if(UX.create){ udCreatePage(root); return; }
    if(UX.edit){ const eu=USERS.find(x=>x.id===UX.edit); if(eu){ udEditPage(root,eu,UX.editFocus); return; } UX.edit=null; }
    if(UX.detail){ const du=USERS.find(x=>x.id===UX.detail); if(du){ udRender(root,du); return; } UX.detail=null; }
    const cnt = t=>USERS.filter(u=>u.license===t).length;
    const list = uxFiltered(), pages=Math.max(1,Math.ceil(list.length/UX.per)); if(UX.page>pages) UX.page=pages;
    const rows = list.slice((UX.page-1)*UX.per, UX.page*UX.per);
    const depts = [...new Set(USERS.map(u=>u.dept))].sort();
    const ed = exCanEdit('users');
    const sel = USERS.find(u=>u.id===UX.sel);
    const pgBtns = (()=>{ const out=[]; const add=p=>out.push(`<button class="ex-pg${p===UX.page?' on':''}" data-pg="${p}">${p}</button>`);
      if(pages<=7){ for(let p=1;p<=pages;p++) add(p); } else { [1,2,3].forEach(add); if(UX.page>4&&UX.page<pages-2){ out.push('<span class="ex-pg-gap">…</span>'); add(UX.page); } out.push('<span class="ex-pg-gap">…</span>'); add(pages); }
      return out.join(''); })();
    root.innerHTML = exHead('Users &amp; Roles','Manage your team members, assign roles, and control access across the Xccelera AI Platform.',
        exBtn('Import Users','upload','ex-edit','ux-import')+exBtn('Export Users','download','','ux-export')+exBtn('Invite Users','plus','primary ex-edit','ux-invite'))
      + `<div class="ex-kpis">
          ${exKpi('idcard','t-blue',USERS.length,'Total Users',`${cnt('workstation')} workstation + ${cnt('viewer')+cnt('admin')} viewer/admin`,'<span class="ex-up">↑ 12%</span>')}
          ${exKpi('users','t-green',cnt('workstation'),'Workstation Users','Developers, QA, BA, etc.')}
          ${exKpi('eye','t-violet',cnt('viewer'),'Viewer Users','Executives, Finance, PMs')}
          ${exKpi('badge','t-amber',cnt('admin'),'Admin Users','Organization &amp; IT Admins')}
        </div>
        <div class="ex-split${sel?' has-side':''}">
          <div class="ex-card ex-main">
            <div class="ex-tabs">${[['all','All Users',USERS.length],['workstation','Workstation Users',cnt('workstation')],['viewer','Viewer Users',cnt('viewer')],['admin','Admin Users',cnt('admin')]].map(t=>`<button class="ex-tab${UX.tab===t[0]?' on':''}" data-tab="${t[0]}">${t[1]} (${t[2]})</button>`).join('')}</div>
            <div class="ex-toolbar">
              <label class="ex-search">${exI('search',15)}<input id="ux-q" placeholder="Search users by name, email or department…" value="${exEsc(UX.q)}"></label>
              <select class="ex-sel" id="ux-dept"><option value="all">All Departments</option>${depts.map(d=>`<option${UX.dept===d?' selected':''}>${d}</option>`).join('')}</select>
              <select class="ex-sel" id="ux-role"><option value="all">All Roles</option>${USER_ROLES.map(r=>`<option value="${r.value}"${UX.role===r.value?' selected':''}>${r.label}</option>`).join('')}</select>
              <select class="ex-sel" id="ux-status"><option value="all">All Statuses</option>${Object.keys(STATUS_LABEL).map(s=>`<option value="${s}"${UX.status===s?' selected':''}>${STATUS_LABEL[s]}</option>`).join('')}</select>
              ${(UX.q||UX.dept!=='all'||UX.role!=='all'||UX.status!=='all')?exBtn('Clear Filters','x','ghost','ux-clear'):''}
            </div>
            <div class="ex-table-wrap"><table class="ex-table ux-table">
              <thead><tr><th class="cb"><input type="checkbox" id="ux-all"${rows.length&&rows.every(u=>UX.checked.has(u.id))?' checked':''}></th><th>Name</th><th class="c-email">Email</th><th class="c-dept">Department</th><th>Role</th><th>License Type</th><th>Status</th><th class="c-last">Last Login</th><th class="r">Actions</th></tr></thead>
              <tbody>${rows.map(u=>`<tr class="${u.id===UX.sel?'sel':''}" data-uid="${u.id}">
                <td class="cb"><input type="checkbox" data-ck="${u.id}"${UX.checked.has(u.id)?' checked':''}></td>
                <td><div class="ex-who">${uxAvatar(u)}<b>${exEsc(u.name)}</b>${u.you?'<small>you</small>':''}</div></td>
                <td class="mut c-email">${exEsc(u.email)}</td><td class="mut c-dept">${exEsc(u.dept)}</td><td>${exEsc(u.title)}</td>
                <td>${uxLic(u)}</td><td>${uxStatus(u.status)}</td><td class="mut c-last">${exEsc(u.last)}</td>
                <td class="r"><div class="ex-menu-wrap"><button class="ex-dots" data-menu="${u.id}" aria-label="Actions">${exI('dots',16)}</button>
                  <div class="ex-menu" id="ux-menu-${u.id}">
                    <button data-a="view" data-uid="${u.id}">${exI('eye',14)}View Details</button>
                    ${u.you?'':`<button class="ex-edit" data-a="roles" data-uid="${u.id}">${exI('shield',14)}Edit Roles</button>
                    <button class="ex-edit" data-a="license" data-uid="${u.id}">${exI('idcard',14)}Change License</button>
                    ${u.status==='approved'?`<button class="ex-edit" data-a="suspend" data-uid="${u.id}">${exI('lock',14)}Suspend User</button>`:`<button class="ex-edit" data-a="approve" data-uid="${u.id}">${exI('check',14)}Approve User</button>`}
                    <button class="ex-edit danger" data-a="delete" data-uid="${u.id}">${exI('x',14)}Remove User</button>`}
                  </div></div></td></tr>`).join('') || `<tr><td colspan="9" class="ex-empty">No users match these filters.</td></tr>`}</tbody></table></div>
            <div class="ex-pager"><span class="mut">Showing ${list.length?((UX.page-1)*UX.per+1):0}–${Math.min(UX.page*UX.per,list.length)} of ${list.length} users${UX.checked.size?` · <b>${UX.checked.size} selected</b>`:''}</span>
              <div class="ex-pgs"><button class="ex-pg" data-pg="${UX.page-1}" ${UX.page<=1?'disabled':''} aria-label="Previous">${exI('arrowL',14)}</button>${pgBtns}<button class="ex-pg flip" data-pg="${UX.page+1}" ${UX.page>=pages?'disabled':''} aria-label="Next">${exI('arrowL',14)}</button></div>
              <select class="ex-sel sm" id="ux-per">${[12,24,48].map(n=>`<option value="${n}"${UX.per===n?' selected':''}>${n} per page</option>`).join('')}</select></div>
          </div>
          ${sel?uxSide(sel,ed):''}
        </div>`;
    uxBind(root); exNavCounts();
  }
  function uxSide(u,ed){
    const rs=userRoles(u);
    const tabs=[['details','Details'],['roles','Roles &amp; Permissions'],['projects','Projects'],['activity','Activity']];
    let body='';
    if(UX.ptab==='details') body=`<div class="ex-kv">
        <div><span>Email</span><b>${exEsc(u.email)} <button class="ex-ic-btn" data-copy="${exEsc(u.email)}" aria-label="Copy email">${exI('copy',13)}</button></b></div>
        <div><span>Department</span><b>${exEsc(u.dept)}</b></div>
        <div><span>Job Title</span><b>${exEsc(u.title)}</b></div>
        <div><span>License Type</span><b>${uxLic(u)} ${u.you?'':exBtn('Change','','sm ex-edit','ux-chg-lic')}</b></div>
        <div><span>Manager</span><b>${exEsc(u.manager)}</b></div>
        <div><span>Phone</span><b>${exEsc(u.phone)}</b></div>
        <div><span>Location</span><b>${exEsc(u.location)}</b></div>
        <div><span>Date Joined</span><b>${exDate(u.joined)}</b></div></div>`;
    if(UX.ptab==='projects'){ const ps=(typeof PROJECTS!=='undefined'?PROJECTS:[]).slice(0, u.license==='admin'?3:u.license==='viewer'?2:4);
      body = rs.some(r=>ROLE_DEF[r].access.studio) ? `<div class="ex-plist">${ps.map(p=>`<div><span class="ex-pl-ic">${exI('folder',14)}</span><b>${exEsc(p.name)}</b><small>${u.license==='viewer'?'Read only':'Member'}</small></div>`).join('')}</div>` : `<div class="ex-empty">No Platform Studio access with the current roles.</div>`; }
    if(UX.ptab==='activity') body=`<div class="ex-act">${uxActivity(u).map(a=>`<div><span class="ex-act-ic">${exI('shieldok',13)}</span><b>${a[0]}</b><small>${a[1]}</small></div>`).join('')}</div>`;
    const rolesBlock=`<div class="ex-side-sec"><div class="ex-sec-h"><h4>Roles &amp; Permissions</h4>${u.you?'':exBtn('Edit Roles','edit','sm ex-edit','ux-edit-roles')}</div>
        <div class="ex-chips">${rs.map((r,i)=>`<span class="ex-rchip">${exI('shieldok',13)}${ROLE_DEF[r]?USER_ROLES.find(x=>x.value===r).label:r}${i===0?'<em>Primary</em>':''}</span>`).join('')}${(u.extra||[]).map(x=>`<span class="ex-rchip alt">${exI('book',13)}${x}</span>`).join('')}</div>
        <div class="ex-sub-h">Access Permissions</div>
        <ul class="ex-perms">${uxPerms(u).map(p=>`<li class="${p[1]?'y':'n'}">${exI(p[1]?'check':'x',11)}${p[0]}</li>`).join('')}</ul></div>`;
    return `<div class="ex-card ex-side" role="complementary" aria-label="User details">
      <div class="ex-side-top">${uxAvatar(u,true)}<div><h3>${exEsc(u.name)} ${uxStatus(u.status)}</h3><p>${exEsc(u.title)}</p></div><button class="ex-ic-btn ex-x" id="ux-close" aria-label="Close">${exI('x',15)}</button></div>
      <div class="ex-tabs sm">${tabs.map(t=>`<button class="ex-tab${UX.ptab===t[0]?' on':''}" data-ptab="${t[0]}">${t[1]}</button>`).join('')}</div>
      ${UX.ptab==='roles'?rolesBlock:`<div class="ex-side-sec">${body}</div>${UX.ptab==='details'?rolesBlock:''}`}
      ${UX.ptab!=='activity'?`<div class="ex-side-sec"><div class="ex-sec-h"><h4>Recent Activity</h4><button class="ex-link" data-ptab="activity">View All</button></div><div class="ex-act">${uxActivity(u).map(a=>`<div><span class="ex-act-ic">${exI('shieldok',13)}</span><b>${a[0]}</b><small>${a[1]}</small></div>`).join('')}</div></div>`:''}
    </div>`;
  }
  function uxLicenseModal(u){
    exModal('Change License Type',`Choose the license ${exEsc(u.name)} uses.`,
      `<div class="ex-radio">${Object.entries(LIC_TYPES).map(([k,l])=>`<label><input type="radio" name="ux-lic" value="${k}"${u.license===k?' checked':''}><span class="ex-lt ${l.cls}">${l.label}</span><small>${k==='workstation'?'Builds and runs work in Platform Studio':k==='viewer'?'Read-only dashboards and reports':'Administers the organization'}</small></label>`).join('')}</div>`,
      '<button class="um-btn" data-close>Cancel</button><button class="um-btn primary" id="ux-lic-save">Save License</button>',
      (b,close)=>{ b.querySelector('#ux-lic-save').onclick=()=>{ const v=b.querySelector('input[name="ux-lic"]:checked').value; u.license=v; close(); entRenderUsers(); exToast(u.name+' now uses a '+LIC_TYPES[v].label+' license'); }; });
  }
  function uxBind(root){
    const on=(s,ev,fn)=>{ const el=root.querySelector(s); if(el) el.addEventListener(ev,fn); };
    on('#ux-q','input',e=>{ UX.q=e.target.value; UX.page=1; const pos=e.target.selectionStart; entRenderUsers(); const i=$('#ux-q'); if(i){ i.focus(); i.setSelectionRange(pos,pos);} });
    [['#ux-dept','dept'],['#ux-role','role'],['#ux-status','status']].forEach(([s,k])=>on(s,'change',e=>{ UX[k]=e.target.value; UX.page=1; entRenderUsers(); }));
    on('#ux-per','change',e=>{ UX.per=+e.target.value; UX.page=1; entRenderUsers(); });
    on('#ux-clear','click',()=>{ Object.assign(UX,{q:'',dept:'all',role:'all',status:'all',page:1}); entRenderUsers(); });
    on('#ux-invite','click',()=>{ UX.create=true; entRenderUsers(); });
    on('#ux-import','click',()=>exModal('Import Users','Upload a CSV with name, email, department, role and license type.',
      `<label class="ex-drop">${exI('upload',22)}<b>Choose a CSV file</b><small>Columns: Name, Email, Department, Role, License Type</small><input type="file" accept=".csv" id="ux-file" hidden></label><div class="ex-file-name" id="ux-file-name"></div>`,
      '<button class="um-btn" data-close>Cancel</button><button class="um-btn primary" id="ux-imp-go">Import Users</button>',
      (b,close)=>{ const f=b.querySelector('#ux-file'); f.onchange=()=>{ b.querySelector('#ux-file-name').textContent=f.files[0]?f.files[0].name:''; };
        b.querySelector('#ux-imp-go').onclick=()=>{ if(!f.files[0]){ b.querySelector('#ux-file-name').innerHTML='<span style="color:var(--rose)">Choose a CSV file first.</span>'; return; } close(); exToast('Imported users from '+f.files[0].name+' — they start as Pending'); }; }));
    on('#ux-export','click',()=>{ const l=UX.checked.size?USERS.filter(u=>UX.checked.has(u.id)):uxFiltered();
      exDownload('users.csv',['Name,Email,Department,Role,License Type,Status,Last Login'].concat(l.map(u=>[u.name,u.email,u.dept,u.title,LIC_TYPES[u.license].label,STATUS_LABEL[u.status],u.last].map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(','))).join('\n'),'text/csv'); });
    root.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{ UX.tab=b.dataset.tab; UX.page=1; entRenderUsers(); });
    root.querySelectorAll('[data-pg]').forEach(b=>b.onclick=()=>{ if(b.disabled) return; UX.page=+b.dataset.pg; entRenderUsers(); });
    root.querySelectorAll('[data-ptab]').forEach(b=>b.onclick=()=>{ UX.ptab=b.dataset.ptab; entRenderUsers(); });
    on('#ux-close','click',()=>{ UX.sel=null; entRenderUsers(); });
    on('#ux-all','change',e=>{ const ids=[...root.querySelectorAll('[data-ck]')].map(c=>c.dataset.ck); ids.forEach(id=>e.target.checked?UX.checked.add(id):UX.checked.delete(id)); entRenderUsers(); });
    root.querySelectorAll('[data-ck]').forEach(c=>{ c.onclick=e=>e.stopPropagation(); c.onchange=()=>{ c.checked?UX.checked.add(c.dataset.ck):UX.checked.delete(c.dataset.ck); entRenderUsers(); }; });
    root.querySelectorAll('tr[data-uid]').forEach(tr=>tr.onclick=e=>{ if(e.target.closest('.ex-menu-wrap,input')) return; UX.sel=null; UX.detail=tr.dataset.uid; entRenderUsers(); const m=document.querySelector('main'); if(m) m.scrollTop=0; window.scrollTo(0,0); });
    root.querySelectorAll('[data-menu]').forEach(b=>b.onclick=e=>{ e.stopPropagation(); const m=$('#ux-menu-'+b.dataset.menu); const was=m.classList.contains('open'); $$('.ex-menu.open').forEach(x=>x.classList.remove('open')); if(!was) m.classList.add('open'); });
    root.querySelectorAll('.ex-menu [data-a]').forEach(b=>b.onclick=e=>{ e.stopPropagation(); const u=USERS.find(x=>x.id===b.dataset.uid); if(!u) return; const a=b.dataset.a;
      if(a==='view'){ UX.sel=null; UX.detail=u.id; setTimeout(()=>{ const m=document.querySelector('main'); if(m) m.scrollTop=0; window.scrollTo(0,0); },0); }
      if(a==='roles'){ UX.detail=u.id; UX.edit=u.id; UX.editFocus='roles'; entRenderUsers(); return; }
      if(a==='license'){ UX.detail=u.id; UX.edit=u.id; UX.editFocus='license'; entRenderUsers(); return; }
      if(a==='suspend'){ u.status='suspended'; exToast(u.name+' suspended'); }
      if(a==='approve'){ u.status='approved'; exToast(u.name+' approved'); }
      if(a==='delete'){ exModal('Remove User',`Remove ${exEsc(u.name)} from GlobalTech Solutions? Their license goes back to the pool.`,'','<button class="um-btn" data-close>Cancel</button><button class="um-btn primary" id="ux-del-go">Remove User</button>',(m,close)=>{ m.querySelector('#ux-del-go').onclick=()=>{ USERS.splice(USERS.indexOf(u),1); if(UX.sel===u.id) UX.sel=null; close(); entRenderUsers(); exToast(u.name+' removed'); }; }); return; }
      entRenderUsers(); });
    const sel=USERS.find(u=>u.id===UX.sel);
    on('#ux-edit-roles','click',()=>sel&&openEditUserModal(sel));
    on('#ux-chg-lic','click',()=>sel&&uxLicenseModal(sel));
    root.querySelectorAll('[data-copy]').forEach(b=>b.onclick=()=>{ try{ navigator.clipboard.writeText(b.dataset.copy); }catch(e){} exToast('Email copied'); });
  }

  /* ─────────────── SUBSCRIPTION & LICENSING ─────────────── */
  const SUB = {
    plan:'Enterprise Plan', contract:'Annual Contract', start:'2025-01-01', end:'2026-12-31',
    contractId:'XC-ENT-2025-001', value:'$ XXX,XXX / year', payment:'Wire Transfer (**** 6789)', cycle:'Annual', renewal:'2026-12-31', contact:'finance@globaltech.com',
    alloc:{workstation:{total:100,used:80}, viewer:{total:10,used:8}, admin:{total:5,used:4}},
    depts:[['Engineering','code',[50,48],[3,3],[1,1]],['Product','kanban',[15,14],[2,2],[0,0]],['QA','test',[10,9],[1,1],[0,0]],['Operations','gear',[8,6],[1,1],[1,1]],['Finance','pulse',[5,3],[2,1],[1,1]],['Executive Office','users',[2,0],[1,0],[1,1]],['Other','dots',[10,0],[0,0],[0,0]]],
    trend:{months:['Jan','Feb','Mar','Apr','May','Jun'], ws:[50,66,72,76,79,80], vw:[3,4,5,6,7,8], ad:[1,2,2,3,3,4]},
    range:'Last 30 Days', trendRange:'Last 6 Months',
    history:[['12 Jun 2026','Added 5 Workstation licenses to Engineering','Andrew Kirby'],['02 May 2026','Moved 1 Viewer license from Other to Finance','Andrew Kirby'],['18 Mar 2026','Assigned 1 Admin license to Operations','Simon Kirkwood'],['01 Jan 2025','Enterprise Plan contract started — 115 licenses','System']]
  };
  function subTotals(){ const a=SUB.alloc; const total=a.workstation.total+a.viewer.total+a.admin.total, used=a.workstation.used+a.viewer.used+a.admin.used; return {total,used,avail:total-used,pct:Math.round(used/total*100)}; }
  function entRenderLicense(){
    const root=$('#ent-license'); if(!root) return;
    const a=SUB.alloc, T=subTotals(), ed=exCanEdit('license');
    const card=(ic,tone,n,label,sub,used,total,color)=>`<div class="ex-alloc"><div class="ex-alloc-top"><span class="ex-kpi-ic ${tone}">${exI(ic,20)}</span><div><div class="ex-kpi-big">${n}</div><div class="ex-kpi-l">${label}</div><div class="ex-kpi-s">${sub}</div></div></div>
        <div class="ex-bar"><i style="width:${Math.round(used/total*100)}%;background:${color}"></i></div><div class="ex-alloc-ft"><span>${used} in use</span><span>${total-used} available</span></div></div>`;
    const D=SUB.depts, sum=i=>D.reduce((s,d)=>s+d[i][0],0), sumU=i=>D.reduce((s,d)=>s+d[i][1],0);
    const W=520,H=150,P=26, mx=100, xs=i=>P+i*((W-P*2)/5), ys=v=>H-P-(v/mx)*(H-P*2);
    const line=(arr,c)=>`<polyline fill="none" stroke="${c}" stroke-width="2.4" points="${arr.map((v,i)=>xs(i)+','+ys(v)).join(' ')}"/>${arr.map((v,i)=>`<circle cx="${xs(i)}" cy="${ys(v)}" r="3.2" fill="${c}"/>`).join('')}<rect x="${xs(5)+8}" y="${ys(arr[5])-9}" width="26" height="18" rx="5" fill="${c}"/><text x="${xs(5)+21}" y="${ys(arr[5])+4}" text-anchor="middle" font-size="10.5" font-weight="700" fill="#fff">${arr[5]}</text>`;
    root.innerHTML = exHead('Subscription &amp; Licensing','Manage your plan, licenses and usage limits. Allocate seats, monitor usage and control entitlements across your organization.',
        exBtn('Download Contract','doc','','sub-dl')+exBtn('Upgrade Plan','sparkle','primary ex-edit','sub-up'))
      + `<div class="ex-grid g-plan">
          <div class="ex-hero"><div class="ex-hero-glow"></div>
            <div class="ex-hero-l">CURRENT PLAN</div><h3>${SUB.plan} <span class="ex-st st-approved">${exI('check',11)}Active</span></h3>
            <div class="ex-hero-meta">${SUB.contract}<i></i>Start Date: ${exDate(SUB.start)}<i></i>End Date: ${exDate(SUB.end)}</div>
            <p>Designed for large organizations with advanced AI capabilities, enterprise security and dedicated support.</p>
            <div class="ex-hero-btns">${exBtn('View Plan Details','','outline','sub-details')}${exBtn('Manage Plan','','primary ex-edit','sub-manage')}</div></div>
          <div class="ex-card"><div class="ex-sec-h"><h4>Contract &amp; Billing Information</h4><button class="ex-link ex-edit" id="sub-bill-edit">Edit</button></div>
            <div class="cb-grid">${[['doc','Contract ID',SUB.contractId,1],['history','Billing Cycle',SUB.cycle],['db','Contract Value',SUB.value],['clock','Next Renewal',exDate(SUB.renewal)],['idcard','Payment Method',exEsc(SUB.payment)],['mail','Billing Contact',exEsc(SUB.contact)]].map(x=>`<div class="cb-item"><span class="cb-ic">${exI(x[0],15)}</span><div><span class="cb-l">${x[1]}</span><b class="${x[3]?'mono-ish':''}" title="${String(x[2]).replace(/"/g,'')}">${x[2]}</b></div></div>`).join('')}</div></div>
        </div>
        <div class="ex-grid g-main">
          <div class="ex-card"><div class="ex-sec-h"><div><h4>License Allocation</h4><p class="ex-sub">Allocate and manage different license types for your organization.</p></div>${exBtn('Edit Allocation','edit','sm ex-edit','sub-alloc')}</div>
            <div class="ex-alloc-grid">
              ${card('laptop','t-blue',a.workstation.total,'Workstation Licenses','Developers, QA, BA, etc.',a.workstation.used,a.workstation.total,'#3b82f6')}
              ${card('eye','t-violet',a.viewer.total,'Viewer Licenses','Executives, Finance, PMs',a.viewer.used,a.viewer.total,'#a78bfa')}
              ${card('gear','t-green',a.admin.total,'Admin Licenses','Organization &amp; IT Admins',a.admin.used,a.admin.total,'#34d399')}
              ${card('users','t-gray',T.total,'Total Licenses','Across all license types',T.used,T.total,'#94a3b8')}
            </div></div>
          <div class="ex-card"><div class="ex-sec-h"><h4>Overall License Usage</h4><select class="ex-sel sm" id="sub-range">${['Last 7 Days','Last 30 Days','Last 90 Days'].map(r=>`<option${SUB.range===r?' selected':''}>${r}</option>`).join('')}</select></div>
            <div class="ex-donut-row">${exDonut([{v:a.workstation.used,c:'#3b82f6'},{v:a.viewer.used,c:'#a78bfa'},{v:a.admin.used,c:'#34d399'},{v:T.avail,c:'rgba(148,163,184,.22)'}],T.pct+'%','In Use',140)}
              <ul class="ex-legend"><li><i style="background:#3b82f6"></i>Workstation<b>${a.workstation.used} / ${a.workstation.total}</b></li><li><i style="background:#a78bfa"></i>Viewer<b>${a.viewer.used} / ${a.viewer.total}</b></li><li><i style="background:#34d399"></i>Admin<b>${a.admin.used} / ${a.admin.total}</b></li></ul></div>
            <div class="ex-note">${exI('info',14)}<span>You have ${T.avail} available licenses. <button class="ex-link" data-goto-users>Invite new users</button> or reallocate existing licenses.</span></div></div>
        </div>
        <div class="ex-grid g-main">
          <div class="ex-card"><div class="ex-sec-h"><div><h4>License Breakdown by Department</h4><p class="ex-sub">View and manage license allocation across departments.</p></div></div>
            <div class="ex-table-wrap"><table class="ex-table ex-dept">
              <thead><tr><th rowspan="2">Department</th><th colspan="3">Workstation Licenses</th><th colspan="3">Viewer Licenses</th><th colspan="3">Admin Licenses</th><th rowspan="2">Total Licenses</th><th rowspan="2" class="r">Actions</th></tr>
              <tr>${'<th>Assigned</th><th>In Use</th><th>Available</th>'.repeat(3)}</tr></thead>
              <tbody>${D.map((d,i)=>`<tr><td><div class="ex-who"><span class="ex-dic d${i}">${exI(d[1],13)}</span><b>${d[0]}</b></div></td>${[2,3,4].map(k=>`<td>${d[k][0]}</td><td>${d[k][1]}</td><td>${d[k][0]-d[k][1]}</td>`).join('')}<td><b>${d[2][0]+d[3][0]+d[4][0]}</b></td><td class="r">${exBtn('Manage','','sm tint ex-edit','',`data-dept="${i}"`)}</td></tr>`).join('')}
              <tr class="tot"><td><b>Total</b></td>${[2,3,4].map(k=>`<td>${sum(k)}</td><td>${sumU(k)}</td><td>${sum(k)-sumU(k)}</td>`).join('')}<td><b>${sum(2)+sum(3)+sum(4)}</b></td><td></td></tr></tbody></table></div></div>
          <div class="ex-col">
            <div class="ex-card"><div class="ex-sec-h"><h4>Usage Trends</h4><select class="ex-sel sm" id="sub-trend">${['Last 3 Months','Last 6 Months'].map(r=>`<option${SUB.trendRange===r?' selected':''}>${r}</option>`).join('')}</select></div>
              <ul class="ex-legend row"><li><i style="background:#3b82f6"></i>Workstation</li><li><i style="background:#a78bfa"></i>Viewer</li><li><i style="background:#34d399"></i>Admin</li></ul>
              <svg class="ex-chart" viewBox="0 0 ${W+30} ${H}" role="img" aria-label="License usage trend">${[0,25,50,75,100].map(v=>`<line x1="${P}" x2="${W-P+10}" y1="${ys(v)}" y2="${ys(v)}" stroke="currentColor" stroke-opacity=".12"/><text x="${P-6}" y="${ys(v)+3}" text-anchor="end" font-size="9.5" fill="currentColor" opacity=".55">${v}</text>`).join('')}
                ${SUB.trend.months.map((m,i)=>`<text x="${xs(i)}" y="${H-6}" text-anchor="middle" font-size="9.5" fill="currentColor" opacity=".55">${m}</text>`).join('')}
                ${line(SUB.trend.ws,'#3b82f6')}${line(SUB.trend.vw,'#a78bfa')}${line(SUB.trend.ad,'#34d399')}</svg></div>
            <div class="ex-card"><h4 class="ex-h4">License Management</h4>
              <div class="ex-links">
                <button class="ex-linkrow ex-edit" data-lm="invite"><span class="ex-kpi-ic t-blue sm">${exI('users',16)}</span><div><b>Invite New Users</b><small>Send invitations and assign licenses</small></div>${exI('chevR',16)}</button>
                <button class="ex-linkrow ex-edit" data-lm="bulk"><span class="ex-kpi-ic t-blue sm">${exI('upload',16)}</span><div><b>Bulk Upload</b><small>Upload CSV to add multiple users</small></div>${exI('chevR',16)}</button>
                <button class="ex-linkrow" data-lm="history"><span class="ex-kpi-ic t-blue sm">${exI('history',16)}</span><div><b>License History</b><small>View allocation changes and audit log</small></div>${exI('chevR',16)}</button>
              </div></div>
          </div>
        </div>`;
    const on=(s,fn)=>{ const el=root.querySelector(s); if(el) el.onclick=fn; };
    on('#sub-dl',()=>exDownload('GlobalTech-Enterprise-Contract-'+SUB.contractId+'.txt',`Xccelera AI — Enterprise Contract\nContract ID: ${SUB.contractId}\nCustomer: GlobalTech Solutions\nPlan: ${SUB.plan} (${SUB.contract})\nTerm: ${exDate(SUB.start)} – ${exDate(SUB.end)}\nLicenses: ${a.workstation.total} Workstation · ${a.viewer.total} Viewer · ${a.admin.total} Admin\nBilling: ${SUB.cycle}, ${SUB.payment}\nBilling contact: ${SUB.contact}\n`));
    const planBody=`<ul class="ex-perms">${['Unlimited AI agent runs across Platform Studio','Workstation, Viewer and Admin license types','SSO (SAML 2.0 / OpenID Connect) and SCIM provisioning','Dedicated infrastructure in your region','SOC 2, ISO 27001 and GDPR compliance reporting','24/7 dedicated support with custom SLAs'].map(f=>`<li class="y">${exI('check',11)}${f}</li>`).join('')}</ul>`;
    on('#sub-details',()=>exModal(SUB.plan,`${SUB.contract} · ${exDate(SUB.start)} – ${exDate(SUB.end)}`,planBody));
    on('#sub-up',()=>exModal('Upgrade Plan','You are already on the Enterprise Plan, our highest tier. Add licenses or request custom terms instead.',planBody,'<button class="um-btn" data-close>Close</button><button class="um-btn primary" id="sub-req">Request Custom Terms</button>',(b,close)=>{ b.querySelector('#sub-req').onclick=()=>{ close(); exToast('Request sent to your Xccelera account manager'); }; }));
    on('#sub-manage',()=>allocModal());
    on('#sub-alloc',()=>allocModal());
    on('#sub-bill-edit',()=>exModal('Edit Billing Information','Changes apply from the next invoice.',
      `<div class="um-form"><div class="field"><label>Billing Contact</label><input id="sb-contact" value="${exEsc(SUB.contact)}"></div><div class="field"><label>Payment Method</label><input id="sb-pay" value="${exEsc(SUB.payment)}"></div></div>`,
      '<button class="um-btn" data-close>Cancel</button><button class="um-btn primary" id="sb-save">Save Changes</button>',(b,close)=>{ b.querySelector('#sb-save').onclick=()=>{ SUB.contact=b.querySelector('#sb-contact').value.trim()||SUB.contact; SUB.payment=b.querySelector('#sb-pay').value.trim()||SUB.payment; close(); entRenderLicense(); exToast('Billing information updated'); }; }));
    root.querySelector('#sub-range').onchange=e=>{ SUB.range=e.target.value; entRenderLicense(); };
    root.querySelector('#sub-trend').onchange=e=>{ SUB.trendRange=e.target.value; exToast('Showing '+e.target.value.toLowerCase()); };
    root.querySelectorAll('[data-goto-users]').forEach(b=>b.onclick=()=>gotoTop('users'));
    root.querySelectorAll('[data-dept]').forEach(b=>b.onclick=()=>deptModal(+b.dataset.dept));
    root.querySelectorAll('[data-lm]').forEach(b=>b.onclick=()=>{ const k=b.dataset.lm;
      if(k==='invite'){ UX.detail=null; UX.edit=null; UX.create=true; gotoTop('users'); }
      if(k==='bulk'){ gotoTop('users'); setTimeout(()=>{ const i=$('#ux-import'); if(i) i.click(); },50); }
      if(k==='history') exModal('License History','Allocation changes and audit log.',`<div class="ex-act">${SUB.history.map(h=>`<div><span class="ex-act-ic">${exI('history',13)}</span><b>${h[1]}</b><small>${h[0]} · ${h[2]}</small></div>`).join('')}</div>`);
    });
  }
  function allocModal(){
    const a=SUB.alloc;
    exModal('Edit Allocation','Set the number of licenses for each type. A total below what is in use is not allowed.',
      `<div class="um-form ex-3">${Object.entries(a).map(([k,v])=>`<div class="field"><label>${LIC_TYPES[k].label} Licenses</label><input type="number" min="${v.used}" value="${v.total}" data-k="${k}"><small class="mut">${v.used} in use</small></div>`).join('')}</div>`,
      '<button class="um-btn" data-close>Cancel</button><button class="um-btn primary" id="al-save">Save Allocation</button>',
      (b,close)=>{ b.querySelector('#al-save').onclick=()=>{ let bad=false; b.querySelectorAll('[data-k]').forEach(i=>{ const v=parseInt(i.value,10); if(isNaN(v)||v<a[i.dataset.k].used) bad=true; }); if(bad){ b.querySelector('.sub').innerHTML='<span style="color:var(--rose)">Each total must be at least the number in use.</span>'; return; }
        b.querySelectorAll('[data-k]').forEach(i=>a[i.dataset.k].total=parseInt(i.value,10)); SUB.history.unshift([new Date().toLocaleDateString('en-GB',{month:'short',day:'2-digit',year:'numeric'}),'License allocation updated',SESSION.user?SESSION.user.name:'Admin']); close(); entRenderLicense(); exToast('License allocation saved'); }; });
  }
  function deptModal(i){
    const d=SUB.depts[i];
    exModal('Manage '+d[0],'Assigned licenses for this department. Assigned cannot go below what is in use.',
      `<div class="um-form ex-3">${[['Workstation',2],['Viewer',3],['Admin',4]].map(([l,k])=>`<div class="field"><label>${l}</label><input type="number" min="${d[k][1]}" value="${d[k][0]}" data-k="${k}"><small class="mut">${d[k][1]} in use</small></div>`).join('')}</div>`,
      '<button class="um-btn" data-close>Cancel</button><button class="um-btn primary" id="dp-save">Save Changes</button>',
      (b,close)=>{ b.querySelector('#dp-save').onclick=()=>{ let bad=false; b.querySelectorAll('[data-k]').forEach(x=>{ const v=parseInt(x.value,10); if(isNaN(v)||v<d[x.dataset.k][1]) bad=true; }); if(bad){ b.querySelector('.sub').innerHTML='<span style="color:var(--rose)">Assigned must be at least the number in use.</span>'; return; }
        b.querySelectorAll('[data-k]').forEach(x=>d[x.dataset.k][0]=parseInt(x.value,10)); close(); entRenderLicense(); exToast(d[0]+' licenses updated'); }; });
  }

  /* ─────────────── INTEGRATIONS & CONNECTORS ─────────────── */
  const INT_CATS = [['dev','Development Tools','git'],['pm','Project Management','kanban'],['comm','Communication','chat'],['know','Knowledge Sources','book'],['cloud','Cloud & Infrastructure','cloud'],['other','Others','code']];
  const INTS = [
    ['github','GitHub','Source code repository','dev','connected','Sync repositories, code, PRs and issues','5 minutes ago',12],
    ['gitlab','GitLab','Source code repository','dev','connected','Sync repositories, merge requests','12 minutes ago',6],
    ['bitbucket','Bitbucket','Source code repository','dev','none','Connect to sync repositories'],
    ['azdo','Azure DevOps','Boards, Repos, Pipelines','dev','connected','Sync work items, repos and pipelines','3 hours ago',4],
    ['jenkins','Jenkins','CI/CD','dev','setup','Configure Jenkins for build data'],
    ['circleci','CircleCI','CI/CD','dev','setup','Finish authorising build pipelines'],
    ['jira','Jira','Project management','pm','connected','Sync projects, issues, sprints','8 minutes ago'],
    ['linear','Linear','Issue tracking','pm','connected','Sync issues, cycles and roadmaps','40 minutes ago'],
    ['asana','Asana','Work management','pm','none','Connect to sync tasks and projects'],
    ['monday','Monday.com','Work OS','pm','none','Connect to sync boards and items'],
    ['slack','Slack','Team communication','comm','connected','Sync channels, messages, alerts','2 hours ago'],
    ['teams','Microsoft Teams','Team communication','comm','none','Enable to sync channels and messages'],
    ['gmail','Gmail','Email','comm','connected','Send agent notifications and digests','1 hour ago'],
    ['zoom','Zoom','Meetings','comm','none','Connect to import meeting notes'],
    ['confluence','Confluence','Documentation & knowledge base','know','connected','Sync pages, documents and spaces','1 hour ago'],
    ['sharepoint','SharePoint','Document management','know','none','Enable to sync documents'],
    ['notion','Notion','Wiki & docs','know','setup','Choose the workspaces to share'],
    ['gdrive','Google Drive','File storage','know','connected','Sync shared drives and documents','25 minutes ago'],
    ['aws','AWS','Cloud infrastructure','cloud','connected','Sync resources, deployments, logs','1 hour ago'],
    ['gcp','Google Cloud','Cloud infrastructure','cloud','none','Connect to manage cloud resources'],
    ['azure','Microsoft Azure','Cloud infrastructure','cloud','action','Access token expired — reconnect to resume sync','2 days ago'],
    ['snowflake','Snowflake','Data warehouse','cloud','none','Connect to access data sources'],
    ['datadog','Datadog','Monitoring & observability','other','connected','Sync metrics, logs and alerts','30 minutes ago'],
    ['custom','Custom API','Connect any system','other','connected','REST API with custom configuration','15 minutes ago']
  ].map(r=>({id:r[0],name:r[1],sub:r[2],cat:r[3],status:r[4],desc:r[5],sync:r[6]||null,repos:r[7]||0,
    by:'Sarah Johnson (Admin)', on:'15 Jan 2025, 10:30 AM', tab:'overview',
    settings:[['Sync code repositories','Allow agents to read and analyze code',true],['Sync issues and pull requests','Import issues, PRs and comments',true],['Sync wiki and documentation','Import wiki pages and project docs',false],['Sync release information','Import releases and changelogs',true]],
    access:['platform','web-portal','mobile-app','ai-agents','devops'].map((n,i)=>({name:'globaltech/'+n, full:i===0||i===3}))}));
  const IX = {cat:'all', q:'', status:'all', view:'grid', sel:'github'};
  const INT_ST = {connected:['Connected','st-approved','check'], none:['Not Connected','st-none','x'], setup:['Setup Required','st-pending','clock'], action:['Action Required','st-suspended','alert']};
  const intSt = s=>{ const x=INT_ST[s]; return `<span class="ex-st ${x[1]}">${exI(x[2],11)}${x[0]}</span>`; };
  const intLogo = i=>{ const c=INT_CATS.find(c=>c[0]===i.cat); return `<span class="ex-logo c-${i.cat}">${exI(c[2],20)}<em>${i.name[0]}</em></span>`; };
  function intAction(i){ return i.status==='connected'?['Manage','tint']:i.status==='none'?['Connect','primary']:i.status==='setup'?['Configure','warn']:['Reconnect','danger']; }
  function entRenderIntegrations(){
    const root=$('#ent-integrations'); if(!root) return;
    IX.sel=null;
    if(IX.edit){ const ei=INTS.find(x=>x.id===IX.edit); if(ei){ intEditPage(root,ei); return; } IX.edit=null; }
    if(IX.page){ const pi=INTS.find(x=>x.id===IX.page); if(pi){ intDetailPage(root,pi); return; } IX.page=null; }
    const n=s=>INTS.filter(i=>i.status===s).length;
    const q=IX.q.trim().toLowerCase();
    const list=INTS.filter(i=>(IX.cat==='all'||i.cat===IX.cat)&&(IX.status==='all'||i.status===IX.status)&&(!q||(i.name+' '+i.sub).toLowerCase().includes(q)));
    const sel=INTS.find(i=>i.id===IX.sel);
    root.innerHTML = exHead('Integrations &amp; Connectors','Connect your existing tools, data sources and knowledge systems to extend the power of Xccelera AI Platform.',
        exBtn('View Documentation','book','','ix-docs')+exBtn('Add Integration','plus','primary ex-edit','ix-add'))
      + `<div class="ex-kpis">${exKpi('link','t-green',n('connected'),'Connected Integrations','Actively syncing data')}${exKpi('hour','t-amber',n('setup'),'Pending Setup','Requires configuration')}${exKpi('alert','t-rose',n('action'),'Action Required','Needs attention')}${exKpi('db','t-blue',INTS.length,'Total Data Sources','Across all projects')}</div>
        <div class="ex-card ex-bar-card"><div class="ex-tabs">${[['all','All Integrations',INTS.length],...INT_CATS.map(c=>[c[0],c[1],INTS.filter(i=>i.cat===c[0]).length])].map(t=>`<button class="ex-tab${IX.cat===t[0]?' on':''}" data-cat="${t[0]}">${exEsc(t[1])} (${t[2]})</button>`).join('')}</div>
          <div class="ex-toolbar end"><label class="ex-search sm">${exI('search',15)}<input id="ix-q" placeholder="Search integrations…" value="${exEsc(IX.q)}"></label>
            <select class="ex-sel sm" id="ix-st"><option value="all">All Status</option>${Object.entries(INT_ST).map(([k,v])=>`<option value="${k}"${IX.status===k?' selected':''}>${v[0]}</option>`).join('')}</select>
            <div class="ex-vt"><button class="${IX.view==='list'?'on':''}" data-v="list" aria-label="List view">${exI('list',15)}</button><button class="${IX.view==='grid'?'on':''}" data-v="grid" aria-label="Grid view">${exI('grid',15)}</button></div></div></div>
        <div class="ex-split${sel?' has-side':''}">
          <div class="${IX.view==='grid'?'ex-int-grid':'ex-int-list'}">${list.map(i=>{ const [lab,cls]=intAction(i); return `<div class="ex-card ex-int${i.id===IX.sel?' sel':''}" data-iid="${i.id}">
              <div class="ex-int-top">${intLogo(i)}<div><b>${i.name}</b><small>${i.sub}</small></div>
                <div class="ex-menu-wrap"><button class="ex-dots v" data-imenu="${i.id}" aria-label="More">${exI('dots',16)}</button><div class="ex-menu" id="ix-menu-${i.id}">
                  <button data-ia="open" data-iid="${i.id}">${exI('eye',14)}View Details</button>
                  ${i.status==='connected'?`<button class="ex-edit" data-ia="test" data-iid="${i.id}">${exI('pulse',14)}Test Connection</button><button class="ex-edit danger" data-ia="disconnect" data-iid="${i.id}">${exI('x',14)}Disconnect</button>`:`<button class="ex-edit" data-ia="act" data-iid="${i.id}">${exI('link',14)}${intAction(i)[0]}</button>`}
                </div></div></div>
              ${intSt(i.status)}<p>${i.desc}</p>
              <div class="ex-int-ft"><span class="mut">${i.sync?exI('user',12)+' Last sync: '+i.sync:''}</span>${exBtn(lab,'','sm '+cls+' ex-edit','',`data-ia="act" data-iid="${i.id}"`)}</div></div>`; }).join('') || '<div class="ex-card ex-empty">No integrations match.</div>'}</div>
          ${sel?intSide(sel):''}
        </div>`;
    intBind(root); exNavCounts();
  }
  function intSide(i){
    const tabs=[['overview','Overview'],['configuration','Configuration'],['sync','Sync Details'],['permissions','Permissions']];
    let body='';
    if(i.status!=='connected'){
      body=`<div class="ex-side-sec"><p class="ex-p">${i.desc}. Once connected, agents in Platform Studio can use ${i.name} data in the projects you choose.</p>${exBtn(intAction(i)[0]+' '+i.name,'link','primary ex-edit wide','',`data-ia="act" data-iid="${i.id}"`)}</div>`;
    } else if(i.tab==='overview'){
      body=`<div class="ex-side-sec"><p class="ex-p">Connect your ${i.name} account so agents can access its data, understand project structure and learn from your work.</p>
        <div class="ex-kv"><div><span>Connection Status</span><b><span class="ex-st st-approved">${exI('check',11)}Active</span> ${exBtn('Test','','sm ex-edit','ix-test')}</b></div>
        <div><span>Connected By</span><b>${i.by}</b></div><div><span>Connected On</span><b>${i.on}</b></div>
        <div><span>Last Sync</span><b><span class="ex-ok">${exI('check',12)}</span> ${i.sync}</b></div>
        ${i.repos?`<div><span>Repositories</span><b>${i.repos} <button class="ex-link ex-edit" data-itab="permissions">Manage</button></b></div>`:''}
        <div><span>Access Type</span><b>Organization (globaltech)</b></div></div></div>
        ${intSettings(i)}${i.cat==='dev'?intAccess(i):''}`;
    } else if(i.tab==='configuration'){
      body=`<div class="ex-side-sec"><div class="um-form"><div class="field"><label>Workspace / Organization</label><input value="globaltech" class="ex-edit-in"></div><div class="field"><label>Sync Frequency</label><select class="ex-edit-in"><option>Every 5 minutes</option><option>Every 15 minutes</option><option>Hourly</option></select></div><div class="field"><label>Default Project Scope</label><select class="ex-edit-in"><option>All projects</option><option>Selected projects only</option></select></div></div>${exBtn('Save Configuration','','primary ex-edit','ix-save-cfg')}</div>${intSettings(i)}`;
    } else if(i.tab==='sync'){
      body=`<div class="ex-side-sec"><div class="ex-act">${[['Full sync completed',i.sync],['Incremental sync — 214 items','1 hour ago'],['Incremental sync — 98 items','2 hours ago'],['Webhook re-registered','Yesterday']].map(a=>`<div><span class="ex-act-ic">${exI('check',13)}</span><b>${a[0]}</b><small>${a[1]}</small></div>`).join('')}</div>${exBtn('Sync Now','history','ex-edit','ix-sync')}</div>`;
    } else body=intAccess(i,true);
    return `<div class="ex-card ex-side" role="complementary" aria-label="Integration details">
      <div class="ex-side-top">${intLogo(i)}<div><h3>${i.name} ${intSt(i.status)}</h3><p>${i.sub} integration</p></div><button class="ex-ic-btn ex-x" id="ix-close" aria-label="Close">${exI('x',15)}</button></div>
      ${i.status==='connected'?`<div class="ex-tabs sm">${tabs.map(t=>`<button class="ex-tab${i.tab===t[0]?' on':''}" data-itab="${t[0]}">${t[1]}</button>`).join('')}</div>`:''}${body}</div>`;
  }
  const intSettings=i=>`<div class="ex-side-sec"><div class="ex-sec-h"><h4>Sync Settings</h4></div>${i.settings.map((s,k)=>`<div class="ex-toggle-row"><span class="ex-tr-ic">${exI('doc',14)}</span><div><b>${s[0]}</b><small>${s[1]}</small></div>${exSwitch(s[2],`data-iset="${k}"`)}</div>`).join('')}</div>`;
  const intAccess=(i,full)=>`<div class="ex-side-sec"><div class="ex-sec-h"><h4>${i.cat==='dev'?'Repository':'Workspace'} Access</h4>${full?'':`<button class="ex-link" data-itab="permissions">Manage</button>`}</div>${i.access.map((r,k)=>`<div class="ex-repo"><span>${exI('git',14)}${r.name}</span><button class="ex-pill-btn ${r.full?'full':''} ex-edit" data-irepo="${k}" title="Click to change">${r.full?'Full Access':'Read Only'}</button></div>`).join('')}</div>`;
  function intBind(root){
    const on=(s,ev,fn)=>{ const el=root.querySelector(s); if(el) el.addEventListener(ev,fn); };
    on('#ix-q','input',e=>{ IX.q=e.target.value; const p=e.target.selectionStart; entRenderIntegrations(); const i=$('#ix-q'); if(i){ i.focus(); i.setSelectionRange(p,p);} });
    on('#ix-st','change',e=>{ IX.status=e.target.value; entRenderIntegrations(); });
    on('#ix-docs','click',()=>gotoTop('policy'));
    on('#ix-add','click',()=>{ const avail=INTS.filter(i=>i.status!=='connected');
      exModal('Add Integration','Pick a tool to connect. Agents only see data from the projects you allow.',`<div class="ex-pick">${avail.map(i=>`<button data-pick="${i.id}">${intLogo(i)}<b>${i.name}</b><small>${INT_ST[i.status][0]}</small></button>`).join('')}</div>`,'<button class="um-btn" data-close>Cancel</button>',
        (b,close)=>b.querySelectorAll('[data-pick]').forEach(x=>x.onclick=()=>{ close(); intConnect(INTS.find(i=>i.id===x.dataset.pick)); })); });
    root.querySelectorAll('[data-cat]').forEach(b=>b.onclick=()=>{ IX.cat=b.dataset.cat; entRenderIntegrations(); });
    root.querySelectorAll('[data-v]').forEach(b=>b.onclick=()=>{ IX.view=b.dataset.v; entRenderIntegrations(); });
    root.querySelectorAll('.ex-int').forEach(c=>c.onclick=e=>{ if(e.target.closest('button')) return; IX.page=c.dataset.iid; entRenderIntegrations(); const m=document.querySelector('main'); if(m) m.scrollTop=0; window.scrollTo(0,0); });
    root.querySelectorAll('[data-imenu]').forEach(b=>b.onclick=e=>{ e.stopPropagation(); const m=$('#ix-menu-'+b.dataset.imenu); const was=m.classList.contains('open'); $$('.ex-menu.open').forEach(x=>x.classList.remove('open')); if(!was) m.classList.add('open'); });
    root.querySelectorAll('[data-ia]').forEach(b=>b.onclick=e=>{ e.stopPropagation(); const i=INTS.find(x=>x.id===b.dataset.iid); const a=b.dataset.ia;
      if(a==='open'){ IX.page=i.id; entRenderIntegrations(); }
      if(a==='test') exToast(i.name+' connection is healthy');
      if(a==='disconnect') exModal('Disconnect '+i.name,'Agents stop syncing data from '+i.name+'. You can reconnect later.','','<button class="um-btn" data-close>Cancel</button><button class="um-btn primary" id="ix-dc">Disconnect</button>',(m,close)=>{ m.querySelector('#ix-dc').onclick=()=>{ i.status='none'; i.sync=null; close(); entRenderIntegrations(); exToast(i.name+' disconnected'); }; });
      if(a==='act'){ IX.page=i.id; IX.edit=i.id; IX.focus=null; entRenderIntegrations(); }
    });
    const sel=INTS.find(i=>i.id===IX.sel); if(!sel) return;
    on('#ix-close','click',()=>{ IX.sel=null; entRenderIntegrations(); });
    root.querySelectorAll('[data-itab]').forEach(b=>b.onclick=()=>{ sel.tab=b.dataset.itab; entRenderIntegrations(); });
    on('#ix-test','click',()=>exToast(sel.name+' connection is healthy'));
    on('#ix-sync','click',()=>{ sel.sync='Just now'; entRenderIntegrations(); exToast(sel.name+' sync started'); });
    on('#ix-save-cfg','click',()=>exToast(sel.name+' configuration saved'));
    root.querySelectorAll('[data-iset]').forEach(s=>s.onclick=()=>{ if(!exCanEdit('integrations')) return; const k=+s.dataset.iset; sel.settings[k][2]=!sel.settings[k][2]; entRenderIntegrations(); });
    root.querySelectorAll('[data-irepo]').forEach(s=>s.onclick=()=>{ const r=sel.access[+s.dataset.irepo]; r.full=!r.full; entRenderIntegrations(); exToast(r.name+' set to '+(r.full?'Full Access':'Read Only')); });
  }
  function intConnect(i){ IX.page=i.id; IX.edit=i.id; IX.focus=null; entRenderIntegrations(); }
  function intConnectModalOld(i){
    exModal((i.status==='setup'?'Configure ':i.status==='action'?'Reconnect ':'Connect ')+i.name,'Authorise Xccelera AI to read from '+i.name+' for GlobalTech Solutions.',
      `<div class="um-form"><div class="field"><label>${i.cat==='dev'?'Organization / Workspace':'Workspace'}</label><input id="ic-ws" value="globaltech"></div><div class="field"><label>Access Type</label><select id="ic-acc"><option>Organization (globaltech)</option><option>Selected projects only</option></select></div></div>`,
      `<button class="um-btn" data-close>Cancel</button><button class="um-btn primary" id="ic-go">${i.status==='setup'?'Finish Setup':'Authorise &amp; Connect'}</button>`,
      (b,close)=>{ b.querySelector('#ic-go').onclick=()=>{ i.status='connected'; i.sync='Just now'; i.by=(SESSION.user?SESSION.user.name:'Admin'); i.on=new Date().toLocaleString('en-US',{month:'short',day:'numeric',year:'numeric',hour:'numeric',minute:'2-digit'}); i.tab='overview'; IX.sel=i.id; close(); entRenderIntegrations(); exToast(i.name+' connected'); }; });
  }

  /* ─────────────── SECURITY & GOVERNANCE ─────────────── */
  const SEC = {tab:'access',
    iam:[['sso','Single Sign-On (SSO)','SAML 2.0, OpenID Connect','Configured','key'],['mfa','Multi-Factor Authentication (MFA)','Required for all users','Enforced','finger'],['rbac','Role-Based Access Control (RBAC)','Manage roles and permissions','5 roles','users'],['scim','SCIM Provisioning','Automate user lifecycle management','Active','gear']],
    policies:[['Require MFA for all users',true,'finger'],['Enforce SSO for organization',true,'key'],['Restrict access by IP address',false,'pin'],['Session timeout (minutes)','60','clock'],['Allow personal email domains',false,'mail'],['Require device trust',true,'device'],['Enable data export restrictions',true,'doc'],['Block unauthorized AI models',true,'chip']],
    data:[['Data Encryption','AES-256 encryption at rest and in transit','Enabled','lock'],['Data Residency','United Kingdom (eu-west-2)','Configured','db'],['Data Retention','Project data retained for 12 months','Configured','clock'],['Privacy Controls','GDPR compliant data handling','Enabled','shield']],
    comp:[['SOC 2 Type II','Security, Availability, Confidentiality','Valid till Dec 2025'],['ISO 27001','Information Security Management','Valid till Aug 2026'],['GDPR','Data Protection & Privacy','Valid till Dec 2025']],
    log:[['2 mins ago','Sarah Johnson','Login (SSO)','Success','203.0.113.24'],['12 mins ago','Andrew Kirby','Updated role','Success','203.0.113.45'],['1 hour ago','Michael Carter','Added user','Success','198.51.100.12'],['3 hours ago','System','Suspicious login blocked','Blocked','185.199.110.3'],['5 hours ago','Lucy Walker','Changed settings','Success','203.0.113.77'],['Yesterday','Grace Parker','Rotated SCIM token','Success','203.0.113.90'],['Yesterday','System','Unauthorized AI model request blocked','Blocked','10.4.2.17'],['2 days ago','Daniel Brown','Exported usage report','Success','203.0.113.31']]
  };
  function secCard(title,sub,inner,cls){ return `<div class="ex-card ${cls||''}"><h4 class="ex-h4">${title}</h4><p class="ex-sub">${sub}</p>${inner}</div>`; }
  function entRenderSecurity(){
    const root=$('#ent-security'); if(!root) return;
    if(SEC.edit){ secEditPage(root,SEC.edit==='all'?null:SEC.edit); return; }
    const act=USERS.filter(u=>u.status==='approved').length, pend=USERS.filter(u=>u.status==='pending').length, sus=USERS.filter(u=>u.status==='suspended').length, tot=USERS.length;
    const ws=USERS.filter(u=>u.license==='workstation').length, vw=USERS.filter(u=>u.license==='viewer').length, ad=USERS.filter(u=>u.license==='admin').length;
    const ed=exCanEdit('security');
    const iam=secCard('Identity &amp; Access Management','Manage how users access the platform and enforce security policies.',`<div class="ex-rows">${SEC.iam.map(r=>`<button class="ex-linkrow" data-iam="${r[0]}"><span class="ex-kpi-ic t-blue sm">${exI(r[4],16)}</span><div><b>${r[1]}</b><small>${r[2]}</small></div><span class="ex-st st-approved">${exI('check',11)}${r[3]}</span>${exI('chevR',16)}</button>`).join('')}</div>`);
    const overview=secCard('Access Overview','User distribution and access status across the organization.',`<div class="ex-donut-row">${exDonut([{v:act,c:'#34d399'},{v:pend,c:'#3b82f6'},{v:sus,c:'#94a3b8'}],tot,'Total Users',140)}
        <ul class="ex-legend"><li><i style="background:#34d399"></i>Active<b>${act} (${Math.round(act/tot*100)}%)</b></li><li><i style="background:#3b82f6"></i>Pending<b>${pend} (${Math.round(pend/tot*100)}%)</b></li><li><i style="background:#94a3b8"></i>Suspended<b>${sus} (${Math.round(sus/tot*100)}%)</b></li></ul></div>
        <div class="ex-bars"><div class="ex-sec-h"><b>Access by Role</b><span class="mut">Total Users: ${tot}</span></div><div class="ex-bars-in">${[['Developers',ws,'#3b82f6'],['Viewers',vw,'#a78bfa'],['Admins',ad,'#34d399']].map(b=>`<div><em>${b[1]}</em><i style="height:${Math.max(4,b[1]/ws*90)}px;background:${b[2]}"></i><span>${b[0]}</span></div>`).join('')}</div></div>`);
    const pol=secCard('Security Policies','Configure and enforce platform security policies.',`<div class="ex-rows">${SEC.policies.map((p,k)=>`<div class="ex-toggle-row"><span class="ex-tr-ic">${exI(p[2],14)}</span><div><b>${p[0]}</b></div>${typeof p[1]==='string'?`<select class="ex-sel sm ex-edit-in" data-pol="${k}">${['15','30','60','120'].map(v=>`<option${p[1]===v?' selected':''}>${v}</option>`).join('')}</select>`:exSwitch(p[1],`data-pol="${k}"`,!ed)}</div>`).join('')}</div>`);
    const dp=secCard('Data Protection','Manage data encryption, retention and privacy controls.',`<div class="ex-rows">${SEC.data.map(r=>`<div class="ex-linkrow static"><span class="ex-kpi-ic t-blue sm">${exI(r[3],16)}</span><div><b>${r[0]}</b><small>${r[1]}</small></div><span class="ex-st st-approved">${r[2]}</span></div>`).join('')}</div>`);
    const cp=secCard('Compliance &amp; Certifications','Monitor compliance with industry standards and regulations.',`<div class="ex-rows">${SEC.comp.map((r,k)=>`<div class="ex-linkrow static"><span class="ex-cert c${k}">${['SOC','ISO','EU'][k]}</span><div><b>${r[0]}</b><small>${r[1]}</small></div><div class="ex-r"><span class="ex-st st-approved">${exI('check',11)}Compliant</span><small>${r[2]}</small></div></div>`).join('')}</div>`);
    const logRows=(rows)=>`<div class="ex-table-wrap"><table class="ex-table"><thead><tr><th>Time</th><th>User</th><th>Action</th><th>Status</th><th>IP Address</th></tr></thead><tbody>${rows.map(r=>`<tr><td class="mut">${r[0]}</td><td><div class="ex-who">${r[1]==='System'?`<span class="ex-av sys">${exI('gear',12)}</span>`:uxAvatar({name:r[1]})}<b>${r[1]}</b></div></td><td>${r[2]}</td><td><span class="ex-st ${r[3]==='Success'?'st-approved':'st-suspended'}">${r[3]}</span></td><td class="mut mono">${r[4]}</td></tr>`).join('')}</tbody></table></div>`;
    const recent=`<div class="ex-card"><div class="ex-sec-h"><h4>Recent Security Activity</h4><button class="ex-link" data-stab="audit">View All</button></div>${logRows(SEC.log.slice(0,5))}</div>`;
    const tabs=[['access','Access Control'],['auth','Authentication'],['data','Data Protection'],['comp','Compliance'],['audit','Audit Logs'],['threat','Threat Monitoring'],['policy','Policy Settings']];
    let content='';
    if(SEC.tab==='access') content=`<div class="ex-grid g-3">${iam}${overview}${pol}</div><div class="ex-grid g-3">${dp}${cp}${recent}</div>`;
    if(SEC.tab==='auth') content=`<div class="ex-grid g-2">${iam}${secCard('Identity Provider','Where GlobalTech users sign in.',`<div class="ex-kv"><div><span>Provider</span><b>Microsoft Entra ID</b></div><div><span>Protocol</span><b>SAML 2.0</b></div><div><span>Last Sync</span><b>5 mins ago</b></div><div><span>MFA Coverage</span><b>${act} of ${act} active users</b></div><div><span>Sign-in Methods</span><b>SSO · Microsoft · Google</b></div></div>`)}</div>`;
    if(SEC.tab==='data') content=`<div class="ex-grid g-2">${dp}${pol}</div>`;
    if(SEC.tab==='comp') content=`<div class="ex-grid g-2">${cp}${secCard('Audit Readiness','Evidence collected automatically for audits.',`<ul class="ex-perms">${['Access reviews completed this quarter','Encryption keys rotated in the last 90 days','Audit logs retained for 12 months','Vendor risk assessments on file'].map(x=>`<li class="y">${exI('check',11)}${x}</li>`).join('')}</ul>`)}</div>`;
    if(SEC.tab==='audit') content=`<div class="ex-card"><div class="ex-sec-h"><h4>Audit Logs</h4>${exBtn('Export Logs','download','sm','sec-export')}</div>${logRows(SEC.log)}</div>`;
    if(SEC.tab==='threat') content=`<div class="ex-grid g-2">${secCard('Threats Blocked','Last 7 days.',`<div class="ex-kv"><div><span>Suspicious logins blocked</span><b>4</b></div><div><span>Unauthorized AI model requests</span><b>2</b></div><div><span>Blocked IP addresses</span><b>3</b></div><div><span>Open incidents</span><b>0</b></div></div>`)}<div class="ex-card"><h4 class="ex-h4">Blocked Events</h4>${logRows(SEC.log.filter(r=>r[3]==='Blocked'))}</div></div>`;
    if(SEC.tab==='policy') content=`<div class="ex-grid g-2">${pol}${secCard('Policy Documents','Published policies everyone in GlobalTech can read.',`<div class="ex-rows">${['Acceptable Use Policy','Data Handling Standard','AI Usage Guidelines'].map(x=>`<button class="ex-linkrow" data-goto-policy><span class="ex-kpi-ic t-blue sm">${exI('doc',16)}</span><div><b>${x}</b><small>Updated Jan 2026</small></div>${exI('chevR',16)}</button>`).join('')}</div>`)}</div>`;
    root.innerHTML = exHead('Security &amp; Governance','Control access, protect your data and ensure compliance across the Xccelera AI Platform.',
        exBtn('View Security Documentation','book','','sec-docs')+exBtn('Edit Security Settings','gear','primary ex-edit','sec-edit'))
      + `<div class="ex-kpis">${exKpi('shieldok','t-blue','92<small>/100</small>','Security Score','Good security posture','<span class="ex-up">↑ 8%</span>')}${exKpi('users','t-blue',tot,'Active Users','All users secured with <b class="ok">MFA</b>')}${exKpi('key','t-green','<span class="ok">Connected</span>','SSO / Identity','SAML 2.0 · Last sync 5 mins ago')}${exKpi('doc','t-amber','3/3','Compliance Status','SOC 2 · ISO 27001 · GDPR','<span class="ex-ok big">'+exI('check',12)+'</span>')}</div>
        <div class="ex-tabs line">${tabs.map(t=>`<button class="ex-tab${SEC.tab===t[0]?' on':''}" data-stab="${t[0]}">${t[1]}</button>`).join('')}</div>${content}`;
    root.querySelectorAll('[data-stab]').forEach(b=>b.onclick=()=>{ SEC.tab=b.dataset.stab; entRenderSecurity(); });
    root.querySelector('#sec-docs').onclick=()=>gotoTop('policy');
    root.querySelector('#sec-edit').onclick=()=>{ SEC.edit='all'; entRenderSecurity(); };
    root.querySelectorAll('[data-goto-policy]').forEach(b=>b.onclick=()=>gotoTop('policy'));
    root.querySelectorAll('[data-iam]').forEach(b=>b.onclick=()=>{ const k=b.dataset.iam; if(k==='rbac'){ gotoTop('roles'); return; } SEC.edit = k==='mfa'?'mfa':'sso'; entRenderSecurity(); });
    root.querySelectorAll('[data-pol]').forEach(s=>{ const k=+s.dataset.pol; const p=SEC.policies[k];
      if(s.tagName==='SELECT') s.onchange=()=>{ p[1]=s.value; exToast('Session timeout set to '+s.value+' minutes'); };
      else s.onclick=()=>{ if(!ed) return; p[1]=!p[1]; entRenderSecurity(); exToast(p[0]+(p[1]?' turned on':' turned off')); }; });
    const ex=root.querySelector('#sec-export'); if(ex) ex.onclick=()=>exDownload('security-audit-log.csv',['Time,User,Action,Status,IP Address'].concat(SEC.log.map(r=>r.join(','))).join('\n'),'text/csv');
  }

  /* ─────────────── REVIEW & ACTIVATE (Organization Setup) ─────────────── */
  const ORGX = {activated:false,
    details:[['Organization Name','GlobalTech Solutions'],['Organization ID','ORG-8F3A-7K2L'],['Industry','Technology'],['Region','United Kingdom (London)'],['Timezone','(UTC-05:00) Eastern Time'],['Primary Contact','Sarah Johnson'],['Domain','globaltech.com'],['Data Residency','US Region']]};
  function entRenderOrganisation(){
    const root=$('#ent-organisation'); if(!root) return;
    if(ORGX.edit){ orgEditPage(root); return; }
    const a=SUB.alloc, conn=INTS.filter(i=>i.status==='connected');
    const cs=id=>{ const i=INTS.find(x=>x.id===id); return i&&i.status==='connected'?'Connected':'Not connected'; };
    const steps=[['Organization','organisation'],['Subscription','license'],['Users & Roles','users'],['Integrations','integrations'],['Security','security'],['Review & Activate','organisation']];
    const sum=(ic,tone,title,go,rows)=>`<div class="ex-card ex-sum"><div class="ex-sum-h"><span class="ex-kpi-ic ${tone} sm">${exI(ic,17)}</span><div><h4>${title}</h4><span class="ex-st st-approved">${exI('check',11)}Completed</span></div><button class="ex-link" data-go="${go}">Edit</button></div><div class="ex-kv tight">${rows.map(r=>`<div><span>${r[0]}</span><b>${exEsc(r[1])}</b></div>`).join('')}</div></div>`;
    const pol=k=>SEC.policies[k][1];
    const checks=['Organization profile configured','Subscription and licenses set','Users imported and roles assigned','Departments and teams created','Integrations connected and tested','Security and governance policies set','AI models and agent permissions configured','Billing and finance settings verified'];
    const valid=[['License allocation is valid',a.workstation.total>=a.workstation.used],['All required administrators assigned',USERS.some(u=>hasRole(u,'org-admin'))],['SSO and MFA configured correctly',pol(0)&&pol(1)],['At least one integration connected',conn.length>0],['Security policies applied',true],['Billing information verified',!!SUB.contact]];
    const ready=valid.every(v=>v[1]);
    root.innerHTML = exHead('Review &amp; Activate','Review your organization setup, verify all configurations, and activate your Xccelera AI Platform.','')
      + `<div class="ex-steps">${steps.map((s,i)=>`<button class="ex-step${i===5?' cur':''}" data-go="${s[1]}"><span class="ex-step-ic">${i<5||ORGX.activated?exI('check',13):'6'}</span><div><b>${i+1}. ${s[0]}</b><small>${i<5||ORGX.activated?'Completed':'In Progress'}</small></div></button>`).join('')}</div>
        <div class="ex-grid g-review">
          <div class="ex-card ex-cfg"><div class="ex-sec-h"><div><h4>Configuration Summary</h4><p class="ex-sub">Please review all settings before activating your organization. You can go back and edit any section if needed.</p></div>${exBtn('Download Summary','download','sm','org-dl')}</div>
            <div class="ex-sum-grid">
              ${sum('building','t-blue','Organization Details','organisation-edit',ORGX.details)}
              ${sum('db','t-blue','Subscription &amp; Licensing','license',[['Plan',SUB.plan],['Contract ID',SUB.contractId],['Contract Period',exDate(SUB.start)+' – '+exDate(SUB.end)],['Workstation Licenses',a.workstation.total],['Viewer Licenses',a.viewer.total],['Admin Licenses',a.admin.total],['Total Licenses',subTotals().total],['Billing Cycle',SUB.cycle],['Payment Method',SUB.payment]])}
              ${sum('users','t-violet','Users &amp; Roles','users',[['Total Users',USERS.length],['Workstation Users',USERS.filter(u=>u.license==='workstation').length],['Viewer Users',USERS.filter(u=>u.license==='viewer').length],['Admin Users',USERS.filter(u=>u.license==='admin').length],['SSO / Identity Provider','Microsoft Entra ID'],['MFA',pol(0)?'Enabled':'Disabled'],['Pending Invitations',USERS.filter(u=>u.status==='pending').length]])}
              ${sum('link','t-green','Integrations &amp; Connectors','integrations',[['Connected Integrations',conn.length],['Source Code (GitHub)',cs('github')],['Project Management (Jira)',cs('jira')],['Communication (Slack)',cs('slack')],['Documentation (Confluence)',cs('confluence')],['CI/CD (Jenkins)',cs('jenkins')],['Cloud (AWS)',cs('aws')],['Last Sync','5 minutes ago']])}
              ${sum('shieldok','t-blue','Security &amp; Governance','security',[['SSO Enabled',pol(1)?'Yes (SAML 2.0)':'No'],['MFA',pol(0)?'Required for all users':'Optional'],['IP Allowlist',pol(2)?'Enabled':'Not enabled'],['Data Encryption','AES-256'],['Data Retention','12 months'],['Compliance','SOC 2, ISO 27001, GDPR'],['Audit Logging','Enabled']])}
              ${sum('gear','t-blue','AI &amp; Project Settings','config',[['Default AI Models','Claude, GPT, Llama (as configured)'],['Model Routing','Enabled'],['Knowledge Graph','Enabled'],['Project Workspaces',typeof PROJECTS!=='undefined'?PROJECTS.length:8],['Agent Permissions','Configured'],['Usage Limits','Configured'],['Organization Memory','Enabled']])}
            </div></div>
          <div class="ex-col">
            <div class="ex-card"><h4 class="ex-h4">Activation Checklist</h4><p class="ex-sub">Ensure all required items are completed before activation.</p><ul class="ex-check">${checks.map(c=>`<li>${exI('check',11)}<span>${c}</span><em>Completed</em></li>`).join('')}</ul></div>
            <div class="ex-card ex-valid ${ready?'ok':'bad'}"><h4 class="ex-h4">Pre-Activation Validation</h4><p class="ex-sub">${ready?'All critical checks have passed. Your organization is ready for activation.':'Fix the items marked below before activating.'}</p>
              <div class="ex-valid-in"><ul class="ex-perms">${valid.map(v=>`<li class="${v[1]?'y':'n'}">${exI(v[1]?'check':'x',11)}${v[0]}</li>`).join('')}</ul>
              <div class="ex-ready"><span>${exI(ready?'check':'alert',34)}</span><b>${ORGX.activated?'Organization Active':ready?'Ready to Activate':'Not Ready'}</b><small>${ready?'No blocking issues found.':'Blocking issues found.'}</small></div></div></div>
            <div class="ex-card ex-next"><h4 class="ex-h4">${exI('info',15)} What happens next?</h4><ol>${['Your organization will be activated and ready to use.','All invited users will receive activation emails.','Integrations will start syncing automatically.','You can manage settings anytime from the Enterprise Admin Portal.'].map(x=>`<li>${x}</li>`).join('')}</ol></div>
            <div class="ex-act-btns">${exBtn('Back','arrowL','outline','org-back')}${ORGX.activated?exBtn('Organization Active','check','primary','org-done','disabled'):exBtn('Activate Organization','rocket','primary ex-edit','org-activate',ready?'':'disabled')}</div>
          </div></div>`;
    root.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{ const g=b.dataset.go; if(g==='organisation') return; if(g==='organisation-edit'){ ORGX.edit=true; entRenderOrganisation(); return; } gotoTop(g); });
    root.querySelector('#org-back').onclick=()=>gotoTop('security');
    const go=root.querySelector('#org-activate'); if(go) go.onclick=()=>exModal('Activate Organization','Activate GlobalTech Solutions on the Xccelera AI Platform? Invited users will get activation emails.','','<button class="um-btn" data-close>Cancel</button><button class="um-btn primary" id="org-go">Activate Organization</button>',(b,close)=>{ b.querySelector('#org-go').onclick=()=>{ ORGX.activated=true; close(); entRenderOrganisation(); exToast('GlobalTech Solutions is now active'); }; });
    root.querySelector('#org-dl').onclick=()=>exDownload('GlobalTech-Configuration-Summary.txt',['GlobalTech Solutions — Configuration Summary',''].concat(ORGX.details.map(d=>d[0]+': '+d[1])).concat(['','Plan: '+SUB.plan,'Licenses: '+subTotals().total,'Users: '+USERS.length,'Connected integrations: '+conn.length,'Status: '+(ORGX.activated?'Active':'Ready to activate')]).join('\n'));
  }
  function orgEditModal(){
    exModal('Edit Organization Details','',`<div class="um-form ex-2">${ORGX.details.map((d,k)=>`<div class="field"><label>${d[0]}</label><input data-k="${k}" value="${exEsc(d[1])}" ${k===1?'disabled':''}></div>`).join('')}</div>`,
      '<button class="um-btn" data-close>Cancel</button><button class="um-btn primary" id="od-save">Save Changes</button>',
      (b,close)=>{ b.querySelector('#od-save').onclick=()=>{ b.querySelectorAll('[data-k]').forEach(i=>{ if(i.value.trim()) ORGX.details[+i.dataset.k][1]=i.value.trim(); }); close(); entRenderOrganisation(); exToast('Organization details saved'); }; });
  }
  function exNavCounts(){ const u=$('#users-nav-count'); if(u) u.textContent=USERS.length; const i=$('#int-nav-count'); if(i) i.textContent=INTS.filter(x=>x.status==='connected').length; }
  setTimeout(exNavCounts,0);

  document.addEventListener('click',e=>{ if(e.target.closest('#top-nav .nav-item[data-goto="users"]')) UX.detail=null; },true);

  document.addEventListener('click',e=>{ const n=e.target.closest('#top-nav .nav-item'); if(!n) return; const g=n.dataset.goto;
    if(g==='users'){ UX.edit=null; UX.create=false; } if(g==='integrations'){ IX.page=null; IX.edit=null; } if(g==='security'){ SEC.edit=null; } if(g==='organisation'){ ORGX.edit=false; } },true);

  /* ─────────────── EXECUTIVE DASHBOARD (Enterprise · Organization Insights) ─────────────── */
  const EXD = {range:'Last 6 Months', delRange:'Last 6 Months', costRange:'Last 6 Months',
    months:['Jan','Feb','Mar','Apr','May','Jun'],
    planned:[60,63,70,72,81,90], completed:[56,61,71,68,78,89], ontime:[89,89,87,85,88,91],
    model:[14,16,13,15,14,16], orch:[6,7,6,7,6,7], other:[5,5,4,5,4,4], tokens:[56,66,64,62,68,62],
    projects:[['Customer Portal 2.0','Development','Platform',80,'40% dev time'],['Legacy System Migration','Modernization','Core Engineering',65,'35% maintenance cost'],['AI Support Assistant','Internal Tool','IT Operations',95,'50% ticket resolution'],['Data Analytics Platform','Development','Data Team',60,'Faster insights'],['Mobile App Enhancement','Development','Product',75,'30% feature velocity'],['Partner API Gateway','Development','Platform',45,'25% faster onboarding'],['Mainframe Billing Rewrite','Modernization','Core Engineering',30,'20% infra cost'],['Knowledge Graph POC','POC','Data Team',55,'Faster code search']],
    teams:[['Engineering','code',80,74,7.2,42],['Product','kanban',15,12,5.1,38],['QA','test',10,8,4.3,35],['Operations','gear',8,6,3.9,32],['Finance','pulse',5,4,2.1,20]],
    models:[['Claude 3.5',42,'#3b82f6'],['GPT-4o',28,'#60a5fa'],['Llama 3',15,'#a78bfa'],['Gemini',12,'#fb923c'],['Others',3,'#94a3b8']],
    outcomes:[['32%','Reduction in development time','t-green'],['35%','Lower AI costs through orchestration','t-green'],['41%','Increase in developer productivity','t-blue'],['94%','Code quality and testing accuracy','t-violet'],['28%','Reduction in infrastructure and maintenance effort','t-amber']]
  };
  function exdTrend(v,up,good){ return `<span class="ex-trend ${good===false?'bad':''}">${up?'↑':'↓'} ${v}</span>`; }
  function exdRing(pct,label,big,trend){ const r=34,c=2*Math.PI*r; return `<div class="ex-ring"><div class="ex-ring-c"><svg viewBox="0 0 84 84"><circle cx="42" cy="42" r="${r}" stroke="rgba(148,163,184,.18)" stroke-width="9" fill="none"/><circle cx="42" cy="42" r="${r}" stroke="#0e60ff" stroke-width="9" fill="none" stroke-linecap="round" stroke-dasharray="${c*pct/100} ${c}" transform="rotate(-90 42 42)"/></svg><b>${big}</b></div><span>${label}</span>${trend}</div>`; }
  function entRenderDashboard(){
    const root=$('#ent-dash'); if(!root) return;
    const ws=USERS.filter(u=>u.license==='workstation').length, vw=USERS.filter(u=>u.license==='viewer').length, ad=USERS.filter(u=>u.license==='admin').length;
    const M=EXD.months, W=520,H=230,P=34;
    const xs=(i,n)=>P+ (i+.5)*((W-P*2)/n);
    /* delivery chart */
    const ys=v=>H-28-(v/100)*(H-50), yp=v=>H-28-(v/100)*(H-50);
    const bw=18;
    const del=`<svg class="ex-chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="Planned and completed projects with on-time rate">
      ${[0,20,40,60,80,100].map(v=>`<line x1="${P}" x2="${W-P}" y1="${ys(v)}" y2="${ys(v)}" stroke="currentColor" stroke-opacity=".1"/><text x="${P-6}" y="${ys(v)+3}" text-anchor="end" font-size="10" fill="currentColor" opacity=".6">${v}</text><text x="${W-P+6}" y="${ys(v)+3}" font-size="10" fill="#34d399" opacity=".8">${v}%</text>`).join('')}
      ${M.map((m,i)=>`<rect x="${xs(i,6)-bw-1}" y="${ys(EXD.planned[i])}" width="${bw}" height="${ys(0)-ys(EXD.planned[i])}" rx="3" fill="#0e60ff"><title>Planned · ${m}: ${EXD.planned[i]} projects</title></rect><rect x="${xs(i,6)+1}" y="${ys(EXD.completed[i])}" width="${bw}" height="${ys(0)-ys(EXD.completed[i])}" rx="3" fill="#7fb0ff"><title>Completed · ${m}: ${EXD.completed[i]} projects</title></rect><text x="${xs(i,6)}" y="${H-10}" text-anchor="middle" font-size="10.5" fill="currentColor" opacity=".7">${m}</text>`).join('')}
      <polyline fill="none" stroke="#34d399" stroke-width="2.2" points="${EXD.ontime.map((v,i)=>xs(i,6)+','+yp(v)).join(' ')}"/>${EXD.ontime.map((v,i)=>`<circle cx="${xs(i,6)}" cy="${yp(v)}" r="3.4" fill="#34d399"><title>On-time delivery · ${M[i]}: ${v}%</title></circle>`).join('')}</svg>`;
    /* cost chart: stacked $K (max 50) + tokens line (max 100M) */
    const yc=v=>H-28-(v/50)*(H-50);
    const cost=`<svg class="ex-chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="Monthly AI cost and tokens">
      ${[0,10,20,30,40,50].map(v=>`<line x1="${P}" x2="${W-P}" y1="${yc(v)}" y2="${yc(v)}" stroke="currentColor" stroke-opacity=".1"/><text x="${P-6}" y="${yc(v)+3}" text-anchor="end" font-size="10" fill="currentColor" opacity=".6">${v}K</text><text x="${W-P+6}" y="${yc(v)+3}" font-size="10" fill="#a78bfa" opacity=".85">${v*2}</text>`).join('')}
      ${M.map((m,i)=>{ const a=EXD.model[i],b=EXD.orch[i],c=EXD.other[i]; const x=xs(i,6)-16; return `<rect x="${x}" y="${yc(a)}" width="32" height="${yc(0)-yc(a)}" fill="#0e60ff"><title>Model costs · ${m}: $${a}K</title></rect><rect x="${x}" y="${yc(a+b)}" width="32" height="${yc(0)-yc(b)}" fill="#7fb0ff"><title>Orchestration savings · ${m}: $${b}K</title></rect><rect x="${x}" y="${yc(a+b+c)}" width="32" height="${yc(0)-yc(c)}" rx="3" fill="#a78bfa"><title>Other AI costs · ${m}: $${c}K</title></rect><text x="${xs(i,6)}" y="${H-10}" text-anchor="middle" font-size="10.5" fill="currentColor" opacity=".7">${m}</text>`; }).join('')}
      <polyline fill="none" stroke="#c4b5fd" stroke-width="2.2" points="${EXD.tokens.map((v,i)=>xs(i,6)+','+yc(v/2)).join(' ')}"/>${EXD.tokens.map((v,i)=>`<circle cx="${xs(i,6)}" cy="${yc(v/2)}" r="3.4" fill="#c4b5fd"><title>Tokens · ${M[i]}: ${v}M</title></circle>`).join('')}</svg>`;
    const stat=(big,label,tr)=>`<div class="ex-stat"><div><b>${big}</b>${tr}</div><span>${label}</span></div>`;
    const sel=(id,val)=>`<select class="ex-sel sm" id="${id}">${['Last 3 Months','Last 6 Months'].map(r=>`<option${val===r?' selected':''}>${r}</option>`).join('')}</select>`;
    const projRows=list=>list.map(p=>`<tr><td><b class="ink">${p[0]}</b></td><td class="mut">${p[1]}</td><td class="mut">${p[2]}</td><td><div class="ex-prog"><div class="ex-bar"><i style="width:${p[3]}%;background:#0e60ff"></i></div><span>${p[3]}%</span></div></td><td><span class="ex-trend">↑ ${p[4]}</span></td></tr>`).join('');
    const modelsTotal=62;
    root.innerHTML = `<div class="ex-head ex-dash-head"><div><h2>Executive Dashboard</h2><p>Strategic insights on AI adoption, delivery performance, cost savings and business impact.</p></div>
        <div class="ex-head-btns"><span class="ex-date">${exI('clock',14)}1 Jan 2025 – 30 Jun 2025</span><select class="ex-sel" id="exd-range">${['Last 3 Months','Last 6 Months','Last 12 Months'].map(r=>`<option${EXD.range===r?' selected':''}>${r}</option>`).join('')}</select>${exBtn('Export Report','download','','exd-export')}</div></div>
      <div class="ex-kpis k5">
        ${exKpi('users','t-blue',USERS.length,'Total Users',`${ws} Developers | ${vw} Viewers | ${ad} Admins`,'<span class="ex-up">↑ 18%</span>')}
        ${exKpi('code','t-violet',28,'Active Projects','18 Development | 6 Modernization | 4 POCs','<span class="ex-up">↑ 33%</span>')}
        ${exKpi('clock','t-green','32%','Time to Delivery','Reduction in average delivery time','<span class="ex-up">↓</span>')}
        ${exKpi('db','t-amber','$248K','Estimated Cost Savings','Compared to traditional development','<span class="ex-up">↑ 28%</span>')}
        ${exKpi('pulse','t-teal','41%','Productivity Increase','More output per engineer')}
      </div>
      <div class="ex-grid g-2">
        <div class="ex-card"><div class="ex-sec-h"><div><h4>Project Delivery Performance</h4><p class="ex-sub">On-time delivery, cycle time and quality across all projects</p></div>${sel('exd-del',EXD.delRange)}</div>
          <div class="ex-chart-row"><div>${del}<ul class="ex-legend row"><li><i style="background:#0e60ff"></i>Planned</li><li><i style="background:#7fb0ff"></i>Completed</li><li><i style="background:#34d399"></i>On-time %</li></ul></div>
          <div class="ex-stats col">${stat('85%','On-time Delivery',exdTrend('12%',true))}${stat('6.2 weeks','Avg. Delivery Time',exdTrend('32%',false))}${stat('94%','Quality Score',exdTrend('8%',true))}</div></div></div>
        <div class="ex-card"><div class="ex-sec-h"><div><h4>AI Usage &amp; Cost Overview</h4><p class="ex-sub">Total AI consumption, cost optimization and savings</p></div>${sel('exd-cost',EXD.costRange)}</div>
          ${cost}<ul class="ex-legend row"><li><i style="background:#0e60ff"></i>Model Costs</li><li><i style="background:#7fb0ff"></i>Orchestration Savings</li><li><i style="background:#a78bfa"></i>Other AI Costs</li><li><i style="background:#c4b5fd"></i>Tokens (M)</li></ul>
          <div class="ex-stats">${stat('$86K','Total AI Cost',exdTrend('27%',false))}${stat('$42K','Orchestration Savings',exdTrend('33%',true))}${stat('62M','Tokens Used',exdTrend('18%',true))}${stat('35%','Cost Reduction',exdTrend('35%',false))}</div></div>
      </div>
      <div class="ex-grid g-2">
        <div class="ex-card"><div class="ex-sec-h"><div><h4>Top Projects by Business Value</h4><p class="ex-sub">Projects with highest impact on efficiency, cost and strategic goals</p></div><button class="ex-link" id="exd-proj-all">View All</button></div>
          <div class="ex-table-wrap"><table class="ex-table ex-compact"><thead><tr><th>Project Name</th><th>Type</th><th>Team</th><th>Progress</th><th>Business Impact</th></tr></thead><tbody>${projRows(EXD.projects.slice(0,5))}</tbody></table></div></div>
        <div class="ex-card"><div class="ex-sec-h"><div><h4>Productivity &amp; Adoption</h4><p class="ex-sub">Platform usage and adoption across teams</p></div><button class="ex-link" id="exd-adopt-all">View All</button></div>
          <div class="ex-rings">${exdRing(92,'Developer Adoption','92%',exdTrend('12%',true))}${exdRing(78,'Active Weekly Users','78%',exdTrend('18%',false))}${exdRing(64,'Avg. Tasks per User/Day','6.4',exdTrend('35%',true))}${exdRing(87,'Agent Success Rate','87%',exdTrend('9%',true))}</div></div>
      </div>
      <div class="ex-grid g-dash3">
        <div class="ex-card"><div class="ex-sec-h"><div><h4>Team Performance</h4><p class="ex-sub">Productivity and delivery metrics by department</p></div><button class="ex-link" id="exd-team-all">View All</button></div>
          <div class="ex-table-wrap"><table class="ex-table ex-team"><thead><tr><th>Department</th><th>Users</th><th>Active Users</th><th>Tasks/Day</th><th>Productivity Gain</th></tr></thead><tbody>${EXD.teams.map((t,i)=>`<tr><td><div class="ex-who"><span class="ex-dic d${i}">${exI(t[1],13)}</span><b>${t[0]}</b></div></td><td>${t[2]}</td><td>${t[3]} (${Math.round(t[3]/t[2]*100)}%)</td><td><div class="ex-prog"><div class="ex-bar"><i style="width:${t[4]/8*100}%;background:#0e60ff"></i></div><span>${t[4]}</span></div></td><td><span class="ex-trend">↑ ${t[5]}%</span></td></tr>`).join('')}</tbody></table></div></div>
        <div class="ex-card"><div class="ex-sec-h"><div><h4>AI Model Usage</h4><p class="ex-sub">Distribution of usage across different LLMs</p></div></div>
          <div class="ex-donut-row">${exDonut(EXD.models.map(m=>({v:m[1],c:m[2]})),modelsTotal+'M','Total Tokens',140)}<ul class="ex-legend">${EXD.models.map(m=>`<li><i style="background:${m[2]}"></i>${m[0]}<b>${m[1]}%</b></li>`).join('')}</ul></div></div>
        <div class="ex-card"><div class="ex-sec-h"><div><h4>Key Business Outcomes</h4><p class="ex-sub">Measured impact since platform adoption</p></div><button class="ex-link" id="exd-out-all">View All</button></div>
          <div class="ex-outs">${EXD.outcomes.map(o=>`<div><span class="ex-kpi-ic ${o[2]} xs">${exI('check',12)}</span><b>${o[0]}</b><span>${o[1]}</span></div>`).join('')}</div></div>
      </div>`;
    root.insertAdjacentHTML('beforeend', exExecMore());
    const on=(s,fn,ev)=>{ const el=root.querySelector(s); if(el) el.addEventListener(ev||'click',fn); };
    on('#exd-range',e=>{ EXD.range=e.target.value; exToast('Showing '+e.target.value.toLowerCase()); },'change');
    on('#exd-del',e=>{ EXD.delRange=e.target.value; exToast('Delivery performance · '+e.target.value.toLowerCase()); },'change');
    on('#exd-cost',e=>{ EXD.costRange=e.target.value; exToast('AI usage & cost · '+e.target.value.toLowerCase()); },'change');
    on('#exd-export',()=>exDownload('GlobalTech-Executive-Dashboard.csv',['Metric,Value','Total Users,'+USERS.length,'Active Projects,28','Time to Delivery,-32%','Estimated Cost Savings,$248K','Productivity Increase,41%','On-time Delivery,85%','Avg. Delivery Time,6.2 weeks','Quality Score,94%','Total AI Cost,$86K','Orchestration Savings,$42K','Tokens Used,62M','Cost Reduction,35%'].join('\n'),'text/csv'));
    on('#exd-proj-all',()=>exModal('All Projects by Business Value','',`<div class="ex-table-wrap"><table class="ex-table ex-compact"><thead><tr><th>Project Name</th><th>Type</th><th>Team</th><th>Progress</th><th>Business Impact</th></tr></thead><tbody>${projRows(EXD.projects)}</tbody></table></div>`,null,b=>b.querySelector('.um-modal').style.maxWidth='860px'));
    on('#exd-adopt-all',()=>exModal('Productivity & Adoption','Adoption by department over the selected period.',`<div class="ex-kv">${EXD.teams.map(t=>`<div><span>${t[0]}</span><b>${Math.round(t[3]/t[2]*100)}% active · ${t[4]} tasks per user/day</b></div>`).join('')}</div>`));
    on('#exd-team-all',()=>gotoTop('users'));
    on('#exd-out-all',()=>exModal('Key Business Outcomes','Measured impact since GlobalTech adopted the Xccelera AI Platform.',`<div class="ex-outs">${EXD.outcomes.concat([['3.4×','Faster legacy code conversion','t-blue'],['50%','Faster support ticket resolution','t-green']]).map(o=>`<div><span class="ex-kpi-ic ${o[2]} xs">${exI('check',12)}</span><b>${o[0]}</b><span>${o[1]}</span></div>`).join('')}</div>`));
  }

  /* ─────────────── PLATFORM STUDIO DASHBOARD ─────────────── */
  const STD = {range:'Last 6 Months', agentRange:'Last 6 Months', modelRange:'Last 6 Months',
    sdlc:[['Requirements',10,6,40],['Design & Architecture',15,9,40],['Development',20,13,35],['Testing',12,6,50],['Deployment',5,3,40]],
    health:[['On Track',18,'#34d399'],['At Risk',6,'#3b82f6'],['Delayed',3,'#fbbf24'],['Completed',1,'#94a3b8']],
    stack:[['Python',28,'code'],['JavaScript / TypeScript',22,'code'],['Java',15,'code'],['.NET',10,'code'],['Go',8,'code'],['React / Next.js',18,'grid'],['Others',9,'dots']],
    agents:[['Requirements Agent','doc',86,'1.2s',[3,4,4,5,6,6,7]],['Architecture Agent','building',83,'0.9s',[2,3,3,4,5,5,6]],['Code Agent','code',91,'1.1s',[3,4,5,5,6,7,8]],['Test Agent','test',88,'1.4s',[2,3,4,4,5,6,7]],['Review Agent','shieldok',93,'1.0s',[4,4,5,6,6,7,8]],['Bug Fix Agent','alert',87,'1.3s',[2,3,3,5,5,6,7]],['Documentation Agent','book',85,'1.1s',[3,3,4,4,5,6,6]]],
    quality:[['94%','Code Quality Score','↑ 8%','shieldok','t-green'],['78%','Test Coverage','↑ 12%','test','t-blue'],['36%','Reduction in Defects','↓ 36%','alert','t-rose'],['2.1 days','Avg. PR Cycle Time','↓ 41%','clock','t-violet']],
    projects:[['Customer Portal 2.0','Development','Platform',80,'320 hrs','$48K','On Track'],['Legacy System Migration','Modernization','Core Eng.',65,'480 hrs','$72K','At Risk'],['AI Support Assistant','Internal Tool','IT Ops',95,'600 hrs','$90K','On Track'],['Data Analytics Platform','Development','Data Team',60,'280 hrs','$42K','Delayed'],['Mobile App Enhancement','Development','Product',75,'340 hrs','$51K','On Track'],['Partner API Gateway','Development','Platform',45,'150 hrs','$23K','On Track'],['Mainframe Billing Rewrite','Modernization','Core Eng.',30,'210 hrs','$31K','At Risk']],
    insights:[['32%','Faster time to delivery'],['28%','Higher developer productivity'],['36%','Reduction in production defects'],['41%','More code reviewed with AI']]
  };
  const STD_ST = {'On Track':'st-approved','At Risk':'st-pending','Delayed':'st-suspended','Completed':'st-none'};
  function stdSpark(arr,c){ const w=90,h=26,mx=Math.max(...arr),mn=Math.min(...arr); const pts=arr.map((v,i)=>(i*(w/(arr.length-1))).toFixed(1)+','+(h-3-((v-mn)/(mx-mn||1))*(h-6)).toFixed(1)).join(' ');
    return `<svg viewBox="0 0 ${w} ${h}" class="ex-spark" aria-hidden="true"><polyline fill="none" stroke="${c}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" points="${pts}"/></svg>`; }
  function entRenderStudioDash(){
    const root=$('#stu-dash'); if(!root) return;
    const sel=(id,val)=>`<select class="ex-sel sm" id="${id}">${['Last 3 Months','Last 6 Months'].map(r=>`<option${val===r?' selected':''}>${r}</option>`).join('')}</select>`;
    /* SDLC grouped bars */
    const W=520,H=210,P=34, n=STD.sdlc.length, slot=(W-P*2)/n, y=v=>H-44-(v/20)*(H-70);
    const sdlc=`<svg class="ex-chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="Days per SDLC phase, traditional vs with Xccelera AI">
      <text x="10" y="${(H-44)/2+10}" font-size="10" fill="currentColor" opacity=".6" transform="rotate(-90 10 ${(H-44)/2+10})" text-anchor="middle">Time (Days)</text>
      ${[0,5,10,15,20].map(v=>`<line x1="${P}" x2="${W-8}" y1="${y(v)}" y2="${y(v)}" stroke="currentColor" stroke-opacity=".1"/><text x="${P-6}" y="${y(v)+3}" text-anchor="end" font-size="10" fill="currentColor" opacity=".6">${v}</text>`).join('')}
      ${STD.sdlc.map((s,i)=>{ const cx=P+slot*(i+.5); const lbl=s[0].split(' & ');
        return `<rect x="${cx-27}" y="${y(s[1])}" width="26" height="${y(0)-y(s[1])}" rx="3" fill="#7fb0ff"><title>Traditional · ${s[0]}: ${s[1]} days</title></rect><text x="${cx-14}" y="${y(s[1])-5}" text-anchor="middle" font-size="11" font-weight="700" fill="currentColor">${s[1]}</text>
          <rect x="${cx+1}" y="${y(s[2])}" width="26" height="${y(0)-y(s[2])}" rx="3" fill="#0e60ff"><title>With Xccelera AI · ${s[0]}: ${s[2]} days</title></rect><text x="${cx+14}" y="${y(s[2])-5}" text-anchor="middle" font-size="11" font-weight="700" fill="currentColor">${s[2]}</text>
          ${lbl.map((l,k)=>`<text x="${cx}" y="${H-28+k*12}" text-anchor="middle" font-size="10.5" fill="currentColor" opacity=".75">${l}${k===0&&lbl.length>1?' &amp;':''}</text>`).join('')}`; }).join('')}</svg>
      <div class="ex-sdlc-chips" style="grid-template-columns:repeat(${n},1fr)">${STD.sdlc.map(s=>`<span>↓ ${s[3]}%</span>`).join('')}</div>`;
    const ht=STD.health.reduce((a,h)=>a+h[1],0);
    root.innerHTML = `<div class="ex-head ex-dash-head"><div><h2>Studio Dashboard</h2><p>Engineering performance, architecture health, AI adoption and delivery insights.</p></div>
        <div class="ex-head-btns"><span class="ex-date">${exI('clock',14)}1 Jan 2025 – 30 Jun 2025</span><select class="ex-sel" id="std-range">${['Last 3 Months','Last 6 Months','Last 12 Months'].map(r=>`<option${STD.range===r?' selected':''}>${r}</option>`).join('')}</select>${exBtn('Export Report','download','','std-export')}</div></div>
      <div class="ex-kpis k5">
        ${exKpi('code','t-blue',28,'Active Projects','18 Development | 6 Modernization | 4 POCs','<span class="ex-up">↑ 33%</span>')}
        ${exKpi('users','t-teal',100,'Engineering Users','80 Developers | 10 QA | 5 DevOps | 5 Others','<span class="ex-up">↑ 12%</span>')}
        ${exKpi('chip','t-blue',7,'AI Agents in Use','BackendX, FrontendX, IntegrationX and 4 more','<span class="ex-up">100% Adoption</span>')}
        ${exKpi('db','t-rose','6 <small>LLMs</small>','Model Usage','Claude | GPT-4o | Llama | Gemini | Others')}
        ${exKpi('shieldok','t-green','94%','Code Quality Score','Based on AI review &amp; test coverage','<span class="ex-up">↑ 8%</span>')}
      </div>
      <div class="ex-grid g-std1">
        <div class="ex-card"><div class="ex-sec-h"><div><h4>Development Lifecycle Performance</h4><p class="ex-sub">AI assisted vs. traditional development metrics across SDLC phases</p></div><ul class="ex-legend row"><li><i style="background:#7fb0ff"></i>Traditional</li><li><i style="background:#0e60ff"></i>With Xccelera AI</li></ul></div>${sdlc}</div>
        <div class="ex-card"><div class="ex-sec-h"><div><h4>Project Health Overview</h4><p class="ex-sub">Real-time status of all engineering projects</p></div><button class="ex-link" id="std-health-all">View All</button></div>
          <div class="ex-donut-row col">${exDonut(STD.health.map(h=>({v:h[1],c:h[2]})),ht,'Projects',150)}<ul class="ex-legend">${STD.health.map(h=>`<li><i style="background:${h[2]}"></i>${h[0]}<b>${h[1]} (${Math.round(h[1]/ht*100)}%)</b></li>`).join('')}</ul></div></div>
        <div class="ex-card"><h4 class="ex-h4">Technology Stack</h4><p class="ex-sub">Languages, frameworks and platforms in use</p>
          <div class="ex-stack">${STD.stack.map(s=>`<div><span class="ex-tr-ic">${exI(s[2],13)}</span><b>${s[0]}</b><div class="ex-bar"><i style="width:${s[1]/28*100}%;background:#0e60ff"></i></div><em>${s[1]}%</em></div>`).join('')}</div></div>
      </div>
      <div class="ex-grid g-std2">
        <div class="ex-card"><div class="ex-sec-h"><div><h4>AI Agent Adoption &amp; Usage</h4><p class="ex-sub">Usage of Xccelera AI agents across the development lifecycle</p></div>${sel('std-agents',STD.agentRange)}</div>
          <div class="ex-agents">${STD.agents.map((a,i)=>`<button class="ex-agent" data-agent="${i}"><span class="ex-kpi-ic ${['t-green','t-blue','t-violet','t-amber','t-green','t-rose','t-blue'][i]} sm">${exI(a[1],16)}</span><b>${a[0].replace(' Agent','<br>Agent')}</b><strong>${a[2]}%</strong><small>Success Rate</small><strong class="sm">${a[3]}</strong><small>Avg. Latency</small>${stdSpark(a[4],['#34d399','#3b82f6','#a78bfa','#fbbf24','#34d399','#fb7185','#3b82f6'][i])}</button>`).join('')}</div></div>
        <div class="ex-card"><div class="ex-sec-h"><h4>Code Quality &amp; Engineering Metrics</h4><button class="ex-link" id="std-quality">View Details</button></div>
          <div class="ex-qgrid">${STD.quality.map(q=>`<div class="ex-q"><span class="ex-kpi-ic ${q[4]}">${exI(q[3],22)}</span><div><b>${q[0]}</b><span>${q[1]}</span></div><em class="ex-trend">${q[2]}</em></div>`).join('')}</div></div>
      </div>
      <div class="ex-grid g-std3">
        <div class="ex-card"><div class="ex-sec-h"><h4>Top Projects by Engineering Impact</h4><button class="ex-link" id="std-proj-all">View All</button></div>
          <div class="ex-table-wrap"><table class="ex-table ex-compact"><thead><tr><th>Project</th><th>Type</th><th>Team</th><th>Progress</th><th>Time Saved</th><th>Cost Saved</th><th>Status</th></tr></thead><tbody>${stdProjRows(STD.projects.slice(0,5))}</tbody></table></div></div>
        <div class="ex-card"><div class="ex-sec-h"><h4>Model Usage Distribution</h4>${sel('std-models',STD.modelRange)}</div>
          <div class="ex-donut-row">${exDonut(EXD.models.map(m=>({v:m[1],c:m[2]})),'62M','Total Tokens',140)}<ul class="ex-legend">${EXD.models.map(m=>`<li><i style="background:${m[2]}"></i>${m[0]}<b>${m[1]}%</b></li>`).join('')}</ul></div></div>
        <div class="ex-card"><h4 class="ex-h4 ex-ins-h">${exI('sparkle',16)} Key Insights</h4><p class="ex-sub">AI analysis of engineering performance</p>
          <div class="ex-outs">${STD.insights.map(o=>`<div><span class="ex-kpi-ic t-green xs">↑</span><b>${o[0]}</b><span>${o[1]}</span></div>`).join('')}<div><span class="ex-kpi-ic t-blue xs">${exI('info',12)}</span><span style="grid-column:2/-1">7 out of 10 teams actively using AI agents</span></div></div></div>
      </div>`;
    root.insertAdjacentHTML('beforeend', exStudioMore());
    const on=(s,fn,ev)=>{ const el=root.querySelector(s); if(el) el.addEventListener(ev||'click',fn); };
    ['std-range','std-agents','std-models'].forEach(id=>on('#'+id,e=>{ STD[id==='std-range'?'range':id==='std-agents'?'agentRange':'modelRange']=e.target.value; exToast('Showing '+e.target.value.toLowerCase()); },'change'));
    on('#std-export',()=>exDownload('Studio-Dashboard.csv',['Metric,Value','Active Projects,28','Engineering Users,100','AI Agents in Use,7','Model Usage,6 LLMs','Code Quality Score,94%'].concat(STD.sdlc.map(s=>s[0]+' (days traditional / with AI),'+s[1]+' / '+s[2])).concat(STD.agents.map(a=>a[0]+' success rate,'+a[2]+'%')).join('\n'),'text/csv'));
    on('#std-health-all',()=>gotoTop('projects'));
    on('#std-proj-all',()=>exModal('Projects by Engineering Impact','',`<div class="ex-table-wrap"><table class="ex-table ex-compact"><thead><tr><th>Project</th><th>Type</th><th>Team</th><th>Progress</th><th>Time Saved</th><th>Cost Saved</th><th>Status</th></tr></thead><tbody>${stdProjRows(STD.projects)}</tbody></table></div>`,'<button class="um-btn" data-close>Close</button><button class="um-btn primary" id="std-open-proj">Open Projects</button>',(b,close)=>{ b.querySelector('.um-modal').style.maxWidth='900px'; b.querySelector('#std-open-proj').onclick=()=>{ close(); gotoTop('projects'); }; }));
    on('#std-quality',()=>exModal('Code Quality & Engineering Metrics','Measured across all Platform Studio projects in the selected period.',`<div class="ex-kv">${[['Code Quality Score','94% (↑ 8%)'],['Test Coverage','78% (↑ 12%)'],['Defects reaching production','↓ 36%'],['Avg. PR Cycle Time','2.1 days (↓ 41%)'],['PRs reviewed by AI','1,284'],['Critical vulnerabilities open','0']].map(r=>`<div><span>${r[0]}</span><b>${r[1]}</b></div>`).join('')}</div>`));
    root.querySelectorAll('[data-agent]').forEach(b=>b.onclick=()=>{ const a=STD.agents[+b.dataset.agent]; exModal(a[0],'Usage in the selected period.',`<div class="ex-kv"><div><span>Success Rate</span><b>${a[2]}%</b></div><div><span>Avg. Latency</span><b>${a[3]}</b></div><div><span>Trend</span><b>${stdSpark(a[4],'#3b82f6')}</b></div></div>`,'<button class="um-btn" data-close>Close</button><button class="um-btn primary" id="std-open-ai">Open AI Tools</button>',(m,close)=>{ m.querySelector('#std-open-ai').onclick=()=>{ close(); gotoTop('orchestrator'); }; }); });
  }
  function stdProjRows(list){ return list.map(p=>`<tr><td><b class="ink">${p[0]}</b></td><td class="mut">${p[1]}</td><td class="mut">${p[2]}</td><td><div class="ex-prog"><div class="ex-bar"><i style="width:${p[3]}%;background:#0e60ff"></i></div><span>${p[3]}%</span></div></td><td class="ok-t">${p[4]}</td><td class="ok-t">${p[5]}</td><td><span class="ex-st ${STD_ST[p[6]]}">${p[6]}</span></td></tr>`).join(''); }

  /* ─────────────── THEME (light / dark) ─────────────── */
  function xcTheme(){ return document.documentElement.dataset.theme==='light'?'light':'dark'; }
  function xcSetTheme(t,quiet){
    document.documentElement.dataset.theme=t;
    try{ localStorage.setItem('xc-ui-theme',t); }catch(e){}
    $$('.theme-btn').forEach(b=>{ b.setAttribute('aria-label','Switch to '+(t==='light'?'dark':'light')+' theme'); });
    const f=$('#kg-frame'); if(f){ f.dataset.theme=t; try{ if(f.contentWindow&&f.contentWindow.applyTheme) f.contentWindow.applyTheme(t); }catch(e){} }
    if(window.restartLoginDots) window.restartLoginDots();
    if(!quiet) exToast((t==='light'?'Light':'Dark')+' theme on');
  }
  (function initTheme(){
    let t=null; try{ t=localStorage.getItem('xc-ui-theme'); }catch(e){}
    if(t!=='light'&&t!=='dark') t='light';
    xcSetTheme(t,true);
    document.addEventListener('click',e=>{ const b=e.target.closest('.theme-btn'); if(b){ e.preventDefault(); xcSetTheme(xcTheme()==='light'?'dark':'light'); } });
  })();

  /* ─────────────── KNOWLEDGE GRAPH (Platform Studio) ─────────────── */
  function entOpenKG(){
    const f=$('#kg-frame'), tpl=document.getElementById('kg-src'); if(!f) return;
    f.dataset.theme=xcTheme();
    if(!f.dataset.loaded){
      if(!tpl){ $('#kg-wait').textContent='The knowledge graph could not be loaded.'; return; }
      f.dataset.loaded='1';
      f.addEventListener('load',()=>{ const w=$('#kg-wait'); if(w) w.hidden=true; try{ f.contentWindow.applyTheme(xcTheme()); }catch(e){} },{once:true});
      setTimeout(()=>{ f.srcdoc='<!doctype html>'+tpl.innerHTML; },30);
    } else { try{ f.contentWindow.applyTheme(xcTheme()); }catch(e){} }
  }

  /* profile + sign out move to the bottom of the side navigation */
  (function moveIdentityToSide(){
    const aside=$('#app-aside'), prof=document.querySelector('#app-header .profile'), so=$('#signout-btn');
    if(!aside||!prof) return;
    const foot=document.createElement('div'); foot.className='side-foot';
    foot.appendChild(prof); if(so) foot.appendChild(so);
    aside.appendChild(foot);
  })();

  /* mobile: hamburger opens the side navigation full screen */
  (function mobileNav(){
    const hdr=$('#app-header'), aside=$('#app-aside'); if(!hdr||!aside) return;
    const mk=(cls,label,path)=>{ const b=document.createElement('button'); b.type='button'; b.className=cls; b.setAttribute('aria-label',label); b.title=label; b.innerHTML=`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round">${path}</svg>`; return b; };
    const open=mk('nav-menu-btn','Open menu','<path d="M3 6h18M3 12h18M3 18h18"/>');
    const close=mk('nav-close-btn','Close menu','<path d="M18 6 6 18M6 6l12 12"/>');
    hdr.insertBefore(open,hdr.firstChild);
    const top=aside.querySelector('.side-top-row'); if(top) top.appendChild(close);
    const set=v=>{ document.body.classList.toggle('nav-open',v); open.setAttribute('aria-expanded',v); };
    open.onclick=()=>set(true); close.onclick=()=>set(false);
    aside.addEventListener('click',e=>{ if(e.target.closest('.nav-item,.side-suite-body [data-tool],.side-suite-item,.side-foot .profile')) setTimeout(()=>set(false),60); });
    document.addEventListener('keydown',e=>{ if(e.key==='Escape') set(false); });
    window.addEventListener('resize',()=>{ if(innerWidth>960) set(false); });
  })();

  /* ─────────────── ADDITIONAL DASHBOARD CHARTS (chart version) ─────────────── */
  const CHX = {
    months:['Jan','Feb','Mar','Apr','May','Jun'],
    seatsLic:[115,115,115,115,115,115], seatsUsed:[70,76,81,85,89,92],
    savings:[['Engineering',142],['Product',38],['QA',27],['Operations',21],['Finance',12],['Executive Office',8]],
    wau:[52,55,58,61,63,66,68,71,73,75,77,78],
    ptype:[['Development',[12,4,1,1]],['Modernization',[3,2,1,0]],['POC',[3,0,1,0]]],
    pstat:[['On Track','#34d399'],['At Risk','#3b82f6'],['Delayed','#fbbf24'],['Completed','#94a3b8']],
    deployProd:[6,7,5,8,9,8,10,11,9,12,13,14], deployStg:[10,12,11,13,14,15,15,17,16,18,19,20],
    prDays:[3.6,3.4,3.1,2.9,2.7,2.5,2.4,2.3,2.2,2.2,2.1,2.1],
    found:[42,38,35,31,28,26], fixed:[36,37,36,33,30,28],
    days:['Mon','Tue','Wed','Thu','Fri','Sat','Sun'], slots:['00','02','04','06','08','10','12','14','16','18','20','22']
  };
  const chxWeeks = n=>Array.from({length:n},(_,i)=>'W'+(i+1));
  function chxAxis(W,H,P,max,steps,fmt,yfn){ return Array.from({length:steps+1},(_,i)=>{ const v=max/steps*i, y=yfn(v); return `<line x1="${P}" x2="${W-10}" y1="${y}" y2="${y}" stroke="currentColor" stroke-opacity=".1"/><text x="${P-6}" y="${y+3}" text-anchor="end" font-size="10" fill="currentColor" opacity=".6">${fmt(v)}</text>`; }).join(''); }
  function chxLine(labels,series,opt){
    const PT=!!opt.portrait, W=PT?340:520,H=PT?300:210,P=36,B=26, max=opt.max, n=labels.length, x=i=>P+i*((W-P-14)/(n-1)), y=v=>H-B-(v/max)*(H-B-14);
    let s=`<svg class="ex-chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="${opt.label}">${chxAxis(W,H,P,max,opt.steps||4,opt.fmt||(v=>Math.round(v)),y)}`;
    s+=labels.map((m,i)=>(n<=(PT?6:8)||i%(PT?3:2)===0)?`<text x="${x(i)}" y="${H-8}" text-anchor="middle" font-size="10" fill="currentColor" opacity=".65">${m}</text>`:'').join('');
    series.forEach(se=>{ const pts=se.v.map((v,i)=>x(i)+','+y(v)).join(' ');
      if(se.area) s+=`<polygon points="${x(0)},${y(0)} ${pts} ${x(n-1)},${y(0)}" fill="${se.c}" fill-opacity=".14"/>`;
      s+=`<polyline fill="none" stroke="${se.c}" stroke-width="2.4" ${se.dash?'stroke-dasharray="5 4"':''} stroke-linejoin="round" points="${pts}"/>`;
      if(!se.dash) s+=se.v.map((v,i)=>`<circle cx="${x(i)}" cy="${y(v)}" r="3.2" fill="${se.c}"><title>${se.n} · ${labels[i]}: ${(opt.fmt||(v=>v))(v)}</title></circle>`).join(''); });
    return s+'</svg>';
  }
  function chxBars(labels,series,opt){
    if(opt.portrait) return chxBarsH(labels,series,opt);
    const W=520,H=210,P=36,B=26,max=opt.max,n=labels.length,slot=(W-P-10)/n,bw=Math.min(22,slot*.6),y=v=>H-B-(v/max)*(H-B-14);
    let s=`<svg class="ex-chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="${opt.label}">${chxAxis(W,H,P,max,opt.steps||4,v=>Math.round(v),y)}`;
    labels.forEach((m,i)=>{ const cx=P+slot*(i+.5);
      if(opt.stack){ let acc=0; series.forEach((se,k)=>{ const v=se.v[i]; s+=`<rect x="${cx-bw/2}" y="${y(acc+v)}" width="${bw}" height="${y(acc)-y(acc+v)}" ${k===series.length-1?'rx="3"':''} fill="${se.c}"><title>${se.n} · ${m}: ${v}</title></rect>`; acc+=v; }); }
      else { const g=series.length, w=bw/g*1.4; series.forEach((se,k)=>{ const v=se.v[i], bx=cx-(w*g)/2+k*w; s+=`<rect x="${bx}" y="${y(v)}" width="${w-2}" height="${y(0)-y(v)}" rx="3" fill="${se.c}"><title>${se.n} · ${m}: ${v}</title></rect>`; }); }
      if(n<=8||i%2===0) s+=`<text x="${cx}" y="${H-8}" text-anchor="middle" font-size="10" fill="currentColor" opacity=".65">${m}</text>`; });
    return s+'</svg>';
  }
  function chxBarsH(labels,series,opt){
    const tot=i=>series.reduce((a,se)=>a+se.v[i],0), mx=opt.stack?Math.max(...labels.map((m,i)=>tot(i))):opt.max;
    return `<div class="chx-hb" role="img" aria-label="${opt.label}">${labels.map((m,i)=>`<div class="chx-hb-r"><b>${m}</b><div class="chx-hb-t${opt.stack?'':' grp'}">${series.map(se=>`<i style="${opt.stack?'width':'--w'}:${(se.v[i]/mx*100).toFixed(1)}%;background:${se.c}" title="${se.n} · ${m}: ${se.v[i]}"></i>`).join('')}</div><em>${opt.stack?tot(i):series.map(se=>se.v[i]).join(' / ')}</em></div>`).join('')}</div>`;
  }
  const chxLegend = items=>`<ul class="ex-legend row">${items.map(i=>`<li><i style="background:${i[1]}"></i>${i[0]}</li>`).join('')}</ul>`;
  const CHX_REG = {};
  /* compact tile: title + small chart only; the full chart, legend and figures open in a modal */
  function chxCard(title,sub,mk){
    const id='chx_'+title.replace(/[^a-z]/gi,'');
    const body=typeof mk==='function'?mk({}):mk;
    CHX_REG[id]={title,sub,mk:typeof mk==='function'?mk:()=>body};
    const viz=body.split(/<ul class="ex-legend|<div class="ex-stats|<div class="chx-heat-key/)[0];
    return `<button type="button" class="ex-card chx-tile" data-chx="${id}" aria-label="Open ${title.replace(/&amp;/g,'&')} chart">
      <div class="chx-tile-h"><h4>${title}</h4><span class="chx-open" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M15 3h6v6M9 21H3v-6M21 3l-7 7M3 21l7-7"/></svg></span></div>
      <p class="ex-sub">${sub}</p><div class="chx-tile-viz">${viz}</div></button>`;
  }
  document.addEventListener('click',e=>{ const t=e.target.closest('[data-chx]'); if(!t) return; const c=CHX_REG[t.dataset.chx]; if(!c) return;
    const port=()=>window.matchMedia('(orientation: portrait) and (max-width: 820px)').matches||innerWidth<560;
    exModal(c.title,c.sub,`<div class="chx-full"></div>`,null,b=>{ b.querySelector('.um-modal').classList.add('chx-modal');
      const host=b.querySelector('.chx-full'); let cur=null;
      const draw=()=>{ const pm=port(); if(pm===cur) return; cur=pm; host.className='chx-full '+(pm?'is-portrait':'is-landscape'); host.innerHTML=c.mk({portrait:pm}); };
      draw(); const on=()=>{ if(!document.body.contains(b)){ removeEventListener('resize',on); return; } draw(); };
      addEventListener('resize',on); addEventListener('orientationchange',on); }); });
  const chxStatRow = arr=>`<div class="ex-stats">${arr.map(a=>`<div class="ex-stat"><div><b>${a[0]}</b>${a[2]?`<span class="ex-trend">${a[2]}</span>`:''}</div><span>${a[1]}</span></div>`).join('')}</div>`;

  function exExecMore(){
    const totSave=CHX.savings.reduce((a,b)=>a+b[1],0), maxS=CHX.savings[0][1];
    const seats=chxCard('License &amp; Seat Usage','Seats in use against licensed seats, month by month',o=>chxLine(CHX.months,[{n:'Licensed seats',v:CHX.seatsLic,c:'#94a3b8',dash:true},{n:'Seats in use',v:CHX.seatsUsed,c:'#0e60ff',area:true}],{max:125,steps:5,label:'Seat usage trend',portrait:o.portrait})+
      chxLegend([['Seats in use','#0e60ff'],['Licensed seats','#94a3b8']])+chxStatRow([['92 / 115','Seats in use','↑ 31%'],['80%','Utilisation'],['23','Seats available']]));
    const save=chxCard('Cost Savings by Department','Estimated savings compared to traditional development',o=>`<div class="chx-hbars">${CHX.savings.map((d,i)=>`<div><b>${d[0]}</b><div class="ex-bar"><i style="width:${d[1]/maxS*100}%;background:${['#0e60ff','#3b82f6','#60a5fa','#7fb0ff','#a78bfa','#c4b5fd'][i]}"></i></div><em>$${d[1]}K</em></div>`).join('')}</div>`+
      chxStatRow([['$'+totSave+'K','Total savings','↑ 28%'],['57%','From Engineering'],['$2.1K','Per user']]));
    const wau=chxCard('Adoption Trend','Weekly active users as a share of all licensed users',o=>chxLine(chxWeeks(12),[{n:'Weekly active users',v:CHX.wau,c:'#34d399',area:true}],{max:100,steps:4,fmt:v=>Math.round(v)+'%',label:'Weekly active users trend',portrait:o.portrait})+
      chxStatRow([['78%','This week','↑ 26 pts'],['93','Active users'],['12 wks','Period']]));
    const tot=t=>t[1].reduce((a,b)=>a+b,0);
    const ptype=chxCard('Projects by Type &amp; Status','Where the 28 active projects stand',o=>`<div class="chx-stack">${CHX.ptype.map(t=>`<div><div class="chx-stack-h"><b>${t[0]}</b><span>${tot(t)} projects</span></div><div class="chx-seg">${t[1].map((v,k)=>v?`<i style="flex:${v};background:${CHX.pstat[k][1]}" title="${CHX.pstat[k][0]}: ${v}">${v}</i>`:'').join('')}</div></div>`).join('')}</div>`+
      chxLegend(CHX.pstat.map(s=>[s[0],s[1]])));
    return `<div class="chx-row">${seats}${save}${wau}${ptype}</div>`;
  }

  function exStudioMore(){
    const dep=chxCard('Deployments per Week','Releases shipped by Platform Studio pipelines',o=>chxBars(chxWeeks(12),[{n:'Production',v:CHX.deployProd,c:'#0e60ff'},{n:'Staging',v:CHX.deployStg,c:'#7fb0ff'}],{max:35,steps:5,stack:true,label:'Deployments per week',portrait:o.portrait})+
      chxLegend([['Production','#0e60ff'],['Staging','#7fb0ff']])+chxStatRow([['14','Production this week','↑ 133%'],['316','Total deployments'],['0.8%','Rollback rate']]));
    const pr=chxCard('PR Cycle Time Trend','Average days from pull request opened to merged',o=>chxLine(chxWeeks(12),[{n:'Avg. PR cycle time',v:CHX.prDays,c:'#a78bfa',area:true}],{max:4,steps:4,fmt:v=>v.toFixed(1)+'d',label:'PR cycle time trend',portrait:o.portrait})+
      chxStatRow([['2.1 days','Current','↓ 41%'],['1,284','PRs reviewed by AI'],['6.2 hrs','First review']]));
    // heatmap — agent runs by day and 2-hour slot
    const val=(d,s)=>{ const work=d<5, peak=s>=4&&s<=9; return Math.round((work?(peak?70:22):(peak?18:6))+((d*7+s*13)%17)); };
    let mx=0; for(let d=0;d<7;d++)for(let s=0;s<12;s++) mx=Math.max(mx,val(d,s));
    const heatKey=`<div class="chx-heat-key"><span>Fewer</span><i style="--a:.12"></i><i style="--a:.35"></i><i style="--a:.6"></i><i style="--a:.85"></i><i style="--a:1"></i><span>More runs</span></div>`;
    const heatP=()=>`<div class="chx-heat chx-heat-p"><span></span>${CHX.days.map(d=>`<small>${d}</small>`).join('')}${CHX.slots.map((sl,s)=>`<small>${sl}:00</small>${CHX.days.map((dn,d)=>{ const v=val(d,s); return `<i style="--a:${(0.08+0.92*v/mx).toFixed(2)}" title="${dn} ${sl}:00 — ${v} runs"></i>`; }).join('')}`).join('')}</div>`+heatKey;
    const heat=o=>o.portrait?heatP():`<div class="chx-heat"><span></span>${CHX.slots.map(s=>`<small>${s}</small>`).join('')}${CHX.days.map((dn,d)=>`<small>${dn}</small>${CHX.slots.map((sl,s)=>{ const v=val(d,s); return `<i style="--a:${(0.08+0.92*v/mx).toFixed(2)}" title="${dn} ${sl}:00 — ${v} runs"></i>`; }).join('')}`).join('')}</div>
      <div class="chx-heat-key"><span>Fewer</span><i style="--a:.12"></i><i style="--a:.35"></i><i style="--a:.6"></i><i style="--a:.85"></i><i style="--a:1"></i><span>More runs</span></div>`;
    const hm=chxCard('Agent Runs Heatmap','When agents run across the week (hour of day)',o=>heat(o)+chxStatRow([['Tue 10:00','Busiest slot'],['4,860','Runs this week','↑ 22%'],['91%','Run on weekdays']]));
    const df=chxCard('Defects Found vs Fixed','Defects raised by AI review and tests, and how many were fixed',o=>chxBars(CHX.months,[{n:'Found',v:CHX.found,c:'#fb7185'},{n:'Fixed',v:CHX.fixed,c:'#34d399'}],{max:50,steps:5,label:'Defects found vs fixed',portrait:o.portrait})+
      chxLegend([['Found','#fb7185'],['Fixed','#34d399']])+chxStatRow([['26','Found in Jun','↓ 38%'],['28','Fixed in Jun'],['1.4 days','Avg. time to fix']]));
    return `<div class="chx-row">${dep}${pr}${hm}${df}</div>`;
  }

  /* ─────────────── USER DETAIL PAGE (Users & Roles → click a user) ─────────────── */
  function udSeed(u){ let h=0; for(const c of u.id+u.email) h=(h*31+c.charCodeAt(0))>>>0; return ()=>{ h=(h*1103515245+12345)>>>0; return (h>>>8)/16777216; }; }
  function udData(u){
    const r=udSeed(u), rs=userRoles(u);
    const studio=rs.some(x=>ROLE_DEF[x]&&ROLE_DEF[x].access.studio);
    const readOnly=rs.every(x=>x==='viewer'||x==='org-admin');
    const toolIds = studio ? (toolsForUser(u).length?toolsForUser(u):SUITE_TOOLS.map(t=>t.id)) : [];
    const projList=(typeof PROJECTS!=='undefined'&&Array.isArray(PROJECTS))?PROJECTS:[];
    const nProj = !studio ? 0 : u.license==='admin' ? Math.min(projList.length,5) : u.license==='viewer' ? Math.min(projList.length,3) : 2+Math.floor(r()*Math.max(1,projList.length-2));
    const projects = projList.slice().sort(()=>r()-.5).slice(0,nProj).map((p,i)=>({p, role: readOnly?'Viewer':(i===0&&rs.includes('pm')?'Lead':rs.includes('pm')?'Manager':'Contributor'), hours: readOnly?Math.round(2+r()*10):Math.round(18+r()*120), runs: readOnly?0:Math.round(6+r()*60)}));
    const active = u.status==='approved';
    const toolUse = toolIds.map(id=>({t:SUITE_TOOLS.find(x=>x.id===id), runs: readOnly||!active?0:Math.round(r()*r()*140)})).filter(x=>x.t).sort((a,b)=>b.runs-a.runs);
    const totalRuns=toolUse.reduce((a,b)=>a+b.runs,0);
    const weeks=Array.from({length:12},(_,i)=>!active?0:readOnly?Math.round(r()*6):Math.round(totalRuns/12*(0.55+i*0.06)*(0.8+r()*0.4)));
    const views=Array.from({length:12},(_,i)=>!active?0:Math.round(4+r()*14+i));
    return {studio,readOnly,active,projects,toolUse,totalRuns,weeks,views,toolIds,
      hours: projects.reduce((a,b)=>a+b.hours,0), saved: Math.round(projects.reduce((a,b)=>a+b.hours,0)*0.34),
      success: totalRuns? (88+r()*10).toFixed(1)+'%':'—'};
  }
  const UD_COLORS=['#0e60ff','#3b82f6','#60a5fa','#a78bfa','#34d399','#fbbf24','#fb7185'];
  function udPage(u){
    const d=udData(u), rs=userRoles(u), ed=exCanEdit('users');
    const roleName=x=>{ const r=USER_ROLES.find(y=>y.value===x); return r?r.label:x; };
    const portals=['enterprise','studio'].map(p=>`<span class="ud-portal ${canEnterPortal(u,p)?'y':'n'}">${exI(canEnterPortal(u,p)?'check':'x',12)}${PORTALS[p].label}</span>`).join('');
    const empty=(t)=>`<div class="ud-empty">${exI('info',18)}<span>${t}</span></div>`;
    /* project involvement */
    const maxH=Math.max(1,...d.projects.map(x=>x.hours));
    const projCard=`<div class="ex-card"><div class="ex-sec-h"><div><h4>Project Involvement</h4><p class="ex-sub">Hours contributed to each Platform Studio project</p></div><span class="ud-count">${d.projects.length} project${d.projects.length===1?'':'s'}</span></div>
      ${d.projects.length?`<div class="chx-hbars">${d.projects.map((x,i)=>`<div><b title="${exEsc(x.p.name)}">${exEsc(x.p.name)}</b><div class="ex-bar"><i style="width:${x.hours/maxH*100}%;background:${UD_COLORS[i%UD_COLORS.length]}"></i></div><em>${x.hours}h</em></div>`).join('')}</div>`:empty(d.studio?'Not assigned to any project yet.':'No Platform Studio access with the current roles.')}</div>`;
    /* tool usage donut */
    const used=d.toolUse.filter(x=>x.runs>0);
    const toolCard=`<div class="ex-card"><div class="ex-sec-h"><div><h4>Tool Usage</h4><p class="ex-sub">Agent runs by Studio tool, last 90 days</p></div></div>
      ${used.length?`<div class="ex-donut-row">${exDonut(used.map((x,i)=>({v:x.runs,c:UD_COLORS[i%UD_COLORS.length]})),d.totalRuns,'Agent runs',140)}<ul class="ex-legend">${used.slice(0,6).map((x,i)=>`<li><i style="background:${UD_COLORS[i%UD_COLORS.length]}"></i>${x.t.name}<b>${x.runs}</b></li>`).join('')}</ul></div>`
        :empty(!d.studio?'No Platform Studio access with the current roles.':d.readOnly?'Read-only access — this user views results but does not run agents.':'No agent runs yet.')}</div>`;
    /* activity line */
    const series=d.readOnly?[{n:'Pages viewed',v:d.views,c:'#a78bfa',area:true}]:[{n:'Agent runs',v:d.weeks,c:'#0e60ff',area:true},{n:'Pages viewed',v:d.views,c:'#a78bfa',dash:true}];
    const mx=Math.max(10,...d.weeks,...d.views); const top=Math.ceil(mx*1.15/10)*10;
    const actCard=`<div class="ex-card"><div class="ex-sec-h"><div><h4>Activity Over Time</h4><p class="ex-sub">Weekly activity across Platform Studio, last 12 weeks</p></div></div>
      ${d.active?chxLine(chxWeeks(12),series,{max:top,steps:4,label:'Weekly activity'})+chxLegend(series.map(s=>[s.n,s.c])):empty(u.status==='pending'?'Activity starts once the account is approved.':'Account is suspended — no recent activity.')}</div>`;
    /* access */
    const accCard=`<div class="ex-card"><div class="ex-sec-h"><div><h4>Tool Access</h4><p class="ex-sub">Studio tools this user can open, granted through their roles</p></div><button class="ex-link" data-go-roles>Manage in Roles</button></div>
      <div class="ud-portals">${portals}</div>
      <div class="ud-tools">${SUITE_TOOLS.map(t=>{ const has=d.toolIds.includes(t.id); return `<div class="ud-tool ${has?'y':'n'}"><span class="ud-tool-ic">${typeof toolIco==='function'?toolIco(t.icon,15):exI('chip',15)}</span><b>${t.name}</b><em>${has?(d.readOnly?'View only':'Full access'):'No access'}</em></div>`; }).join('')}</div></div>`;
    const permCard=`<div class="ex-card"><div class="ex-sec-h"><h4>Roles &amp; Permissions</h4>${u.you?'':exBtn('Edit Roles','edit','sm ex-edit','ud-roles2')}</div>
      <div class="ex-chips">${rs.map((x,i)=>`<span class="ex-rchip">${exI('shieldok',13)}${roleName(x)}${i===0?'<em>Primary</em>':''}</span>`).join('')}</div>
      <div class="ex-sub-h">Access Permissions</div><ul class="ex-perms">${uxPerms(u).map(p=>`<li class="${p[1]?'y':'n'}">${exI(p[1]?'check':'x',11)}${p[0]}</li>`).join('')}</ul></div>`;
    /* projects table */
    const tbl=`<div class="ex-card"><div class="ex-sec-h"><div><h4>Projects</h4><p class="ex-sub">Projects this user works on in Platform Studio</p></div></div>
      ${d.projects.length?`<div class="ex-table-wrap"><table class="ex-table"><thead><tr><th>Project</th><th>Type</th><th>Team</th><th>Role</th><th>Progress</th><th>Hours</th><th>Agent Runs</th><th class="r"></th></tr></thead><tbody>${d.projects.map(x=>{ const pr=typeof projectProgress==='function'?projectProgress(x.p):0; return `<tr><td><b class="ink">${exEsc(x.p.name)}</b></td><td class="mut">${x.p.type==='brownfield'?'Brownfield':'Greenfield'}</td><td class="mut">${exEsc(x.p.team||'—')}</td><td>${x.role}</td><td><div class="ex-prog"><div class="ex-bar"><i style="width:${pr}%;background:#0e60ff"></i></div><span>${pr}%</span></div></td><td>${x.hours}h</td><td>${x.runs}</td><td class="r">${exBtn('Open','chevR','sm tint','',`data-open-proj="${x.p.id}"`)}</td></tr>`; }).join('')}</tbody></table></div>`:empty(d.studio?'Not assigned to any project yet.':'No Platform Studio access with the current roles.')}</div>`;
    const act=`<div class="ex-card"><div class="ex-sec-h"><h4>Recent Activity</h4></div><div class="ex-act">${uxActivity(u).concat(d.projects.slice(0,2).map((x,i)=>[(d.readOnly?'Viewed report for ':'Worked on ')+x.p.name,['Yesterday','2 days ago'][i]])).map(a=>`<div><span class="ex-act-ic">${exI('shieldok',13)}</span><b>${exEsc(a[0])}</b><small>${a[1]}</small></div>`).join('')}</div></div>`;
    const kpis=`<div class="ex-kpis k5">
      ${exKpi('folder','t-blue',d.projects.length,'Projects Involved',d.studio?'In Platform Studio':'No Studio access')}
      ${exKpi('chip','t-violet',d.totalRuns,'Agent Runs','Last 90 days')}
      ${exKpi('grid','t-teal',d.toolIds.length+'<small>/'+SUITE_TOOLS.length+'</small>','Tools With Access',d.readOnly?'View only':'Through assigned roles')}
      ${exKpi('clock','t-green',d.hours+'h','Hours Contributed','≈ '+d.saved+'h saved with AI')}
      ${exKpi('pulse','t-amber',d.success,'Run Success Rate','Last login: '+exEsc(u.last||'—'))}
    </div>`;
    return `<div class="ud-top"><button class="ex-btn" id="ud-back">${exI('arrowL',15)}Back to Users</button><nav class="ud-crumbs"><a data-crumb>Users &amp; Roles</a><span>/</span><b>${exEsc(u.name)}</b></nav></div>
      <div class="ex-card ud-hero">
        <div class="ud-id">${uxAvatar(u,true)}<div><h2>${exEsc(u.name)} ${uxStatus(u.status)}</h2><p>${exEsc(u.title||'')} · ${exEsc(u.dept||'')}</p>
          <div class="ud-meta"><span>${exI('mail',13)}${exEsc(u.email)}</span><span>${exI('pin',13)}${exEsc(u.location||'—')}</span><span>${exI('user',13)}Manager: ${exEsc(u.manager||'—')}</span><span>${exI('clock',13)}Joined ${u.joined?exDate(u.joined):'—'}</span><span>${uxLic(u)}</span></div></div></div>
        ${u.you?'':`<div class="ud-actions">${exBtn('Edit User','edit','primary ex-edit','ud-edit')}${exBtn('Edit Roles','shield','ex-edit','ud-roles')}${exBtn('Change License','idcard','ex-edit','ud-lic')}${exBtn('Reset Password','key','ex-edit','ud-pw')}
          ${u.status==='approved'?exBtn('Suspend User','lock','warn ex-edit','ud-sus'):exBtn(u.status==='pending'?'Approve User':'Reactivate User','check','primary ex-edit','ud-app')}${exBtn('Remove User','x','danger ex-edit','ud-del')}</div>`}
      </div>
      ${kpis}
      <div class="ex-grid g-2">${projCard}${toolCard}</div>
      <div class="ex-grid g-2">${actCard}${accCard}</div>
      ${tbl}
      <div class="ex-grid g-2">${permCard}${act}</div>`;
  }
  function udRender(root,u){
    root.innerHTML=udPage(u);
    const on=(s,fn)=>{ const el=root.querySelector(s); if(el) el.onclick=fn; };
    const back=()=>{ UX.detail=null; entRenderUsers(); const m=document.querySelector('main'); if(m) m.scrollTop=0; window.scrollTo(0,0); };
    on('#ud-back',back); on('[data-crumb]',back);
    const ed=f=>{ UX.edit=u.id; UX.editFocus=f; entRenderUsers(); }; on('#ud-edit',()=>ed(null)); on('#ud-roles',()=>ed('roles')); on('#ud-roles2',()=>ed('roles'));
    on('#ud-lic',()=>ed('license'));
    on('#ud-pw',()=>exModal('Reset Password',`Send a password reset link to ${exEsc(u.email)}? Their current sessions stay signed in until the link is used.`,'','<button class="um-btn" data-close>Cancel</button><button class="um-btn primary" id="ud-pw-go">Send Reset Link</button>',(m,close)=>{ m.querySelector('#ud-pw-go').onclick=()=>{ close(); exToast('Password reset link sent to '+u.email); }; }));
    on('#ud-sus',()=>exModal('Suspend User',`Suspend ${exEsc(u.name)}? They can't sign in to either portal until reactivated. Their license stays assigned.`,'','<button class="um-btn" data-close>Cancel</button><button class="um-btn primary" id="ud-sus-go">Suspend User</button>',(m,close)=>{ m.querySelector('#ud-sus-go').onclick=()=>{ u.status='suspended'; close(); entRenderUsers(); exToast(u.name+' suspended'); }; }));
    on('#ud-app',()=>{ u.status='approved'; entRenderUsers(); exToast(u.name+' is now active'); });
    on('#ud-del',()=>exModal('Remove User',`Remove ${exEsc(u.name)} from GlobalTech Solutions? Their license goes back to the pool.`,'','<button class="um-btn" data-close>Cancel</button><button class="um-btn primary" id="ud-del-go">Remove User</button>',(m,close)=>{ m.querySelector('#ud-del-go').onclick=()=>{ USERS.splice(USERS.indexOf(u),1); UX.detail=null; close(); entRenderUsers(); exToast(u.name+' removed'); }; }));
    on('[data-go-roles]',()=>gotoTop('roles'));
    root.querySelectorAll('[data-open-proj]').forEach(b=>b.onclick=()=>{
      const id=b.dataset.openProj;
      if(SESSION.portal==='studio' && typeof openProjectDetail==='function'){ openProjectDetail(id); return; }
      if(canEnterPortal(SESSION.user,'studio')) exModal('Open in Platform Studio','Projects live in Platform Studio. Switch portals to open this project?','','<button class="um-btn" data-close>Cancel</button><button class="um-btn primary" id="ud-sw">Switch &amp; Open</button>',(m,close)=>{ m.querySelector('#ud-sw').onclick=()=>{ close(); const sw=$('#portal-switch'); if(sw) sw.click(); setTimeout(()=>{ if(typeof openProjectDetail==='function') openProjectDetail(id); },400); }; });
      else exToast('Projects open in Platform Studio, which your roles don’t include');
    });
  }

  /* ═══════════ IN-PAGE FORMS (edit pages instead of modals) ═══════════ */
  function xfField(f){
    const id='xf_'+f.k, req=f.req?'<i class="xf-req">*</i>':'', hint=f.hint?`<small class="xf-hint">${f.hint}</small>`:'';
    const lab=`<label class="xf-lab" for="${id}">${f.label}${req}</label>`;
    const v=f.val==null?'':f.val;
    let ctl='';
    if(f.type==='select') ctl=`<select class="xf-in" id="${id}" data-k="${f.k}" ${f.ro?'disabled':''}>${f.opts.map(o=>{ const ov=Array.isArray(o)?o[0]:o, ol=Array.isArray(o)?o[1]:o; return `<option value="${exEsc(ov)}"${String(ov)===String(v)?' selected':''}>${exEsc(ol)}</option>`; }).join('')}</select>`;
    else if(f.type==='textarea') ctl=`<textarea class="xf-in" id="${id}" data-k="${f.k}" rows="${f.rows||4}" placeholder="${exEsc(f.ph||'')}" ${f.ro?'readonly':''}>${exEsc(v)}</textarea>`;
    else if(f.type==='toggle') return `<div class="xf-f xf-toggle${f.full?' full':''}"><div><b>${f.label}</b>${f.hint?`<small>${f.hint}</small>`:''}</div><label class="xf-sw"><input type="checkbox" data-k="${f.k}" ${v?'checked':''} ${f.ro?'disabled':''}><span></span></label></div>`;
    else if(f.type==='radio') ctl=`<div class="xf-radio">${f.opts.map(o=>`<label class="xf-rc${String(o[0])===String(v)?' on':''}"><input type="radio" name="${id}" data-k="${f.k}" value="${exEsc(o[0])}" ${String(o[0])===String(v)?'checked':''}><b>${o[1]}</b>${o[2]?`<small>${o[2]}</small>`:''}</label>`).join('')}</div>`;
    else if(f.type==='checks') ctl=`<div class="xf-checks">${f.opts.map(o=>`<label class="xf-ck"><input type="checkbox" data-k="${f.k}" value="${exEsc(o[0])}" ${(v||[]).includes(o[0])?'checked':''}><span><b>${o[1]}</b>${o[2]?`<small>${o[2]}</small>`:''}</span></label>`).join('')}</div>`;
    else if(f.type==='rows') ctl=`<div class="xf-rows">${f.opts.map((o,i)=>`<div class="xf-row"><span>${exI(f.icon||'git',14)}${exEsc(o.name)}</span><select class="xf-in sm" data-k="${f.k}" data-i="${i}">${f.choices.map(c=>`<option${c===o.val?' selected':''}>${c}</option>`).join('')}</select></div>`).join('')}</div>`;
    else ctl=`<input class="xf-in" id="${id}" data-k="${f.k}" type="${f.type||'text'}" value="${exEsc(v)}" placeholder="${exEsc(f.ph||'')}" ${f.ro?'readonly':''} ${f.type==='number'&&f.min!=null?`min="${f.min}"`:''}>`;
    return `<div class="xf-f${f.full||['textarea','radio','checks','rows'].includes(f.type)?' full':''}${f.ro?' ro':''}">${lab}${ctl}${hint}<small class="xf-err" hidden></small></div>`;
  }
  function exFormPage(root,cfg){
    root.innerHTML=`<div class="ud-top"><button class="ex-btn" id="xf-back">${exI('arrowL',15)}${cfg.backLabel||'Back'}</button><nav class="ud-crumbs">${(cfg.crumbs||[]).map((c,i,a)=>i<a.length-1?`<a data-xc="${i}">${c}</a><span>/</span>`:`<b>${c}</b>`).join('')}</nav></div>
      <div class="ex-head"><div><h2>${cfg.title}</h2><p>${cfg.sub||''}</p></div></div>
      <form class="xf xf-panel${cfg.layout?' xf-'+cfg.layout:''}" novalidate>
        ${cfg.sections.map((s,si)=>`<section class="xf-sec" id="xf-sec-${s.id||si}"><div class="xf-sec-h"><h4>${s.icon?exI(s.icon,16):''}${s.title}</h4>${s.desc?`<p>${s.desc}</p>`:''}</div><div class="xf-grid">${s.fields.map(xfField).join('')}</div></section>`).join('')}
        <div class="xf-foot"><span class="xf-note">${exI('info',14)}<span>${cfg.note||'Fields marked * are required.'}</span></span><div class="xf-btns"><button type="button" class="ex-btn" id="xf-cancel">Cancel</button><button type="submit" class="ex-btn primary ex-edit" id="xf-save">${exI('check',15)}${cfg.saveLabel||'Save Changes'}</button></div></div>
      </form>`;
    const form=root.querySelector('form');
    form.querySelectorAll('.xf-rc input').forEach(r=>r.onchange=()=>{ r.closest('.xf-radio').querySelectorAll('.xf-rc').forEach(x=>x.classList.toggle('on',x.contains(r))); });
    const back=()=>{ cfg.onBack(); const m=document.querySelector('main'); if(m) m.scrollTop=0; window.scrollTo(0,0); };
    root.querySelector('#xf-back').onclick=back; root.querySelector('#xf-cancel').onclick=back;
    root.querySelectorAll('[data-xc]').forEach(a=>a.onclick=()=>{ const fn=(cfg.crumbFns||[])[+a.dataset.xc]; fn?fn():back(); });
    form.onsubmit=e=>{ e.preventDefault();
      const vals={}; const all=cfg.sections.flatMap(s=>s.fields);
      all.forEach(f=>{ const els=[...form.querySelectorAll(`[data-k="${f.k}"]`)];
        if(f.type==='toggle') vals[f.k]=els[0].checked;
        else if(f.type==='checks') vals[f.k]=els.filter(x=>x.checked).map(x=>x.value);
        else if(f.type==='radio') vals[f.k]=(els.find(x=>x.checked)||{}).value;
        else if(f.type==='rows') vals[f.k]=els.map(x=>x.value);
        else vals[f.k]=(els[0].value||'').trim(); });
      let bad=null; form.querySelectorAll('.xf-err').forEach(x=>{x.hidden=true;x.parentElement.classList.remove('err');});
      const fail=(k,msg)=>{ const el=form.querySelector(`[data-k="${k}"]`); const box=el&&el.closest('.xf-f'); if(box){ box.classList.add('err'); const er=box.querySelector('.xf-err'); er.textContent=msg; er.hidden=false; if(!bad) bad=box; } };
      all.forEach(f=>{ const v=vals[f.k];
        if(f.req && (v==null||v===''||(Array.isArray(v)&&!v.length))) fail(f.k, f.type==='checks'?'Choose at least one.':'This field is required.');
        else if(f.type==='email'&&v&&!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(v)) fail(f.k,'Enter a valid email address.');
        else if(f.validate){ const m=f.validate(v,vals); if(m) fail(f.k,m); } });
      if(bad){ bad.scrollIntoView({behavior:'smooth',block:'center'}); exToast('Check the highlighted fields'); return; }
      cfg.onSave(vals); back(); };
    if(cfg.focus){ const s=root.querySelector('#xf-sec-'+cfg.focus); if(s) setTimeout(()=>{ s.scrollIntoView({behavior:'smooth',block:'start'}); s.classList.add('xf-flash'); },80); }
    else { const m=document.querySelector('main'); if(m) m.scrollTop=0; window.scrollTo(0,0); }
  }

  /* ── Users: Edit User page ── */
  function udEditPage(root,u,focus){
    const depts=[...new Set(USERS.map(x=>x.dept).filter(Boolean))].sort();
    exFormPage(root,{title:'Edit User',sub:`Update ${exEsc(u.name)}’s profile, license and roles.`,backLabel:'Back to User',
      crumbs:['Users &amp; Roles',exEsc(u.name),'Edit'],crumbFns:[()=>{UX.edit=null;UX.detail=null;entRenderUsers();},()=>{UX.edit=null;entRenderUsers();}],
      focus,onBack:()=>{UX.edit=null;entRenderUsers();},
      sections:[
        {id:'profile',title:'Profile',icon:'user',desc:'Basic details shown across both portals.',fields:[
          {k:'name',label:'Full Name',req:true,val:u.name},{k:'email',label:'Work Email',type:'email',req:true,val:u.email,validate:v=>USERS.some(x=>x!==u&&x.email.toLowerCase()===v.toLowerCase())?'Another user already has this email.':null},
          {k:'title',label:'Job Title',val:u.title},{k:'dept',label:'Department',type:'select',opts:depts,val:u.dept},
          {k:'manager',label:'Manager',type:'select',opts:['—'].concat(USERS.filter(x=>x!==u&&x.status==='approved').map(x=>x.name).sort()),val:u.manager},
          {k:'phone',label:'Phone',type:'tel',val:u.phone},{k:'location',label:'Location',val:u.location}]},
        {id:'license',title:'License',icon:'idcard',desc:'The license this user consumes. Changes apply immediately.',fields:[
          {k:'license',label:'License Type',type:'radio',val:u.license,opts:[['workstation','Workstation','Builds and runs work in Platform Studio'],['viewer','Viewer','Read-only dashboards and reports'],['admin','Admin','Administers the organization']]}]},
        {id:'roles',title:'Roles &amp; Status',icon:'shield',desc:'Access is the combination of every role a person holds.',fields:[
          {k:'roles',label:'Roles',type:'checks',req:true,val:userRoles(u),opts:USER_ROLES.map(r=>[r.value,r.label,[ROLE_DEF[r.value].access.enterprise?'Enterprise':null,ROLE_DEF[r.value].access.studio?'Studio':null].filter(Boolean).join(' + ')||'—'])},
          {k:'status',label:'Account Status',type:'select',val:u.status,opts:[['approved','Active'],['pending','Pending'],['suspended','Suspended']]}]}
      ],
      onSave:v=>{ Object.assign(u,{name:v.name,email:v.email,title:v.title,dept:v.dept,manager:v.manager,phone:v.phone,location:v.location,license:v.license,status:v.status,roles:v.roles,role:v.roles[0]}); exToast(u.name+' updated'); }});
  }

  /* ── Integrations: detail page + configure / connect page ── */
  function intDetailPage(root,i){
    const [lab]=intAction(i), conn=i.status==='connected';
    const items=conn?(1200+(i.id.length*317)%4800):0;
    root.innerHTML=`<div class="ud-top"><button class="ex-btn" id="ix-back">${exI('arrowL',15)}Back to Integrations</button><nav class="ud-crumbs"><a data-ix-list>Integrations</a><span>/</span><b>${i.name}</b></nav></div>
      <div class="ex-card ud-hero"><div class="ud-id">${intLogo(i)}<div><h2>${i.name} ${intSt(i.status)}</h2><p>${i.sub} · ${INT_CATS.find(c=>c[0]===i.cat)[1]}</p><div class="ud-meta"><span>${exI('info',13)}${i.desc}</span></div></div></div>
        <div class="ud-actions">${conn?exBtn('Edit Configuration','edit','primary ex-edit','ixd-edit')+exBtn('Test Connection','pulse','','ixd-test')+exBtn('Sync Now','history','ex-edit','ixd-sync')+exBtn('Disconnect','x','danger ex-edit','ixd-dc'):exBtn(lab+' '+i.name,'link','primary ex-edit','ixd-edit')}</div></div>
      ${conn?`<div class="ex-kpis">${exKpi('history','t-green',i.sync,'Last Sync','Every '+(i.freq||'5 minutes'))}${exKpi('db','t-blue',items.toLocaleString(),'Items Synced','Across all projects')}${exKpi('git','t-violet',i.access.length,i.cat==='dev'?'Repositories':'Workspaces',i.access.filter(r=>r.full).length+' with full access')}${exKpi('alert','t-amber',0,'Sync Errors','Last 7 days')}</div>
      <div class="ex-grid g-2"><div class="ex-card"><div class="ex-sec-h"><h4>Connection</h4><button class="ex-link ex-edit" data-ixe="connection">Edit</button></div><div class="ex-kv">
        <div><span>Workspace</span><b>${exEsc(i.ws||'globaltech')}</b></div><div><span>Auth Method</span><b>${exEsc(i.auth||'OAuth app')}</b></div><div><span>Connected By</span><b>${i.by}</b></div><div><span>Connected On</span><b>${i.on}</b></div><div><span>Project Scope</span><b>${exEsc(i.scope||'All projects')}</b></div></div></div>
      <div class="ex-card"><div class="ex-sec-h"><h4>Data Synced</h4><button class="ex-link ex-edit" data-ixe="data">Edit</button></div><ul class="ex-perms">${i.settings.map(s=>`<li class="${s[2]?'y':'n'}">${exI(s[2]?'check':'x',11)}<span><b style="font-weight:500">${s[0]}</b> <span class="mut">— ${s[1]}</span></span></li>`).join('')}</ul></div></div>
      <div class="ex-grid g-2"><div class="ex-card"><div class="ex-sec-h"><h4>${i.cat==='dev'?'Repository':'Workspace'} Access</h4><button class="ex-link ex-edit" data-ixe="access">Edit</button></div><div class="ex-table-wrap"><table class="ex-table"><thead><tr><th>Name</th><th>Access</th></tr></thead><tbody>${i.access.map(r=>`<tr><td>${exI('git',13)} ${r.name}</td><td><span class="ex-st ${r.full?'st-approved':'st-none'}">${r.full?'Full Access':'Read Only'}</span></td></tr>`).join('')}</tbody></table></div></div>
      <div class="ex-card"><div class="ex-sec-h"><h4>Sync History</h4></div><div class="ex-act">${[['Full sync completed',i.sync],['Incremental sync — 214 items','1 hour ago'],['Incremental sync — 98 items','2 hours ago'],['Webhook re-registered','Yesterday']].map(a=>`<div><span class="ex-act-ic">${exI('check',13)}</span><b>${a[0]}</b><small>${a[1]}</small></div>`).join('')}</div></div></div>`
      :`<div class="ex-card ud-empty" style="min-height:220px">${exI('link',26)}<b style="color:var(--ink);font-size:15px">${i.status==='action'?'Reconnect '+i.name+' to resume syncing':i.status==='setup'?'Finish setting up '+i.name:i.name+' is not connected'}</b><span>${i.desc}. Once connected, agents in Platform Studio can use ${i.name} data in the projects you choose.</span>${exBtn(lab+' '+i.name,'link','primary ex-edit','ixd-edit2')}</div>`}`;
    const on=(s,fn)=>{ const el=root.querySelector(s); if(el) el.onclick=fn; };
    const list=()=>{ IX.page=null; entRenderIntegrations(); };
    on('#ix-back',list); on('[data-ix-list]',list);
    const edit=f=>{ IX.edit=i.id; IX.focus=f||null; entRenderIntegrations(); };
    on('#ixd-edit',()=>edit()); on('#ixd-edit2',()=>edit());
    root.querySelectorAll('[data-ixe]').forEach(b=>b.onclick=()=>edit(b.dataset.ixe));
    on('#ixd-test',()=>exToast(i.name+' connection is healthy'));
    on('#ixd-sync',()=>{ i.sync='Just now'; entRenderIntegrations(); exToast(i.name+' sync started'); });
    on('#ixd-dc',()=>exModal('Disconnect '+i.name,'Agents stop syncing data from '+i.name+'. You can reconnect later.','','<button class="um-btn" data-close>Cancel</button><button class="um-btn primary" id="ix-dc2">Disconnect</button>',(m,close)=>{ m.querySelector('#ix-dc2').onclick=()=>{ i.status='none'; i.sync=null; close(); entRenderIntegrations(); exToast(i.name+' disconnected'); }; }));
  }
  function intEditPage(root,i){
    const conn=i.status==='connected', projs=(typeof PROJECTS!=='undefined'&&Array.isArray(PROJECTS))?PROJECTS:[];
    exFormPage(root,{title:conn?'Edit '+i.name+' Configuration':(i.status==='action'?'Reconnect ':i.status==='setup'?'Configure ':'Connect ')+i.name,
      sub:conn?'Change how '+i.name+' connects and what it syncs into Platform Studio.':'Authorise Xccelera AI to read from '+i.name+' for GlobalTech Solutions.',
      backLabel:'Back',crumbs:['Integrations',i.name,conn?'Edit':'Connect'],crumbFns:[()=>{IX.edit=null;IX.page=null;entRenderIntegrations();},()=>{IX.edit=null;entRenderIntegrations();}],
      focus:IX.focus,saveLabel:conn?'Save Configuration':'Authorise & Connect',onBack:()=>{IX.edit=null;IX.page=i.id;entRenderIntegrations();},
      sections:[
        {id:'connection',title:'Connection',icon:'link',desc:'Where Xccelera AI connects and how it signs in.',fields:[
          {k:'ws',label:i.cat==='dev'?'Organization / Workspace':'Workspace',req:true,val:i.ws||'globaltech'},
          {k:'url',label:'Base URL',val:i.url||'',ph:'Leave empty for the cloud service',hint:'Only needed for self-hosted servers.'},
          {k:'auth',label:'Auth Method',type:'select',val:i.auth||'OAuth app',opts:['OAuth app','Personal access token','Service account']},
          {k:'token',label:'Access Token / Client Secret',type:'password',val:'',ph:conn?'•••••••• (unchanged)':'Paste token',hint:'Stored encrypted. Leave empty to keep the current one.'}]},
        {id:'sync',title:'Sync Schedule',icon:'history',desc:'How often data is pulled and which projects can use it.',fields:[
          {k:'freq',label:'Sync Frequency',type:'select',val:i.freq||'5 minutes',opts:['5 minutes','15 minutes','1 hour','6 hours','Daily']},
          {k:'scope',label:'Project Scope',type:'select',val:i.scope||'All projects',opts:['All projects','Selected projects only']},
          {k:'projects',label:'Selected Projects',type:'checks',val:i.projects||[],opts:projs.map(p=>[p.id,p.name,p.team||'']),hint:'Used when scope is “Selected projects only”.'}]},
        {id:'data',title:'Data to Sync',icon:'db',desc:'Choose what agents are allowed to read.',fields:i.settings.map((s,k)=>({k:'set'+k,label:s[0],hint:s[1],type:'toggle',val:s[2]}))},
        {id:'access',title:(i.cat==='dev'?'Repository':'Workspace')+' Access',icon:'git',desc:'Per-'+(i.cat==='dev'?'repository':'workspace')+' permission for agents.',fields:[
          {k:'acc',label:'Access Levels',type:'rows',opts:i.access.map(r=>({name:r.name,val:r.full?'Full Access':'Read Only'})),choices:['Full Access','Read Only','No Access']}]}
      ],
      onSave:v=>{ Object.assign(i,{ws:v.ws,url:v.url,auth:v.auth,freq:v.freq,scope:v.scope,projects:v.projects});
        i.settings.forEach((s,k)=>s[2]=v['set'+k]);
        i.access=i.access.map((r,k)=>({name:r.name,full:v.acc[k]==='Full Access',val:v.acc[k]})).filter((r,k)=>v.acc[k]!=='No Access');
        if(!conn){ i.status='connected'; i.sync='Just now'; i.by=SESSION.user?SESSION.user.name:'Admin'; i.on=new Date().toLocaleString('en-US',{month:'short',day:'numeric',year:'numeric',hour:'numeric',minute:'2-digit'}); exToast(i.name+' connected'); }
        else exToast(i.name+' configuration saved'); }});
  }

  /* ── Security: Edit Security Settings page ── */
  SEC.cfg = SEC.cfg || {provider:'Microsoft Entra ID',protocol:'SAML 2.0',ssoUrl:'https://login.microsoftonline.com/globaltech/saml2',entity:'urn:xccelera:globaltech',cert:'',mfaMethods:['app','key'],ipList:'203.0.113.0/24\n198.51.100.0/24',residency:'United Kingdom (eu-west-2)',retention:'12 months',models:['claude','gpt','llama']};
  function secEditPage(root,focus){
    const P=SEC.policies, c=SEC.cfg;
    exFormPage(root,{title:'Edit Security Settings',sub:'Authentication, access, data protection and AI governance for GlobalTech Solutions.',
      crumbs:['Security &amp; Governance','Edit Settings'],backLabel:'Back to Security',focus,saveLabel:'Save Security Settings',
      note:'Changes apply to every user at their next sign-in.',onBack:()=>{SEC.edit=null;entRenderSecurity();},
      sections:[
        {id:'sso',title:'Single Sign-On',icon:'key',desc:'Sign users in through your identity provider.',fields:[
          {k:'sso',label:'Enforce SSO for the organization',type:'toggle',val:P[1][1],full:true},
          {k:'provider',label:'Identity Provider',type:'select',val:c.provider,opts:['Microsoft Entra ID','Okta','Google Workspace','Ping Identity','OneLogin']},
          {k:'protocol',label:'Protocol',type:'select',val:c.protocol,opts:['SAML 2.0','OpenID Connect']},
          {k:'ssoUrl',label:'Sign-in URL',type:'url',req:true,val:c.ssoUrl},{k:'entity',label:'Entity ID / Client ID',req:true,val:c.entity},
          {k:'cert',label:'Signing Certificate',type:'textarea',rows:3,val:c.cert,ph:'-----BEGIN CERTIFICATE-----',hint:'Leave empty to keep the current certificate.'}]},
        {id:'mfa',title:'Multi-Factor Authentication',icon:'finger',desc:'Extra verification at sign-in.',fields:[
          {k:'mfa',label:'Require MFA for all users',type:'toggle',val:P[0][1],full:true},
          {k:'mfaMethods',label:'Allowed Methods',type:'checks',val:c.mfaMethods,opts:[['app','Authenticator app'],['key','Security key (FIDO2)'],['sms','SMS code','Least secure']],validate:(v,all)=>all.mfa&&!v.length?'Choose at least one method while MFA is required.':null}]},
        {id:'session',title:'Sessions &amp; Network',icon:'clock',desc:'Session length and where users can sign in from.',fields:[
          {k:'timeout',label:'Session Timeout',type:'select',val:P[3][1],opts:[['15','15 minutes'],['30','30 minutes'],['60','60 minutes'],['120','2 hours']]},
          {k:'device',label:'Require device trust',type:'toggle',val:P[5][1]},
          {k:'personal',label:'Allow personal email domains',type:'toggle',val:P[4][1]},
          {k:'ip',label:'Restrict access by IP address',type:'toggle',val:P[2][1]},
          {k:'ipList',label:'Allowed IP Ranges',type:'textarea',rows:3,val:c.ipList,hint:'One CIDR range per line.',validate:(v,all)=>all.ip&&!v.trim()?'Add at least one range while IP restriction is on.':(v.split(/\n/).filter(x=>x.trim()&&!/^\d{1,3}(\.\d{1,3}){3}(\/\d{1,2})?$/.test(x.trim())).length?'Use CIDR format, e.g. 203.0.113.0/24.':null)}]},
        {id:'data',title:'Data Protection',icon:'lock',desc:'Where data lives and how long it is kept.',fields:[
          {k:'residency',label:'Data Residency',type:'select',val:c.residency,opts:['United Kingdom (eu-west-2)','European Union (eu-west-1)','India (ap-south-1)','Singapore (ap-southeast-1)']},
          {k:'retention',label:'Data Retention',type:'select',val:c.retention,opts:['3 months','6 months','12 months','24 months','Indefinite']},
          {k:'export',label:'Enable data export restrictions',type:'toggle',val:P[6][1],full:true}]},
        {id:'ai',title:'AI Governance',icon:'chip',desc:'Which models agents may use.',fields:[
          {k:'block',label:'Block unauthorized AI models',type:'toggle',val:P[7][1],full:true},
          {k:'models',label:'Approved Models',type:'checks',req:true,val:c.models,opts:[['claude','Claude'],['gpt','GPT-4o'],['llama','Llama 3'],['gemini','Gemini'],['mistral','Mistral']]}]}
      ],
      onSave:v=>{ P[1][1]=v.sso;P[0][1]=v.mfa;P[3][1]=v.timeout;P[5][1]=v.device;P[4][1]=v.personal;P[2][1]=v.ip;P[6][1]=v.export;P[7][1]=v.block;
        Object.assign(c,{provider:v.provider,protocol:v.protocol,ssoUrl:v.ssoUrl,entity:v.entity,cert:v.cert||c.cert,mfaMethods:v.mfaMethods,ipList:v.ipList,residency:v.residency,retention:v.retention,models:v.models});
        SEC.data[1][1]=v.residency; SEC.data[2][1]='Project data retained for '+v.retention;
        SEC.log.unshift(['Just now',SESSION.user?SESSION.user.name:'Admin','Changed security settings','Success','203.0.113.24']); exToast('Security settings saved'); }});
  }

