  let ruleSearch='';
  let ruleSort='confidence';
  const collapsedGroups=new Set();
  const openRules=new Set();

  function highlightMatch(text, q){
    if(!q) return text;
    const idx = text.toLowerCase().indexOf(q.toLowerCase());
    if(idx===-1) return text;
    return text.slice(0,idx) + '<mark>' + text.slice(idx, idx+q.length) + '</mark>' + text.slice(idx+q.length);
  }
  function sortRules(rules){
    const arr=[...rules];
    if(ruleSort==='confidence') arr.sort((a,b)=>b.weight-a.weight);
    else if(ruleSort==='uses') arr.sort((a,b)=>b.uses-a.uses);
    else if(ruleSort==='recent') arr.sort((a,b)=>new Date(b.lastApplied)-new Date(a.lastApplied));
    return arr;
  }
  function renderRules(){
    const q = ruleSearch.trim().toLowerCase();
    const groups = RULE_GROUPS.map(g=>({...g, rules: sortRules(g.rules).filter(r=>!q || r.text.toLowerCase().includes(q) || r.tags.some(t=>t.includes(q)))}))
                              .filter(g=>g.rules.length>0);

    const totalMatched = groups.reduce((s,g)=>s+g.rules.length,0);
    const totalAll = RULE_GROUPS.reduce((s,g)=>s+g.rules.length,0);
    $('#rules-count').textContent = q ? `${totalMatched} of ${totalAll} rules match` : `${totalAll} active rules across ${RULE_GROUPS.length} tools`;

    if(!groups.length){
      $('#rules-groups').innerHTML = `<div class="rules-empty">No learned rules match "${ruleSearch}" — try a different keyword.</div>`;
      return;
    }

    $('#rules-groups').innerHTML = groups.map(g=>{
      const rowKey = i=>g.key+'-'+i;
      return `
      <div class="rule-group ${collapsedGroups.has(g.key)?'collapsed':''}" data-group="${g.key}">
        <div class="rg-head" data-toggle-group="${g.key}">
          <span class="ico">${svgIco(g.key,15)}</span><h3>${g.name}</h3>
          <span class="cnt">${g.rules.length} rule${g.rules.length===1?'':'s'}</span>
          <svg class="chev" viewBox="0 0 24 24" fill="none" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m6 9 6 6 6-6"/></svg>
        </div>
        <div class="rule-rows">
          ${g.rules.map((r,i)=>`
            <div class="rule-row ${openRules.has(rowKey(i))?'open':''}" data-row="${rowKey(i)}">
              <div class="rr-main" data-toggle-row="${rowKey(i)}">
                <span class="rchk"><svg viewBox="0 0 24 24" fill="none" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="m5 12 5 5L20 7"/></svg></span>
                <div class="rtxt">${highlightMatch(r.text, q)}
                  <div class="rmeta">
                    <span>Confidence ${(r.weight*100).toFixed(0)}%</span>
                    <span>·</span>
                    <span>Applied ${r.uses}× so far</span>
                    <span>·</span>
                    <span>Last applied ${r.lastApplied}</span>
                  </div>
                </div>
                <svg class="rexp" viewBox="0 0 24 24" fill="none" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m6 9 6 6 6-6"/></svg>
              </div>
              <div class="rdetail">
                <div class="rdetail-grid">
                  <div class="dd"><div class="k">First learned</div><div class="v">${r.firstSeen}</div></div>
                  <div class="dd"><div class="k">Last applied</div><div class="v">${r.lastApplied}</div></div>
                </div>
                <div class="rdetail-tags">${r.tags.map(t=>`<span>${t}</span>`).join('')}</div>
              </div>
            </div>`).join('')}
        </div>
      </div>`;
    }).join('');

    $$('#rules-groups [data-toggle-group]').forEach(el=>el.onclick=()=>{
      const k=el.dataset.toggleGroup;
      collapsedGroups.has(k)?collapsedGroups.delete(k):collapsedGroups.add(k);
      renderRules();
    });
    $$('#rules-groups [data-toggle-row]').forEach(el=>el.onclick=()=>{
      const k=el.dataset.toggleRow;
      openRules.has(k)?openRules.delete(k):openRules.add(k);
      renderRules();
    });
  }

